window.CARDS=window.CARDS||{};CARDS["story-v-y1v10-index"]=[{"i":"sc-ayanokouji-kiyotaka-y1v10-p6-1","v":"y1v10","y":1,"o":12,"k":"","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka prologue  hirata s monologue mentioned by hirata as someone he may be similar to   a shadow  not the center of class","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v10-p6-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v10-p6-1\">Prologue: Hirata’s monologue<\/a><\/span><span class=\"meta\">Y1V10 · p.6–10<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Mentioned by Hirata as someone he may be similar to — a shadow, not the center of class.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v10-p12-1\">→ After: Ch.1: Exam results and the hallway encounter<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v10-p6-1","v":"y1v10","y":1,"o":12,"k":"inner spoken","w":"horikita-suzune hirata-yousuke","q":"hirata yosuke prologue  hirata s monologue hirata s first person retrospective  protecting his class became his duty  he was originally a shadow  like ayanokoji  to protect my important friends  i have to protect the class  if i can protect the class  i can protect my friends  a childhood friend was bullied without him noticing and attempted suicide  that day changed his life  the class was being pinned down because they were making the wrong choices  the fights within the class itself have disappeared  but at the same time  so did the smiles  the scene shows classmates watching him with surprise  he tells horikita to shut up   horikita  can you shut up a bit  vulgar and full of violence  classmates including horikita san look at him strangely  at the very end of this worst special exam   i  i  tells horikita to shut up  she looks at him strangely","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v10-p6-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v10-p6-1\">Prologue: Hirata’s monologue<\/a><\/span><span class=\"meta\">Y1V10 · p.6–10<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Hirata’s first-person retrospective: protecting his class became his duty; he was originally a shadow, like Ayanokōji. The scene shows classmates watching him with surprise; he tells Horikita to shut up. Vulgar and full of violence; classmates including Horikita-san look at him strangely. At the very end of this worst special exam; “I, I—”<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q inner\"><b class=\"sp\">Hirata Yōsuke<\/b> To protect my important friends, I have to protect the class. If I can protect the class, I can protect my friends.<span class=\"pg\">p.6<\/span><\/li><li class=\"q inner\"><b class=\"sp\">Hirata Yōsuke<\/b> The class was being pinned down because they were making the wrong choices. The fights within the class itself have disappeared, but at the same time, so did the smiles.<span class=\"pg\">p.7<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “Horikita… can you shut up a bit.”<span class=\"pg\">p.7<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Backstory<\/span> A childhood friend was bullied without him noticing and attempted suicide; that day changed his life.<span class=\"pg\">p.6<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Tells Horikita to shut up; she looks at him strangely.<span class=\"pg\">p.7–8<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v10-p12-1\">→ After: Ch.1: Exam results and the hallway encounter<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y1v10-p6-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"hirata-yousuke horikita-suzune","q":"horikita suzune prologue  hirata s monologue hirata tells horikita to shut up  classmates including horikita san look at him strangely   horikita  can you shut up a bit  looks at him strangely after his outburst","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v10-p6-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v10-p6-1\">Prologue: Hirata’s monologue<\/a><\/span><span class=\"meta\">Y1V10 · p.6–10<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Hirata tells Horikita to shut up; classmates including Horikita-san look at him strangely.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “Horikita… can you shut up a bit.”<span class=\"pg\">p.7<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Looks at him strangely after his outburst.<span class=\"pg\">p.7–8<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v10-p12-1\">→ After: Ch.1: Exam results and the hallway encounter<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v10-p12-1","v":"y1v10","y":1,"o":12,"k":"action inner spoken","w":"nagumo-miyabi horikita-manabu horikita-suzune ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 1  exam results and the hallway encounter encounters nagumo and manabu in the hallway  nagumo tests him about forum rumors   well  i have no idea  but at the end of the day  they ve caused me nothing but trouble  horikita watches from a distance  nagumo reveals he called her here  horikita asks what was discussed  he tells her to face her brother before he graduates   don t you want to try and face him at least once before he graduates  nagumo tests him about forum rumors  he deflects  manabu backs him up against nagumo  tells her to face her brother  she refuses  uses the time between classes for a bathroom break and encounters nagumo and horikita manabu in the hallway on the way back   somehow   is that so  straightens up in response to nagumo s remark about attitude toward the student council president   i m not particularly interested  ultimately  i don t have the time to be worrying about my upperclassmen  looks over his shoulder and sees horikita suzune watching from a distance   are you the one who called her here  nagumo   you don t understand anything  there s no way that my brother would look after me  going out of my way to approach him when i know i would be treated cruelly is just plain stupid   really  well  maybe you re right  it was a difficult conversation for her  she becomes docile and meek like a lamb in front of her brother  it would be meaningless if she didn t have the courage to face him herself","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v10-p12-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v10-p12-1\">Ch.1: Exam results and the hallway encounter<\/a><\/span><span class=\"meta\">Y1V10 · p.12–29<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Encounters Nagumo and Manabu in the hallway; Nagumo tests him about forum rumors. Horikita watches from a distance; Nagumo reveals he called her here. Horikita asks what was discussed; he tells her to face her brother before he graduates. Looks over his shoulder and sees Horikita Suzune watching from a distance.<\/p><p class=\"with\">with <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Well, I have no idea. But at the end of the day, they’ve caused me nothing but trouble.”<span class=\"pg\">p.15<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Don’t you want to try and face him at least once before he graduates?”<span class=\"pg\">p.22<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Somehow.”<span class=\"pg\">p.15<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Nagumo tests him about forum rumors; he deflects.<span class=\"pg\">p.14–20<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Manabu backs him up against Nagumo.<span class=\"pg\">p.14–21<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Tells her to face her brother; she refuses.<span class=\"pg\">p.22–23<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Uses the time between classes for a bathroom break and encounters Nagumo and Horikita Manabu in the hallway on the way back.<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Is that so?”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Straightens up in response to Nagumo’s remark about attitude toward the student council president.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m not particularly interested. Ultimately, I don’t have the time to be worrying about my upperclassmen.”<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you the one who called her here, Nagumo?”<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You don’t understand anything. There’s no way that my brother would look after me. Going out of my way to approach him when I know I would be treated cruelly is just plain stupid.”<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Really? Well, maybe you’re right.”<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> It was a difficult conversation for her; she becomes docile and meek like a lamb in front of her brother.<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> It would be meaningless if she didn’t have the courage to face him herself.<span class=\"pg\">p.23<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v10-p6-1\">← Before: Prologue: Hirata’s monologue<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v10-p30-1\">→ After: Ch.2: The Class Vote<\/button><\/div><\/article>"},{"i":"sc-chabashira-sae-y1v10-p12-1","v":"y1v10","y":1,"o":12,"k":"action spoken","w":"horikita-suzune ike-kanji sudou-ken chabashira-sae","q":"chabashira sae ch 1  exam results and the hallway encounter announces exam results  red line of fate  zero expulsions  praises the class   everyone  this next special exam will be the last one this year  reveals next special exam on march 8  watches hirata encourage the class  present in hallway during nagumo manabu conversation  not directly involved  horikita came third  tutored sudo in english  the encouragement line  everyone  this next special exam will be the last one this year  let s all work together and try our best  if we do  our class should be able to aim for class a without anyone being expelled  is spoken by hirata as he addresses the class  spreads a large piece of paper on the blackboard and draws the red line of fate   calm yourself  you ll know in a couple of minutes   are you feeling confident  ike   you studied hard  huh  yet you re still so uneasy   sudo  you always seem to be in the running for the lowest score  so how are you feeling   the results this time   everyone successfully passed the exam  these have been your best results so far   sudo  this past year  you managed to improve your grades better than anyone  you seemed confident that you d pass as well  i m looking forward to seeing how you ll succeed in the future  reports that all classes passed and class c came in 3rd by average score   i have to hand it to you guys  it may be a simple thing to say  but well done   nevertheless ike  you re getting a bit too excited  special exams aside  at an academic level  it s only natural for you to pass an exam like this one  and besides  this exam wasn t nearly as difficult as other national level exams  cuts into the cheerful atmosphere to announce the next special exam  scheduled for march 8th   most of you were probably already aware of this  but just because you ve finished this end of term exam doesn t mean that testing has finished for the year  there will be a particularly important special exam soon  and as in previous years  it s scheduled to begin on march 8th  reveals a relieved smile as the class responds to hirata s encouragement   the way things have been going recently  i m starting to think that all of you might just be able to graduate together two years from now   but don t get too cocky  your last exam is only a week away  and by no means will it be easy  questions ike about confidence and notes he came in last but passed  praises sudo s improvement and confidence","h":"<article class=\"card\" id=\"sc-chabashira-sae-y1v10-p12-1\"><h3><span class=\"ttl\"><a href=\"../../../people/chabashira-sae.html#sc-chabashira-sae-y1v10-p12-1\">Ch.1: Exam results and the hallway encounter<\/a><\/span><span class=\"meta\">Y1V10 · p.12–29<\/span><span class=\"by\">notes on <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/span><\/h3><p class=\"setup\">Announces exam results; red line of fate; zero expulsions; praises the class. Reveals next special exam on March 8; watches Hirata encourage the class. Present in hallway during Nagumo-Manabu conversation (not directly involved). Reports that all classes passed and Class C came in 3rd by average score. Cuts into the cheerful atmosphere to announce the next special exam, scheduled for March 8th. Reveals a relieved smile as the class responds to Hirata’s encouragement.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Chabashira Sae<\/b> “Everyone. This next special exam will be the last one this year.”<span class=\"pg\">p.13<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Chabashira Sae<\/b> “Calm yourself. You’ll know in a couple of minutes.”<span class=\"pg\">p.12<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Chabashira Sae<\/b> “Are you feeling confident, Ike?”<span class=\"pg\">p.12<\/span><\/li><\/ul><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Horikita came third; tutored Sudō in English.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The encouragement line “Everyone. This next special exam will be the last one this year. Let’s all work together and try our best. If we do, our class should be able to aim for class A without anyone being expelled.” is spoken by Hirata as he addresses the class.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Spreads a large piece of paper on the blackboard and draws the red line of fate.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You studied hard, huh? Yet you’re still so uneasy?”<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sudō, you always seem to be in the running for the lowest score, so how are you feeling?”<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The results this time-”<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Everyone successfully passed the exam. These have been your best results so far.”<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sudō. This past year, you managed to improve your grades better than anyone. You seemed confident that you’d pass as well. I’m looking forward to seeing how you’ll succeed in the future.”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have to hand it to you guys. It may be a simple thing to say, but well done.”<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nevertheless Ike, you’re getting a bit too excited. Special exams aside, at an academic level, it’s only natural for you to pass an exam like this one. And besides, this exam wasn’t nearly as difficult as other national-level exams.”<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Most of you were probably already aware of this, but just because you’ve finished this end-of-term exam doesn’t mean that testing has finished for the year. There will be a particularly important special exam soon, and as in previous years, it’s scheduled to begin on March 8th.”<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The way things have been going recently, I’m starting to think that all of you might just be able to graduate together two years from now.”<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But don’t get too cocky. Your last exam is only a week away, and by no means will it be easy.”<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Questions Ike about confidence and notes he came in last but passed.<span class=\"pg\">p.12–14<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Praises Sudō’s improvement and confidence.<span class=\"pg\">p.13–15<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y1v10-p30-1\">→ After: Ch.2: The Class Vote<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v10-p12-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"horikita-suzune nagumo-miyabi horikita-manabu hirata-yousuke","q":"hirata yosuke ch 1  exam results and the hallway encounter exam results announced  chabashira praises the class  no expulsions  chabashira reveals next special exam on march 8  hirata encourages the class   let s all work together and try our best  if we do  our class should be able to aim for class a without anyone being expelled  hirata and horikita encounter nagumo and manabu in the hallway  nagumo tests ayanokoji about forum rumors   let s all work together and try our best  if we do  our class should be able to aim for class a without anyone being expelled  nagumo invites horikita suzune to the student council  she rejects  horikita asks what nagumo and manabu discussed  ayanokoji tells her to face her brother   you don t understand anything  there s no way that my brother would look after me  tells her to face her brother before he graduates  she refuses  present during nagumo s encounter with manabu and horikita  present during nagumo s conversation with manabu","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v10-p12-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v10-p12-1\">Ch.1: Exam results and the hallway encounter<\/a><\/span><span class=\"meta\">Y1V10 · p.12–29<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Exam results announced; Chabashira praises the class; no expulsions. Chabashira reveals next special exam on March 8; Hirata encourages the class. Hirata and Horikita encounter Nagumo and Manabu in the hallway; Nagumo tests Ayanokōji about forum rumors. Nagumo invites Horikita Suzune to the student council; she rejects. Horikita asks what Nagumo and Manabu discussed; Ayanokōji tells her to face her brother.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “Let’s all work together and try our best. If we do, our class should be able to aim for class A without anyone being expelled.”<span class=\"pg\">p.13<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “Let’s all work together and try our best. If we do, our class should be able to aim for class A without anyone being expelled.”<span class=\"pg\">p.19<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “You don’t understand anything. There’s no way that my brother would look after me.”<span class=\"pg\">p.23<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Tells her to face her brother before he graduates; she refuses.<span class=\"pg\">p.22–23<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Present during Nagumo’s encounter with Manabu and Horikita.<span class=\"pg\">p.14–20<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Present during Nagumo’s conversation with Manabu.<span class=\"pg\">p.14–21<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v10-p6-1\">← Before: Prologue: Hirata’s monologue<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v10-p30-1\">→ After: Ch.2: The Class Vote<\/button><\/div><\/article>"},{"i":"sc-horikita-manabu-y1v10-p12-1","v":"y1v10","y":1,"o":12,"k":"action spoken","w":"nagumo-miyabi horikita-suzune ayanokouji-kiyotaka horikita-manabu","q":"horikita manabu ch 1  exam results and the hallway encounter manabu and nagumo are seen talking in the hallway  ayanokoji encounters them  manabu backs ayanokoji up against nagumo s questioning   it s as ayanokoji says  nagumo  you should refrain from saying anything too carelessly  nagumo invites horikita suzune to the student council  manabu dismisses the idea   don t use blood relationships as a means to evaluate somebody s capabilities  nagumo tells manabu to cherish time with his sister  manabu leaves  nagumo says taking down manabu is his only objective  nagumo competes with him  says taking him down is his only objective  dismisses the idea of evaluating her by blood relationship  backs ayanokoji up against nagumo  looks calmly in ayanokoji s direction when nagumo greets him   what s your goal here nagumo   i ll say this now just so we re clear  but you had better not be thinking that you can use my sister to force a concession from me   for the sake of getting what you want  i think you d do anything   are you satisfied  nagumo  senses the conversation has reached its conclusion and leaves without saying another word","h":"<article class=\"card\" id=\"sc-horikita-manabu-y1v10-p12-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-manabu.html#sc-horikita-manabu-y1v10-p12-1\">Ch.1: Exam results and the hallway encounter<\/a><\/span><span class=\"meta\">Y1V10 · p.12–29<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/span><\/h3><p class=\"setup\">Manabu and Nagumo are seen talking in the hallway; Ayanokōji encounters them. Manabu backs Ayanokōji up against Nagumo’s questioning. Nagumo invites Horikita Suzune to the student council; Manabu dismisses the idea. Nagumo tells Manabu to cherish time with his sister; Manabu leaves. Nagumo says taking down Manabu is his only objective.<\/p><p class=\"with\">with <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Manabu<\/b> “It’s as Ayanokōji says, Nagumo. You should refrain from saying anything too carelessly.”<span class=\"pg\">p.16<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Manabu<\/b> “Don’t use blood relationships as a means to evaluate somebody’s capabilities.”<span class=\"pg\">p.18<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Manabu<\/b> “What’s your goal here Nagumo?”<span class=\"pg\">p.18<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Nagumo competes with him; says taking him down is his only objective.<span class=\"pg\">p.14–21<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Dismisses the idea of evaluating her by blood relationship.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Backs Ayanokōji up against Nagumo.<span class=\"pg\">p.15–16<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Looks calmly in Ayanokōji’s direction when Nagumo greets him.<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll say this now just so we’re clear, but you had better not be thinking that you can use my sister to force a concession from me.”<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “For the sake of getting what you want, I think you’d do anything.”<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you satisfied, Nagumo?”<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Senses the conversation has reached its conclusion and leaves without saying another word.<span class=\"pg\">p.20<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-manabu-y1v10-p162-1\">→ After: Ch.4: Meeting and strategy<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y1v10-p12-1","v":"y1v10","y":1,"o":12,"k":"action inner spoken","w":"hirata-yousuke nagumo-miyabi horikita-manabu horikita-suzune","q":"horikita suzune ch 1  exam results and the hallway encounter exam results announced  horikita came third  she tutored sudo in english  nagumo invites her to the student council  she rejects  nagumo declares he will be actively involved with her  asks ayanokoji what nagumo and manabu discussed  ayanokoji tells her to face her brother   you don t understand anything  there s no way that my brother would look after me  she enrolled in the same school to watch over her brother  she becomes docile and meek in front of him  he tells her to face her brother before he graduates  she refuses  nagumo invites her to the student council  she rejects  she says there s no way her brother would look after her  writes down everyone s scores after the results are announced   it s the result of his own hard work after all  all i did was thoroughly break down each of his weaknesses until he started to see success   it looks like ike kun and yamauchi kun still have a bit of space between their scores and the red line  it was probably the right decision for us to routinely hold study sessions  if a certain you know who next to me would actually put in the smallest amount of effort  our class s average score might go up a little bit more  now wouldn t it   i m not going to accept that  one day i m going to make you take this seriously  watches the hallway conversation between nagumo  manabu  and ayanokoji from a distance   the one who sent me this email  was it you  president nagumo   yes  my name is horikita suzune   that s right  i am not fit to be a member of the student council   i m sorry  if you ll excuse me  attempts to get out of the conversation and quickly hurries back to the classroom   president nagumo and my brother  what were they talking about   that s   so what   if my brother s interested in anyone  it s unpleasant  but he s only interested in you","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v10-p12-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v10-p12-1\">Ch.1: Exam results and the hallway encounter<\/a><\/span><span class=\"meta\">Y1V10 · p.12–29<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Exam results announced; Horikita came third; she tutored Sudō in English. Nagumo invites her to the student council; she rejects; Nagumo declares he will be actively involved with her. Asks Ayanokōji what Nagumo and Manabu discussed; Ayanokōji tells her to face her brother. Watches the hallway conversation between Nagumo, Manabu, and Ayanokōji from a distance.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “You don’t understand anything. There’s no way that my brother would look after me.”<span class=\"pg\">p.23<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “It’s the result of his own hard work after all. All I did was thoroughly break down each of his weaknesses until he started to see success.”<span class=\"pg\">p.17<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “It looks like Ike-kun and Yamauchi-kun still have a bit of space between their scores and the red line. It was probably the right decision for us to routinely hold study sessions. If a certain you-know-who next to me would…”<span class=\"pg\">p.17<\/span><\/li><\/ul><details class=\"more\"><summary>16 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Inner voice<\/span> She enrolled in the same school to watch over her brother; she becomes docile and meek in front of him.<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> He tells her to face her brother before he graduates; she refuses.<span class=\"pg\">p.22–23<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Nagumo invites her to the student council; she rejects.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> She says there’s no way her brother would look after her.<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Writes down everyone’s scores after the results are announced.<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It looks like Ike-kun and Yamauchi-kun still have a bit of space between their scores and the red line. It was probably the right decision for us to routinely hold study sessions. If a certain you-know-who next to me would actually put in the smallest amount of effort, our class’s average score might go up a little bit more, now wouldn’t it?”<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m not going to accept that. One day I’m going to make you take this seriously.”<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…The one who sent me this email… Was it you, president Nagumo?”<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes… my name is Horikita Suzune.”<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…That’s right. I am not fit to be a member of the student council.”<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m sorry. If you’ll excuse me.”<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Attempts to get out of the conversation and quickly hurries back to the classroom.<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “President Nagumo and my brother… what were they talking about?”<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s…”<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So what?”<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If my brother’s interested in anyone… it’s unpleasant, but he’s only interested in you.”<span class=\"pg\">p.23<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v10-p6-1\">← Before: Prologue: Hirata’s monologue<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v10-p30-1\">→ After: Ch.2: The Class Vote<\/button><\/div><\/article>"},{"i":"sc-inogashira-kokoro-y1v10-p12-1","v":"y1v10","y":1,"o":12,"k":"","w":"inogashira-kokoro","q":"inogashira kokoro ch 1  exam results inogashira mentioned  sudo came just above inogashira  inogashira mentioned among the lowest scorers","h":"<article class=\"card\" id=\"sc-inogashira-kokoro-y1v10-p12-1\"><h3><span class=\"ttl\"><a href=\"../../../people/inogashira-kokoro.html#sc-inogashira-kokoro-y1v10-p12-1\">Ch.1: Exam results<\/a><\/span><span class=\"meta\">Y1V10 · p.12–19<\/span><span class=\"by\">notes on <a href=\"../../../people/inogashira-kokoro.html\">Inogashira Kokoro<\/a><\/span><\/h3><p class=\"setup\">Inogashira mentioned; Sudō came just above Inogashira. Inogashira mentioned among the lowest scorers.<\/p><\/article>"},{"i":"sc-kouenji-rokusuke-y1v10-p12-1","v":"y1v10","y":1,"o":12,"k":"","w":"kouenji-rokusuke","q":"koenji rokusuke ch 1  exam results koenji came second  his test results fluctuate  possibly slacking off when not worth his time","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y1v10-p12-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y1v10-p12-1\">Ch.1: Exam results<\/a><\/span><span class=\"meta\">Y1V10 · p.12–19<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><p class=\"setup\">Kōenji came second; his test results fluctuate; possibly slacking off when not worth his time.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y1v10-p30-1\">→ After: Ch.2: The Class Vote<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y1v10-p12-1","v":"y1v10","y":1,"o":12,"k":"action spoken","w":"horikita-manabu horikita-suzune ayanokouji-kiyotaka nagumo-miyabi","q":"nagumo miyabi ch 1  exam results and the hallway encounter nagumo and manabu are seen talking in the hallway  nagumo spots ayanokoji  nagumo tests ayanokoji about the forum rumors  manabu backs ayanokoji up   in order to divert attention away from the slander that had been going around about ichinose honami  it seems that someone went and posted a bunch of rumors about various first year students on the school forums  nagumo invites horikita suzune to the student council  she rejects   if it s my senpai s little sister  i can have her take over as the student council president after i graduate  nagumo tells manabu to cherish time with his sister  manabu leaves   i would cherish the time i have left with my little sister if i were you  nagumo says taking down manabu is his only objective   of course  taking down horikita senpai is the only objective i have left at this school  nagumo competes with manabu  says taking him down is his only objective  invites her to the student council  she rejects  tests ayanokoji about forum rumors  spots ayanokoji and waves at him  preventing him from slipping away   yo ayanokoji  did you manage to pass the end of term exam   how cold  i don t think that s the right attitude to have when the student council president is right in front of you   well  whatever  you ve come by at just the right time  there s something i ve been wanting to ask you   so  what have you two celebrities been talking about   just having a little discussion with horikita senpai  ain t that right   tomorrow  a step ahead of the other school years  the third year students will begin a decisive battle that will determine whether horikita senpai will successfully graduate from class a or not  so i wanted to hear about it from him personally  are you interested too   how cold  you re acting like that just because you re horikita senpai s favorite  aren t you   don t delude yourself  ayanokoji  all that preferential treatment doesn t make you special  you just got lucky with the environment you were placed in  that s right  it s all thanks to that watchful  anxious classmate of yours right over there   come here   well  not exactly  but close enough  you re horikita senpai s little sister  right   i didn t expect my predecessor s little sister to get placed in class d after enrollment  i was surprised   i just wanted to meet with you and your little sister   concession  certainly not  do you really think that i d ever make a move on her  such a cute underclassman and moreover my senpai s precious little sister   even so  you don t have to be so distant do you  if only you had told me about your sister earlier  if you had  i would ve been able to invite her to the student council much sooner   this meeting is just for introductions  i ll invite you again another day   good grief  of course this isn t enough to get him to take me seriously   i would cherish the time i have left with my little sister if i were you   is it really so important for you to compete with the former president like this   well  what i do will depend on the details of the exam and horikita senpai himself   will there be any problems with next week s special exam on your end  president nagumo  i wouldn t expect the second years to have it easy either   well  i wonder  just carry on  hoping for my inevitable failure","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v10-p12-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nagumo-miyabi.html#sc-nagumo-miyabi-y1v10-p12-1\">Ch.1: Exam results and the hallway encounter<\/a><\/span><span class=\"meta\">Y1V10 · p.12–29<\/span><span class=\"by\">notes on <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/span><\/h3><p class=\"setup\">Nagumo and Manabu are seen talking in the hallway; Nagumo spots Ayanokōji. Nagumo tests Ayanokōji about the forum rumors; Manabu backs Ayanokōji up. Nagumo invites Horikita Suzune to the student council; she rejects. Nagumo tells Manabu to cherish time with his sister; Manabu leaves. Nagumo says taking down Manabu is his only objective.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “In order to divert attention away from the slander that had been going around about Ichinose Honami, it seems that someone went and posted a bunch of rumors about various first-year students on the school forums.”<span class=\"pg\">p.15<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “If it’s my senpai’s little sister, I can have her take over as the student council president after I graduate.”<span class=\"pg\">p.18<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “I would cherish the time I have left with my little sister if I were you.”<span class=\"pg\">p.20<\/span><\/li><\/ul><details class=\"more\"><summary>26 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Of course. Taking down Horikita-senpai is the only objective I have left at this school.”<span class=\"pg\">p.21<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Nagumo competes with Manabu; says taking him down is his only objective.<span class=\"pg\">p.14–21<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Invites her to the student council; she rejects.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Tests Ayanokōji about forum rumors.<span class=\"pg\">p.14–15<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Spots Ayanokōji and waves at him, preventing him from slipping away.<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yo Ayanokōji. Did you manage to pass the end-of-term exam?”<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How cold. I don’t think that’s the right attitude to have when the student council president is right in front of you.”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, whatever. You’ve come by at just the right time. There’s something I’ve been wanting to ask you.”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, what have you two celebrities been talking about?”<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Just having a little discussion with Horikita-senpai. Ain’t that right?”<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Tomorrow, a step ahead of the other school years, the third-year students will begin a decisive battle that will determine whether Horikita-senpai will successfully graduate from Class A or not. So I wanted to hear about it from him personally. Are you interested too?”<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How cold. You’re acting like that just because you’re Horikita-senpai’s favorite, aren’t you?”<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t delude yourself, Ayanokōji. All that preferential treatment doesn’t make you special. You just got lucky with the environment you were placed in. That’s right… It’s all thanks to that watchful, anxious classmate of yours right over there.”<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Come here.”<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, not exactly, but close enough. You’re Horikita-senpai’s little sister, right?”<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I didn’t expect my predecessor’s little sister to get placed in Class D after enrollment. I was surprised.”<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I just wanted to meet with you and your little sister.”<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Concession? Certainly not! Do you really think that I’d ever make a move on her? Such a cute underclassman and moreover my senpai’s precious little sister?”<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even so, you don’t have to be so distant do you? If only you had told me about your sister earlier. If you had, I would’ve been able to invite her to the student council much sooner.”<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This meeting is just for introductions. I’ll invite you again another day.”<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Good grief. Of course this isn’t enough to get him to take me seriously.”<span class=\"pg\">p.21<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I would cherish the time I have left with my little sister if I were you.”<span class=\"pg\">p.21<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is it really so important for you to compete with the former president like this?”<span class=\"pg\">p.21<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, what I do will depend on the details of the exam and Horikita-senpai himself.”<span class=\"pg\">p.21<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Will there be any problems with next week’s special exam on your end, president Nagumo? I wouldn’t expect the second-years to have it easy either.”<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, I wonder. Just carry on, hoping for my inevitable failure.”<span class=\"pg\">p.22<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v10-p97-1\">→ After: Ch.3: Ichinose’s deal<\/button><\/div><\/article>"},{"i":"sc-satou-maya-y1v10-p12-1","v":"y1v10","y":1,"o":12,"k":"","w":"satou-maya","q":"sato maya ch 1  exam results sato mentioned among the lowest scorers  hondo  sato  inogashira after yamauchi","h":"<article class=\"card\" id=\"sc-satou-maya-y1v10-p12-1\"><h3><span class=\"ttl\"><a href=\"../../../people/satou-maya.html#sc-satou-maya-y1v10-p12-1\">Ch.1: Exam results<\/a><\/span><span class=\"meta\">Y1V10 · p.12–19<\/span><span class=\"by\">notes on <a href=\"../../../people/satou-maya.html\">Satō Maya<\/a><\/span><\/h3><p class=\"setup\">Satō mentioned among the lowest scorers (Hondō, Satō, Inogashira after Yamauchi).<\/p><\/article>"},{"i":"sc-sudou-ken-y1v10-p12-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"horikita-suzune sudou-ken","q":"sudo ken ch 1  exam results sudo shows confidence  chabashira praises his improvement  he came just above inogashira   i m confident at the very least  i absolutely won t get a failing grade  chabashira notes sudo improved more than anyone  his weakest subject was english  horikita tutored him  his english improved substantially   heh  it s nothing special  looks pleased with how well he did despite brushing it off","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v10-p12-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y1v10-p12-1\">Ch.1: Exam results<\/a><\/span><span class=\"meta\">Y1V10 · p.12–19<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"setup\">Sudō shows confidence; Chabashira praises his improvement; he came just above Inogashira. Chabashira notes Sudō improved more than anyone; his weakest subject was English.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “I’m confident at the very least. I absolutely won’t get a failing grade.”<span class=\"pg\">p.13<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “Heh. It’s nothing special.”<span class=\"pg\">p.13<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Horikita tutored him; his English improved substantially.<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Looks pleased with how well he did despite brushing it off.<span class=\"pg\">p.13<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v10-p30-1\">→ After: Ch.2: The Class Vote<\/button><\/div><\/article>"},{"i":"sc-yamauchi-haruki-y1v10-p12-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ike-kanji yamauchi-haruki","q":"yamauchi haruki ch 1  exam results yamauchi came second to last  just above ike   i only studied a little bit the day before and i still managed to pass  yamauchi and ike joke around after passing   is that so  wahahaha  jokes with ike after both barely pass","h":"<article class=\"card\" id=\"sc-yamauchi-haruki-y1v10-p12-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamauchi-haruki.html#sc-yamauchi-haruki-y1v10-p12-1\">Ch.1: Exam results<\/a><\/span><span class=\"meta\">Y1V10 · p.12–19<\/span><span class=\"by\">notes on <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a><\/span><\/h3><p class=\"setup\">Yamauchi came second-to-last; just above Ike. Yamauchi and Ike joke around after passing.<\/p><p class=\"with\">with <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yamauchi Haruki<\/b> “I only studied a little bit the day before and I still managed to pass.”<span class=\"pg\">p.15<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yamauchi Haruki<\/b> “Is that so? Wahahaha!”<span class=\"pg\">p.15<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Jokes with Ike after both barely pass.<span class=\"pg\">p.15<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamauchi-haruki-y1v10-p30-1\">→ After: Ch.2: The Class Vote<\/button><\/div><\/article>"},{"i":"sc-yukimura-teruhiko-y1v10-p12-1","v":"y1v10","y":1,"o":12,"k":"","w":"yukimura-teruhiko","q":"yukimura teruhiko ch 1  exam results keisei came first in the exam  praised for diligence","h":"<article class=\"card\" id=\"sc-yukimura-teruhiko-y1v10-p12-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yukimura-teruhiko.html#sc-yukimura-teruhiko-y1v10-p12-1\">Ch.1: Exam results<\/a><\/span><span class=\"meta\">Y1V10 · p.12–19<\/span><span class=\"by\">notes on <a href=\"../../../people/yukimura-teruhiko.html\">Yukimura Teruhiko<\/a><\/span><\/h3><p class=\"setup\">Keisei came first in the exam; praised for diligence.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yukimura-teruhiko-y1v10-p30-1\">→ After: Ch.2: The Class Vote<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v10-p30-1","v":"y1v10","y":1,"o":12,"k":"inner","w":"horikita-suzune ryuuen-kakeru karuizawa-kei yukimura-teruhiko ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 2  the class vote chabashira announces the supplementary exam  the class is tense  koenji provokes sudo  hirata mediates  horikita and ayanokoji discuss the cruelty of the exam  ayanokoji group at cafe  keisei proposes mutual praise votes  keisei identifies koenji  ike  yamauchi  sudo as likely censure targets  horikita visits ryuen  he claims he could survive if he wanted  ryuen sees through horikita s weakness  ryuen reveals he accepted defeat by ishizaki  horikita says ryuen is doomed  ayanokoji agrees  kei calls ayanokoji  she has a group of seven girls  kei and ayanokoji discuss likely censure targets  ayanokoji intends to accept whatever outcome the class reaches  the exam is cruel  the class had always cooperated until now  he intends to accept whatever outcome the class reaches  discusses exam cruelty  leaves with her  horikita visits ryuen  he sees through her  phone call  she has seven girl group  keisei proposes mutual praise votes","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v10-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v10-p30-1\">Ch.2: The Class Vote<\/a><\/span><span class=\"meta\">Y1V10 · p.30–84<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Chabashira announces the supplementary exam; the class is tense. Kōenji provokes Sudō; Hirata mediates. Horikita and Ayanokōji discuss the cruelty of the exam. Ayanokōji Group at cafe: Keisei proposes mutual praise votes. Keisei identifies Kōenji, Ike, Yamauchi, Sudō as likely censure targets. Horikita visits Ryūen; he claims he could survive if he wanted. Ryūen sees through Horikita’s weakness. Ryūen reveals he accepted defeat by Ishizaki. Horikita says Ryūen is doomed; Ayanokōji agrees. Kei calls Ayanokōji; she has a group of seven girls. Kei and Ayanokōji discuss likely censure targets. Ayanokōji intends to accept whatever outcome the class reaches.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a> · <a href=\"../../../people/yukimura-teruhiko.html\">Yukimura Teruhiko<\/a><\/p><ul class=\"lines\"><li class=\"q inner\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> The exam is cruel; the class had always cooperated until now.<span class=\"pg\">p.50<\/span><\/li><li class=\"q inner\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> He intends to accept whatever outcome the class reaches.<span class=\"pg\">p.79<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Discusses exam cruelty; leaves with her.<span class=\"pg\">p.50, 73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Horikita visits Ryūen; he sees through her.<span class=\"pg\">p.58–74<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Phone call; she has seven-girl group.<span class=\"pg\">p.75–79<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> Keisei proposes mutual praise votes.<span class=\"pg\">p.52–57<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v10-p12-1\">← Before: Ch.1: Exam results and the hallway encounter<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v10-p85-1\">→ After: Ch.3: Morning conversations and after-school meetings<\/button><\/div><\/article>"},{"i":"sc-chabashira-sae-y1v10-p30-1","v":"y1v10","y":1,"o":12,"k":"","w":"chabashira-sae","q":"chabashira sae ch 2  the class vote announces the supplementary exam  the class is tense  explains  the class poll  rules  explains abstention is prohibited  20 million points can override expulsion  explains revote if all totals are zero  explains protection points and 20 million point override","h":"<article class=\"card\" id=\"sc-chabashira-sae-y1v10-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/chabashira-sae.html#sc-chabashira-sae-y1v10-p30-1\">Ch.2: The Class Vote<\/a><\/span><span class=\"meta\">Y1V10 · p.30–84<\/span><span class=\"by\">notes on <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/span><\/h3><p class=\"setup\">Announces the supplementary exam; the class is tense. Explains “The Class Poll” rules. Explains abstention is prohibited; 20 million points can override expulsion. Explains revote if all totals are zero. Explains protection points and 20 million point override.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y1v10-p12-1\">← Before: Ch.1: Exam results and the hallway encounter<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y1v10-p197-1\">→ After: Ch.5: Observing the class discussion<\/button><\/div><\/article>"},{"i":"sc-hasebe-haruka-y1v10-p30-1","v":"y1v10","y":1,"o":12,"k":"","w":"ayanokouji-kiyotaka hasebe-haruka","q":"hasebe haruka ch 2  the class vote haruka sighs about the exam  discusses with ayanokoji group  haruka notes the school wants expulsions  haruka asks about ryuen s situation  haruka says it s pitiful ryuen might be forced out  haruka asks ayanokoji to check on horikita visiting ryuen  discusses exam strategy  asks him to watch over horikita","h":"<article class=\"card\" id=\"sc-hasebe-haruka-y1v10-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hasebe-haruka.html#sc-hasebe-haruka-y1v10-p30-1\">Ch.2: The Class Vote<\/a><\/span><span class=\"meta\">Y1V10 · p.30–84<\/span><span class=\"by\">notes on <a href=\"../../../people/hasebe-haruka.html\">Hasebe Haruka<\/a><\/span><\/h3><p class=\"setup\">Haruka sighs about the exam; discusses with Ayanokōji Group. Haruka notes the school wants expulsions. Haruka asks about Ryūen’s situation. Haruka says it’s pitiful Ryūen might be forced out. Haruka asks Ayanokōji to check on Horikita visiting Ryūen.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Discusses exam strategy; asks him to watch over Horikita.<span class=\"pg\">p.52–65<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hasebe-haruka-y1v10-p85-1\">→ After: Ch.3: Group chat strategy<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v10-p30-1","v":"y1v10","y":1,"o":12,"k":"","w":"horikita-suzune kouenji-rokusuke ryuuen-kakeru karuizawa-kei yukimura-teruhiko hirata-yousuke","q":"hirata yosuke ch 2  the class vote chabashira announces the supplementary exam  the class is tense   the class poll    each student casts 3 praise and 3 censure votes  last place expelled  protection points as reward for top student  censure votes determine last place  hirata asks about abstention  chabashira says it s prohibited  horikita proposes fixing the vote by spreading votes equally  chabashira says it s impossible  revote if all zero  koenji provokes sudo  hirata mediates  horikita silences sudo  koenji claims hidden strength matters  horikita and ayanokoji discuss the cruelty of the exam  ayanokoji group at cafe  keisei proposes mutual praise votes among five  airi worries about being targeted  keisei says to avoid standing out  keisei identifies koenji  ike  yamauchi  sudo as likely censure targets  group discusses ryuen s hopeless situation  horikita visits ryuen  he claims he could survive if he wanted  ryuen sees through horikita s weakness  says her class made her complacent  ryuen reveals he accepted his defeat by ishizaki  horikita provokes him  horikita and ayanokoji leave  she says ryuen is doomed  kei calls ayanokoji  she has a group of seven girls  he advises low profile  kei and ayanokoji discuss likely censure targets  ayanokoji intends to accept whatever outcome the class reaches  horikita proposes vote strategy  silences sudo  discusses cruelty of exam with ayanokoji  koenji provokes sudo  claims hidden strength  horikita visits ryuen  he sees through her  accepts defeat  phone call  she has seven girl group  he advises low profile  keisei proposes mutual praise votes","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v10-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v10-p30-1\">Ch.2: The Class Vote<\/a><\/span><span class=\"meta\">Y1V10 · p.30–84<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Chabashira announces the supplementary exam; the class is tense. “The Class Poll” — each student casts 3 praise and 3 censure votes; last place expelled. Protection points as reward for top student; censure votes determine last place. Hirata asks about abstention; Chabashira says it’s prohibited. Horikita proposes fixing the vote by spreading votes equally; Chabashira says it’s impossible (revote if all zero). Kōenji provokes Sudō; Hirata mediates. Horikita silences Sudō; Kōenji claims hidden strength matters. Horikita and Ayanokōji discuss the cruelty of the exam. Ayanokōji Group at cafe: Keisei proposes mutual praise votes among five. Airi worries about being targeted; Keisei says to avoid standing out. Keisei identifies Kōenji, Ike, Yamauchi, Sudō as likely censure targets. Group discusses Ryūen’s hopeless situation. Horikita visits Ryūen; he claims he could survive if he wanted. Ryūen sees through Horikita’s weakness; says her class made her complacent. Ryūen reveals he accepted his defeat by Ishizaki; Horikita provokes him. Horikita and Ayanokōji leave; she says Ryūen is doomed. Kei calls Ayanokōji; she has a group of seven girls; he advises low profile. Kei and Ayanokōji discuss likely censure targets. Ayanokōji intends to accept whatever outcome the class reaches.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a> · <a href=\"../../../people/yukimura-teruhiko.html\">Yukimura Teruhiko<\/a><\/p><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Horikita proposes vote strategy; silences Sudō; discusses cruelty of exam with Ayanokōji.<span class=\"pg\">p.37–50<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Kōenji provokes Sudō; claims hidden strength.<span class=\"pg\">p.42–48<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Horikita visits Ryūen; he sees through her; accepts defeat.<span class=\"pg\">p.58–74<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Phone call; she has seven-girl group; he advises low profile.<span class=\"pg\">p.75–79<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> Keisei proposes mutual praise votes.<span class=\"pg\">p.52–57<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v10-p12-1\">← Before: Ch.1: Exam results and the hallway encounter<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v10-p128-1\">→ After: Ch.3: Conversation in his room<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y1v10-p30-1","v":"y1v10","y":1,"o":12,"k":"inner spoken","w":"hirata-yousuke ryuuen-kakeru ayanokouji-kiyotaka horikita-suzune","q":"horikita suzune ch 2  the class vote chabashira announces  the class poll  horikita proposes fixing votes equally  chabashira says fixing votes is impossible  revote if all zero  koenji provokes sudo  horikita silences him  horikita and ayanokoji discuss the cruelty of the exam  horikita visits ryuen  he claims he could survive if he wanted  ryuen sees through horikita s weakness  says her class made her complacent  ryuen reveals he accepted defeat by ishizaki  horikita provokes him  horikita says ryuen is doomed  ayanokoji agrees  she enrolled to watch over her brother  becomes docile in front of him  the exam is cruel  the class had always cooperated until now  he mediates conflicts  she silences sudo  visits him  he sees through her weakness  discusses exam cruelty  leaves with him   are you implying that there s something wrong with us   if the entire class unites and selects three people for the praise votes and three people for the censure votes  all six of them would end up with a total of zero votes  that way  nobody would end up in last place  isn t that right   isn t that rule strange  if we voted honestly and just so happened to end up with a total of zero votes on each side  the results would still be the same  even if we held another vote  if we forcibly distorted the results after that  it wouldn t feel like the students were chosen by a legitimate evaluation   then  what happens when there s a tie for first or last place   stop nagging me koenji  i don t think we need someone like you  and that s not gonna change   that s enough sudo kun   don t get so carried away just because your grades have improved a little bit   zip it   that took a lot of extra effort   but  things have really become troublesome  despite all the instability and collusion  the class had always been able to cooperate  and yet  they come along and force us to kick someone out  it s far too cruel   you re awfully composed  ryuen kun   i ll be blunt  this new special exam  what are you going to do   in other words  you re saying you ve obediently resigned yourself to drop out of school   the censure votes will be cast for you  while many students may feel guilty about it  the mental burden on everyone would still be far less than it would be if they voted for somebody else   if you really intend on leaving the school  i won t say a word  no  not just me  there are probably many people in class b and class a who want you to disappear as well  for better or worse  you went too far  nobody s willing to lend you a hand   that s an awfully high evaluation of yourself  how typical of you  but even with all that confidence  you ve fallen to class d because of your lack of capability as a leader  haven t you   it doesn t seem like we ll ever be able to understand each other   today might be the last time we ll be able to speak to each other  so is it alright if i ask you a single question   you re in a more desperate situation than anyone else right now  if you put a serious amount of effort into tackling this exam  would you be able to survive and avoid expulsion   that s what i d expect from you  even if you re bluffing  i don t feel anything but confidence from you   there s no need  i m not in the same position you are   thank you  it feels like i may manage to steel my resolve a bit more thanks to you   there will definitely be expulsions because of this supplementary exam  it s an unavoidable fate  so  it s necessary for us to correctly determine the most suitable person to remove  do you understand the weight behind what i m saying   if that s how it ends up  then that would just be the full extent of my capabilities   choosing who to kick out is the only remotely difficult part of the whole thing   i can do that  i ve never shown mercy to anyone who s held my class back  ever since i enrolled here   you  what could you possibly understand about me   you sound like you have it all figured out  but you don t really have a way to save yourself  do you   did you truly lose to a classmate  or was it done by someone outside of your own class   whichever one it is  are you just going to silently accept your loser status and drop out of school  tells ryuen she will keep an eye out to make sure her classmates never waste any praise votes on him   that guy is the physical embodiment of a liar  it s not that he s not struggling to stay enrolled  he s just putting on airs  it doesn t matter though  no matter how much he struggles  he s doomed to drop out of school   impossible  there s no way for ryuen kun to prevent his expulsion  no matter how you look at it  even if he apologized to his class and started being an actually decent human being for once  it wouldn t change how many votes he d get either way   or  perhaps you ve already thought of something  a way for ryuen kun to avoid expulsion   then that s all there is to it","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v10-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v10-p30-1\">Ch.2: The Class Vote<\/a><\/span><span class=\"meta\">Y1V10 · p.30–84<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Chabashira announces “The Class Poll”; Horikita proposes fixing votes equally. Chabashira says fixing votes is impossible (revote if all zero). Kōenji provokes Sudō; Horikita silences him. Horikita and Ayanokōji discuss the cruelty of the exam. Horikita visits Ryūen; he claims he could survive if he wanted. Ryūen sees through Horikita’s weakness; says her class made her complacent. Ryūen reveals he accepted defeat by Ishizaki; Horikita provokes him. Horikita says Ryūen is doomed; Ayanokōji agrees.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Are you implying that there’s something wrong with us?”<span class=\"pg\">p.36<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “If the entire class unites and selects three people for the praise votes and three people for the censure votes, all six of them would end up with a total of zero votes. That way, nobody would end up in last place. Isn’t that…”<span class=\"pg\">p.37<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Isn’t that rule strange? If we voted honestly and just so happened to end up with a total of zero votes on each side, the results would still be the same, even if we held another vote. If we forcibly distorted the results after…”<span class=\"pg\">p.38<\/span><\/li><\/ul><details class=\"more\"><summary>39 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Inner voice<\/span> She enrolled to watch over her brother; becomes docile in front of him.<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> The exam is cruel; the class had always cooperated until now.<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> He mediates conflicts; she silences Sudō.<span class=\"pg\">p.37–50<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Visits him; he sees through her weakness.<span class=\"pg\">p.58–74<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Discusses exam cruelty; leaves with him.<span class=\"pg\">p.50, 73<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If the entire class unites and selects three people for the praise votes and three people for the censure votes, all six of them would end up with a total of zero votes. That way, nobody would end up in last place. Isn’t that right?”<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Isn’t that rule strange? If we voted honestly and just so happened to end up with a total of zero votes on each side, the results would still be the same, even if we held another vote. If we forcibly distorted the results after that, it wouldn’t feel like the students were chosen by a legitimate evaluation.”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Then, what happens when there’s a tie for first or last place?”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Stop nagging me Kōenji. I don’t think we need someone like you, and that’s not gonna change.”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s enough Sudō-kun.”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t get so carried away just because your grades have improved a little bit.”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Zip it.”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That took a lot of extra effort.”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But… things have really become troublesome. Despite all the instability and collusion, the class had always been able to cooperate. And yet, they come along and force us to kick someone out… it’s far too cruel.”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re awfully composed, Ryūen-kun.”<span class=\"pg\">p.66<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll be blunt. This new special exam. What are you going to do?”<span class=\"pg\">p.66<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In other words… you’re saying you’ve obediently resigned yourself to drop out of school?”<span class=\"pg\">p.66<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The censure votes will be cast for you. While many students may feel guilty about it, the mental burden on everyone would still be far less than it would be if they voted for somebody else.”<span class=\"pg\">p.67<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you really intend on leaving the school, I won’t say a word. No, not just me. There are probably many people in Class B and Class A who want you to disappear as well. For better or worse, you went too far. Nobody’s willing to lend you a hand.”<span class=\"pg\">p.67<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s an awfully high evaluation of yourself. How typical of you. But even with all that confidence, you’ve fallen to Class D because of your lack of capability as a leader, haven’t you?”<span class=\"pg\">p.67<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It doesn’t seem like we’ll ever be able to understand each other.”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Today might be the last time we’ll be able to speak to each other, so is it alright if I ask you a single question?”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re in a more desperate situation than anyone else right now. If you put a serious amount of effort into tackling this exam… would you be able to survive and avoid expulsion?”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s what I’d expect from you, even if you’re bluffing. I don’t feel anything but confidence from you.”<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’s no need. I’m not in the same position you are.”<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Thank you. It feels like I may manage to steel my resolve a bit more thanks to you.”<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There will definitely be expulsions because of this supplementary exam. It’s an unavoidable fate. So, it’s necessary for us to correctly determine the most suitable person to remove. Do you understand the weight behind what I’m saying?”<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If that’s how it ends up, then that would just be the full extent of my capabilities.”<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Choosing who to kick out is the only remotely difficult part of the whole thing.”<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…I can do that. I’ve never shown mercy to anyone who’s held my class back, ever since I enrolled here.”<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You… what could you possibly understand about me?”<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You sound like you have it all figured out, but you don’t really have a way to save yourself, do you?”<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Did you truly lose to a classmate, or was it done by someone outside of your own class…?”<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Whichever one it is, are you just going to silently accept your loser status and drop out of school?”<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tells Ryūen she will keep an eye out to make sure her classmates never waste any praise votes on him.<span class=\"pg\">p.78–79<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That guy is the physical embodiment of a liar. It’s not that he’s not struggling to stay enrolled, he’s just putting on airs. It doesn’t matter though. No matter how much he struggles, he’s doomed to drop out of school.”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Impossible. There’s no way for Ryūen-kun to prevent his expulsion, no matter how you look at it. Even if he apologized to his class and started being an actually decent human being for once, it wouldn’t change how many votes he’d get either way.”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Or, perhaps you’ve already thought of something? A way for Ryūen-kun to avoid expulsion?”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then that’s all there is to it.”<span class=\"pg\">p.73<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v10-p12-1\">← Before: Ch.1: Exam results and the hallway encounter<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v10-p152-1\">→ After: Ch.4: Classroom atmosphere<\/button><\/div><\/article>"},{"i":"sc-karuizawa-kei-y1v10-p30-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ayanokouji-kiyotaka karuizawa-kei","q":"karuizawa kei ch 2  the class vote karuizawa calls ayanokoji  she has a group of seven girls   yeah so  this exam  what should i be doing  ayanokoji advises her to keep a low profile  karuizawa and ayanokoji discuss likely censure targets   out of the whole class  i d say that the three idiots and kouenji kun are all kinda terrible  right  phone call  she has seven girl group  he advises low profile","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y1v10-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y1v10-p30-1\">Ch.2: The Class Vote<\/a><\/span><span class=\"meta\">Y1V10 · p.30–84<\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><p class=\"setup\">Karuizawa calls Ayanokōji; she has a group of seven girls. Ayanokōji advises her to keep a low profile. Karuizawa and Ayanokōji discuss likely censure targets.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “Yeah so, this exam. What should I be doing?”<span class=\"pg\">p.75<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “Out of the whole class, I’d say that the three idiots and Kōuenji-kun are all kinda terrible, right?”<span class=\"pg\">p.78<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Phone call; she has seven-girl group; he advises low profile.<span class=\"pg\">p.75–79<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y1v10-p168-1\">→ After: Ch.4: Warning Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y1v10-p30-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"sudou-ken kouenji-rokusuke","q":"koenji rokusuke ch 2  the class vote koenji provokes sudo  claims unnecessary students should be removed   wrong  this special exam has its sights undoubtedly set upon the next two years  koenji claims hidden strength matters  he can do anything if he tries   if you want to know  it s because i am amazing  koenji argues students without ability should strive to turn over a new leaf  koenji ignored by sudo  horikita silences sudo  identified as a likely censure target by the ayanokoji group  keisei says koenji is an unnecessary student  easy to vote against  provokes sudo  argues unnecessary students should be removed","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y1v10-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y1v10-p30-1\">Ch.2: The Class Vote<\/a><\/span><span class=\"meta\">Y1V10 · p.30–84<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><p class=\"setup\">Kōenji provokes Sudō; claims unnecessary students should be removed. Kōenji claims hidden strength matters; he can do anything if he tries. Kōenji argues students without ability should strive to turn over a new leaf. Kōenji ignored by Sudō; Horikita silences Sudō. Identified as a likely censure target by the Ayanokōji Group. Keisei says Kōenji is an unnecessary student; easy to vote against.<\/p><p class=\"with\">with <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “Wrong. This special exam has its sights undoubtedly set upon the next two years.”<span class=\"pg\">p.43<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “If you want to know, it’s because I am amazing.”<span class=\"pg\">p.45<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Provokes Sudō; argues unnecessary students should be removed.<span class=\"pg\">p.42–48<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y1v10-p12-1\">← Before: Ch.1: Exam results<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y1v10-p200-1\">→ After: Ch.5: Supporting Horikita’s nomination<\/button><\/div><\/article>"},{"i":"sc-kushida-kikyou-y1v10-p30-1","v":"y1v10","y":1,"o":12,"k":"","w":"kushida-kikyou","q":"kushida kikyo ch 2  the class vote kushida mentioned as someone who hates horikita  her influence could be problematic  kushida mentioned as someone who could be put in a position to cast censure votes for horikita","h":"<article class=\"card\" id=\"sc-kushida-kikyou-y1v10-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kushida-kikyou.html#sc-kushida-kikyou-y1v10-p30-1\">Ch.2: The Class Vote<\/a><\/span><span class=\"meta\">Y1V10 · p.30–84<\/span><span class=\"by\">notes on <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/span><\/h3><p class=\"setup\">Kushida mentioned as someone who hates Horikita; her influence could be problematic. Kushida mentioned as someone who could be put in a position to cast censure votes for Horikita.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kushida-kikyou-y1v10-p174-1\">→ After: Ch.4: Revealing the mastermind<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v10-p30-1","v":"y1v10","y":1,"o":12,"k":"","w":"miyake-akito","q":"miyake akito ch 2  the class vote akito agrees with keisei about going against other classes  akito says koenji is an unnecessary student  akito says he would give up if in ryuen s shoes  akito says ryuen is doing all he can to put up a calm front","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v10-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/miyake-akito.html#sc-miyake-akito-y1v10-p30-1\">Ch.2: The Class Vote<\/a><\/span><span class=\"meta\">Y1V10 · p.30–84<\/span><span class=\"by\">notes on <a href=\"../../../people/miyake-akito.html\">Miyake Akito<\/a><\/span><\/h3><p class=\"setup\">Akito agrees with Keisei about going against other classes. Akito says Kōenji is an unnecessary student. Akito says he would give up if in Ryūen’s shoes. Akito says Ryūen is doing all he can to put up a calm front.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v10-p85-1\">→ After: Ch.3: Group chat strategy<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y1v10-p30-1","v":"y1v10","y":1,"o":12,"k":"action spoken","w":"horikita-suzune ryuuen-kakeru","q":"ryuen kakeru ch 2  the class vote ryuen reads a book alone in class d  ayanokoji group observes him  horikita visits ryuen  he claims he could survive if he wanted   i make for a good target for the whole lot  ryuen sees through horikita s weakness  says her class made her complacent  ryuen tells horikita the class has made her complacent and she could not be ruthless enough to choose  he says she would have had to avoid lingering attachments from the start or treat classmates like chess pieces like sakayanagi  pp 72  78  ryuen reveals he accepted his defeat by ishizaki  horikita provokes him   it s ishizaki s reward as the one who defeated me  so i plan on sitting back and accepting it  ryuen says horikita is bluffing about steeling her resolve  horikita says ryuen is doomed  ayanokoji agrees  horikita visits him  he sees through her weakness  says her class made her complacent  sits alone in the cafe reading a book borrowed from the library   i was wondering who it was  but it was just suzune and her mindless little follower  closes the book and faces horikita   and what sort of business do you have with me   it s not like i have a lot of choices  i m not going to do anything   i make for a good target for the whole lot  in an exam like this one where someone has to be expelled  nobody wants to attract the resentment of the poor sap who gets kicked out  but in my case  that just ain t how it works  reopens his book and continues reading   that s probably right  class d doesn t stand a chance after i m gone  as students from the other classes  it would be the best and most appropriate judgment for you to crush me here   kuku  certainly   what a stupid question  of course i could   are you finally satisfied  or do you want to hear my secret plan for surviving the exam   your struggling may lead you to being ostracised by the rest of your class   how lame  so it was all just a bluff   you re looking for self confidence from talking to me  but your resolve doesn t amount to anything   no you can t   i ve had plenty of time to keep tabs on you this past year  so i understand you well enough  putting it in a way even you could understand  i can see the weakness you re trying to keep hidden   your class has already made you complacent  tells horikita she could not be ruthless enough to make a choice at this point and would have had to avoid lingering attachments or treat classmates like chess pieces like sakayanagi   and why would you think that   it s ishizaki s reward as the one who defeated me  so i plan on sitting back and accepting it  it s an opportunity that you  and the rest of class d  shouldn t miss out on  turns his attention back to his book as horikita and ayanokoji leave","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y1v10-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y1v10-p30-1\">Ch.2: The Class Vote<\/a><\/span><span class=\"meta\">Y1V10 · p.30–84<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Ryūen reads a book alone in Class D; Ayanokōji Group observes him. Horikita visits Ryūen; he claims he could survive if he wanted. Ryūen sees through Horikita’s weakness; says her class made her complacent. Ryūen reveals he accepted his defeat by Ishizaki; Horikita provokes him. Ryūen says Horikita is bluffing about steeling her resolve. Horikita says Ryūen is doomed; Ayanokōji agrees.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “I make for a good target for the whole lot.”<span class=\"pg\">p.61<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “It’s Ishizaki’s reward as the one who defeated me, so I plan on sitting back and accepting it.”<span class=\"pg\">p.68<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “I was wondering who it was, but it was just Suzune and her mindless little follower.”<span class=\"pg\">p.73<\/span><\/li><\/ul><details class=\"more\"><summary>23 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Ryūen tells Horikita the class has made her complacent and she could not be ruthless enough to choose; he says she would have had to avoid lingering attachments from the start or treat classmates like chess pieces like Sakayanagi (pp.72, 78).<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Horikita visits him; he sees through her weakness.<span class=\"pg\">p.58–74<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Says her class made her complacent.<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Sits alone in the cafe reading a book borrowed from the library.<span class=\"pg\">p.63<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Closes the book and faces Horikita.<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “And what sort of business do you have with me?”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s not like I have a lot of choices. I’m not going to do anything.”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I make for a good target for the whole lot. In an exam like this one where someone has to be expelled, nobody wants to attract the resentment of the poor sap who gets kicked out, but in my case, that just ain’t how it works.”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Reopens his book and continues reading.<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s probably right. Class D doesn’t stand a chance after I’m gone. As students from the other classes, it would be the best and most appropriate judgment for you to crush me here.”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kuku. Certainly.”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What a stupid question. Of course I could.”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you finally satisfied? Or do you want to hear my secret plan for surviving the exam?”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Your struggling may lead you to being ostracised by the rest of your class.”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How lame. So it was all just a bluff?”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re looking for self-confidence from talking to me, but your resolve doesn’t amount to anything.”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No you can’t.”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve had plenty of time to keep tabs on you this past year, so I understand you well enough. Putting it in a way even you could understand, I can see the weakness you’re trying to keep hidden.”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Your class has already made you complacent.”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tells Horikita she could not be ruthless enough to make a choice at this point and would have had to avoid lingering attachments or treat classmates like chess pieces like Sakayanagi.<span class=\"pg\">p.77–78<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “And why would you think that?”<span class=\"pg\">p.78<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s Ishizaki’s reward as the one who defeated me, so I plan on sitting back and accepting it. It’s an opportunity that you, and the rest of Class D, shouldn’t miss out on.”<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Turns his attention back to his book as Horikita and Ayanokōji leave.<span class=\"pg\">p.79<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y1v10-p239-1\">→ After: Ch.6: Accepting expulsion<\/button><\/div><\/article>"},{"i":"sc-sakura-airi-y1v10-p30-1","v":"y1v10","y":1,"o":12,"k":"","w":"sakura-airi","q":"sakura airi ch 2  the class vote airi shakes her head anxiously at the thought of expulsion  airi worries about being targeted  says she s no help to the class  airi speaks in defense of koenji  airi asks about ryuen s situation","h":"<article class=\"card\" id=\"sc-sakura-airi-y1v10-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakura-airi.html#sc-sakura-airi-y1v10-p30-1\">Ch.2: The Class Vote<\/a><\/span><span class=\"meta\">Y1V10 · p.30–84<\/span><span class=\"by\">notes on <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a><\/span><\/h3><p class=\"setup\">Airi shakes her head anxiously at the thought of expulsion. Airi worries about being targeted; says she’s no help to the class. Airi speaks in defense of Kōenji. Airi asks about Ryūen’s situation.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakura-airi-y1v10-p85-1\">→ After: Ch.3: Group chat strategy<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v10-p30-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"sudou-ken","q":"sudo ken ch 2  the class vote sudo argues with koenji  hirata mediates   you selfishly abstained from both the uninhabited island exam and the athletics festival  sudo slams his fist  horikita silences him  identified as a likely censure target by the ayanokoji group  sudo  ike  yamauchi expected to form a small group","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v10-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y1v10-p30-1\">Ch.2: The Class Vote<\/a><\/span><span class=\"meta\">Y1V10 · p.30–84<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"setup\">Sudō argues with Kōenji; Hirata mediates. Sudō slams his fist; Horikita silences him. Identified as a likely censure target by the Ayanokōji Group. Sudō, Ike, Yamauchi expected to form a small group.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “You selfishly abstained from both the uninhabited island exam and the athletics festival!”<span class=\"pg\">p.42<\/span><\/li><\/ul><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v10-p12-1\">← Before: Ch.1: Exam results<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v10-p149-1\">→ After: Ch.4: Morning walk<\/button><\/div><\/article>"},{"i":"sc-yamauchi-haruki-y1v10-p30-1","v":"y1v10","y":1,"o":12,"k":"","w":"yamauchi-haruki","q":"yamauchi haruki ch 2  the class vote yamauchi jokes that hirata is safe from expulsion  identified as a likely censure target by the ayanokoji group  ike  yamauchi  sudo expected to form a small group","h":"<article class=\"card\" id=\"sc-yamauchi-haruki-y1v10-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamauchi-haruki.html#sc-yamauchi-haruki-y1v10-p30-1\">Ch.2: The Class Vote<\/a><\/span><span class=\"meta\">Y1V10 · p.30–84<\/span><span class=\"by\">notes on <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a><\/span><\/h3><p class=\"setup\">Yamauchi jokes that Hirata is safe from expulsion. Identified as a likely censure target by the Ayanokōji Group. Ike, Yamauchi, Sudō expected to form a small group.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamauchi-haruki-y1v10-p12-1\">← Before: Ch.1: Exam results<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamauchi-haruki-y1v10-p179-1\">→ After: Ch.4: Named as mastermind<\/button><\/div><\/article>"},{"i":"sc-yukimura-teruhiko-y1v10-p30-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ayanokouji-kiyotaka yukimura-teruhiko","q":"yukimura teruhiko ch 2  the class vote keisei proposes mutual praise votes among the ayanokoji group   why don t we come together and vote for each other  keisei says to avoid standing out  large groups are risky  keisei identifies koenji  ike  yamauchi  sudo as likely censure targets  keisei says koenji is an unnecessary student  keisei argues ryuen cannot survive  horikita visits him  proposes mutual praise votes  identifies censure targets","h":"<article class=\"card\" id=\"sc-yukimura-teruhiko-y1v10-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yukimura-teruhiko.html#sc-yukimura-teruhiko-y1v10-p30-1\">Ch.2: The Class Vote<\/a><\/span><span class=\"meta\">Y1V10 · p.30–84<\/span><span class=\"by\">notes on <a href=\"../../../people/yukimura-teruhiko.html\">Yukimura Teruhiko<\/a><\/span><\/h3><p class=\"setup\">Keisei proposes mutual praise votes among the Ayanokōji Group. Keisei says to avoid standing out; large groups are risky. Keisei identifies Kōenji, Ike, Yamauchi, Sudō as likely censure targets. Keisei says Kōenji is an unnecessary student. Keisei argues Ryūen cannot survive; Horikita visits him.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yukimura Teruhiko<\/b> “Why don’t we come together and vote for each other?”<span class=\"pg\">p.52<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Proposes mutual praise votes; identifies censure targets.<span class=\"pg\">p.52–57<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yukimura-teruhiko-y1v10-p12-1\">← Before: Ch.1: Exam results<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yukimura-teruhiko-y1v10-p85-1\">→ After: Ch.3: Group chat strategy<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v10-p85-1","v":"y1v10","y":1,"o":12,"k":"action spoken","w":"ichinose-honami asahina-nazuna sakayanagi-arisu hirata-yousuke ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 3  morning conversations and after school meetings checks the ayanokoji group chat  keisei proposes arriving early to collect information  the group agrees and haruka volunteers for the next day  ichinose joins ayanokoji on the walk to school  she admits the exam is tough for class b and considers bearing the risk herself   in the face of such a terrible exam  i really have no choice but to do something  don t i  ichinose offers to use her cross class praise vote on ayanokoji  he declines   since i have a praise vote i can use on someone in another class  i could use it on you  asahina nazuna borrows ayanokoji and reveals ichinose asked nagumo for points  nagumo s condition is a relationship   the condition he set for lending the points to her  is for the two of them to get into a relationship  classroom atmosphere is tense  haruka messages that nothing unusual has happened  overhears sakayanagi and kamuro discuss sakayanagi s father s suspension and the supplementary exam  sakayanagi tells kamuro she knows ayanokoji from long ago   i simply know him from a long time ago  is this answer not acceptable enough  sakayanagi asks to postpone their match for this exam and promises not to cast censure votes for ayanokoji   for this exam  i won t do anything that would put you at a disadvantage  that is to say  i absolutely won t cast you any censure votes  sakayanagi says she has already decided class a will expel katsuragi kohei   katsuragi kohei kun  meets hirata and goes to his room  hirata cannot find a way to avoid an expulsion   if  if there s a way to save the class  please tell me   ayanokoji kun  do you think it s fine for someone to be expelled  morning walk  she considers bearing the risk and offers her praise vote  reveals ichinose asked nagumo for points and his condition  postpones their match  promises no censure votes  reveals katsuragi as class a target  hirata seeks a way to avoid expulsion   if you have business with me  i ll hear you out   he consented immediately   i ll ask just to make sure  but there s no way she d be lent enough private points with no strings attached  is there   are the conditions he s set too harsh  like an obscenely high interest rate   is it alright  for you to be telling me this   you re overestimating me  there s no way i can afford to make up for class b s lack of points   i can t do anything about it  follows horikita after class but stops when she tells him to leave her alone   it wouldn t be troublesome for us to take in another person   could i bother you for a moment  ayanokoji kun   sure  meets sakayanagi and kamuro and agrees to speak with sakayanagi at the special building   i have plans to meet up with a friend at keyaki mall in around half an hour   was that okay   not particularly   going so far as to have kamuro head back without you  what are you looking to talk to me about   make whatever decision you want   if my classmates were to focus their censure votes on me  there wouldn t be a next time in the first place   perhaps it s possible that your subordinates betray you before our match can even happen   you decided early on who d be removed  sounds like the right decision   a reasonable choice   is it alright for you to be telling me this  about who you re targeting   what are you planning to do with class c   sorry  it s about time i go  meets hirata and goes to his dorm room to talk   between being sent to the uninhabited island and being forced to participate in the training camp  it was quite the tiring year   yeah  i think so too   it sounds difficult  in an exam like this one  the more you think about your classmates  the harder it gets   it would be nice if nobody s expelled when the exam is over  but that s difficult in this case","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v10-p85-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v10-p85-1\">Ch.3: Morning conversations and after-school meetings<\/a><\/span><span class=\"meta\">Y1V10 · p.85–132<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Checks the Ayanokōji Group chat: Keisei proposes arriving early to collect information; the group agrees and Haruka volunteers for the next day. Ichinose joins Ayanokōji on the walk to school; she admits the exam is tough for Class B and considers bearing the risk herself. Ichinose offers to use her cross-class praise vote on Ayanokōji; he declines. Asahina Nazuna borrows Ayanokōji and reveals Ichinose asked Nagumo for points; Nagumo’s condition is a relationship. Classroom atmosphere is tense; Haruka messages that nothing unusual has happened. Overhears Sakayanagi and Kamuro discuss Sakayanagi’s father’s suspension and the supplementary exam. Sakayanagi tells Kamuro she knows Ayanokōji from long ago. Sakayanagi asks to postpone their match for this exam and promises not to cast censure votes for Ayanokōji. Sakayanagi says she has already decided Class A will expel Katsuragi Kōhei. Meets Hirata and goes to his room; Hirata cannot find a way to avoid an expulsion.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/asahina-nazuna.html\">Asahina Nazuna<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “In the face of such a terrible exam… I really have no choice but to do something, don’t I?”<span class=\"pg\">p.93<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “Since I have a praise vote I can use on someone in another class, I could use it on you.”<span class=\"pg\">p.96<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Asahina Nazuna<\/b> “The condition he set for lending the points to her… is for the two of them to get into a relationship.”<span class=\"pg\">p.101<\/span><\/li><\/ul><details class=\"more\"><summary>38 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I simply know him from a long time ago. Is this answer not acceptable enough?”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “For this exam, I won’t do anything that would put you at a disadvantage. That is to say, I absolutely won’t cast you any censure votes.”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Katsuragi Kōhei-kun.”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If… if there’s a way to save the class, please tell me.”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokōji-kun, do you think it’s fine for someone to be expelled?”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Morning walk; she considers bearing the risk and offers her praise vote.<span class=\"pg\">p.89–96<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Asahina Nazuna<\/b> Reveals Ichinose asked Nagumo for points and his condition.<span class=\"pg\">p.97–103<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Postpones their match; promises no censure votes; reveals Katsuragi as Class A target.<span class=\"pg\">p.117–127<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Hirata seeks a way to avoid expulsion.<span class=\"pg\">p.128–132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you have business with me, I’ll hear you out.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “He consented immediately?”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll ask just to make sure, but there’s no way she’d be lent enough private points with no strings attached, is there?”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are the conditions he’s set too harsh? Like an obscenely high interest rate?”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is it alright? For you to be telling me this?”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re overestimating me. There’s no way I can afford to make up for Class B’s lack of points.”<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I can’t do anything about it.”<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Follows Horikita after class but stops when she tells him to leave her alone.<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It wouldn’t be troublesome for us to take in another person.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Could I bother you for a moment, Ayanokōji-kun?”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sure.”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Meets Sakayanagi and Kamuro and agrees to speak with Sakayanagi at the special building.<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have plans to meet up with a friend at Keyaki Mall in around half an hour.”<span class=\"pg\">p.116<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Was that okay?”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Not particularly.”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Going so far as to have Kamuro head back without you, what are you looking to talk to me about?”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Make whatever decision you want.”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If my classmates were to focus their censure votes on me, there wouldn’t be a next time in the first place.”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Perhaps it’s possible that your subordinates betray you before our match can even happen.”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You decided early on who’d be removed? Sounds like the right decision.”<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A reasonable choice?”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is it alright for you to be telling me this? About who you’re targeting?”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What are you planning to do with Class C?”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry. It’s about time I go.”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Meets Hirata and goes to his dorm room to talk.<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Between being sent to the uninhabited island and being forced to participate in the training camp, it was quite the tiring year.”<span class=\"pg\">p.129<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah, I think so too.”<span class=\"pg\">p.129<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It sounds difficult. In an exam like this one, the more you think about your classmates, the harder it gets.”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It would be nice if nobody’s expelled when the exam is over. But that’s difficult in this case.”<span class=\"pg\">p.132<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v10-p30-1\">← Before: Ch.2: The Class Vote<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v10-p148-1\">→ After: Ch.4: The target and the mastermind<\/button><\/div><\/article>"},{"i":"sc-hasebe-haruka-y1v10-p85-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"hasebe-haruka","q":"hasebe haruka ch 3  group chat strategy volunteers in the group chat to go to school early the next day   i ll do it tomorrow since i ll be heading out early  messages ayanokoji that nothing unusual has happened in the classroom","h":"<article class=\"card\" id=\"sc-hasebe-haruka-y1v10-p85-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hasebe-haruka.html#sc-hasebe-haruka-y1v10-p85-1\">Ch.3: Group chat strategy<\/a><\/span><span class=\"meta\">Y1V10 · p.85–88<\/span><span class=\"by\">notes on <a href=\"../../../people/hasebe-haruka.html\">Hasebe Haruka<\/a><\/span><\/h3><p class=\"setup\">Volunteers in the group chat to go to school early the next day. Messages Ayanokōji that nothing unusual has happened in the classroom.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hasebe Haruka<\/b> [I’ll do it tomorrow since I’ll be heading out early.]<span class=\"pg\">p.87<\/span><\/li><\/ul><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hasebe-haruka-y1v10-p30-1\">← Before: Ch.2: The Class Vote<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hasebe-haruka-y1v10-p154-1\">→ After: Ch.4: Ayanokōji Group discussion<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v10-p85-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"miyake-akito","q":"miyake akito ch 3  group chat strategy agrees in the group chat to have someone go to school early to collect information   since we re such a small group  that might be a good idea  i m on board","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v10-p85-1\"><h3><span class=\"ttl\"><a href=\"../../../people/miyake-akito.html#sc-miyake-akito-y1v10-p85-1\">Ch.3: Group chat strategy<\/a><\/span><span class=\"meta\">Y1V10 · p.85–88<\/span><span class=\"by\">notes on <a href=\"../../../people/miyake-akito.html\">Miyake Akito<\/a><\/span><\/h3><p class=\"setup\">Agrees in the group chat to have someone go to school early to collect information.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Miyake Akito<\/b> [Since we’re such a small group, that might be a good idea. I’m on board.]<span class=\"pg\">p.87<\/span><\/li><\/ul><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v10-p30-1\">← Before: Ch.2: The Class Vote<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v10-p154-1\">→ After: Ch.4: Ayanokōji Group discussion<\/button><\/div><\/article>"},{"i":"sc-sakura-airi-y1v10-p85-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"sakura-airi","q":"sakura airi ch 3  group chat strategy agrees in the group chat to the plan to collect information early   i agree too","h":"<article class=\"card\" id=\"sc-sakura-airi-y1v10-p85-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakura-airi.html#sc-sakura-airi-y1v10-p85-1\">Ch.3: Group chat strategy<\/a><\/span><span class=\"meta\">Y1V10 · p.85–88<\/span><span class=\"by\">notes on <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a><\/span><\/h3><p class=\"setup\">Agrees in the group chat to the plan to collect information early.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sakura Airi<\/b> [I agree too.]<span class=\"pg\">p.87<\/span><\/li><\/ul><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakura-airi-y1v10-p30-1\">← Before: Ch.2: The Class Vote<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sakura-airi-y1v10-p154-1\">→ After: Ch.4: Ayanokōji Group discussion<\/button><\/div><\/article>"},{"i":"sc-yukimura-teruhiko-y1v10-p85-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"yukimura-teruhiko","q":"yukimura teruhiko ch 3  group chat strategy proposes in the ayanokoji group chat that one of them go to school early for the next three days to collect information   how do you guys feel about having one of us go to school early for the next three days to collect information  the group agrees and decides to move forward","h":"<article class=\"card\" id=\"sc-yukimura-teruhiko-y1v10-p85-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yukimura-teruhiko.html#sc-yukimura-teruhiko-y1v10-p85-1\">Ch.3: Group chat strategy<\/a><\/span><span class=\"meta\">Y1V10 · p.85–88<\/span><span class=\"by\">notes on <a href=\"../../../people/yukimura-teruhiko.html\">Yukimura Teruhiko<\/a><\/span><\/h3><p class=\"setup\">Proposes in the Ayanokōji Group chat that one of them go to school early for the next three days to collect information. The group agrees and decides to move forward.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yukimura Teruhiko<\/b> [How do you guys feel about having one of us go to school early for the next three days to collect information?]<span class=\"pg\">p.86<\/span><\/li><\/ul><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yukimura-teruhiko-y1v10-p30-1\">← Before: Ch.2: The Class Vote<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yukimura-teruhiko-y1v10-p152-1\">→ After: Ch.4: Classroom atmosphere<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v10-p89-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ayanokouji-kiyotaka asahina-nazuna ichinose-honami","q":"ichinose honami ch 3  morning walk and asahina s interruption joins ayanokoji on the walk to school  she is stiff at first but walks with him  admits the exam is the toughest for class b and considers bearing the risk herself   in the face of such a terrible exam  i really have no choice but to do something  don t i   not exactly  i just feel like i have to fight  and bear responsibility for the risk on my own  offers to use her cross class praise vote on ayanokoji  he declines   since i have a praise vote i can use on someone in another class  i could use it on you   yeah  i can t think of anyone more worthy than you  as the one who saved me  asahina nazuna greets ichinose and asks to borrow ayanokoji  ichinose leaves  morning walk  offers her praise vote  greets asahina before leaving   morning ayanokoji kun   wow  uhh  it s pretty cold again today  huh   did you plan on walking to school with someone   well then  do you mind if i join you   ah  well  yeah  i think this exam is the toughest we ve had by far   eh  no way  i definitely didn t say anything like that   i told you that i never said anything about dropping out myself  but  if you really think so then i guess you re probably right about that   r really   haa  keep it a secret from everyone okay   there s not much more i can tell you  it s not something i d like other people to hear about  furthermore  you re in class c  no matter what kind of exam it is  there are times where we just aren t able to collaborate   anywho  the school is pretty terrible  isn t it  what with making someone drop out of school and all  even if you manage to get praise votes from the kids in the other classes  someone still has to leave in the end   err  yes  he s a good friend   i understand  well then  ayanokoji kun  i ll be going on ahead   oh no  please excuse me","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v10-p89-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y1v10-p89-1\">Ch.3: Morning walk and Asahina’s interruption<\/a><\/span><span class=\"meta\">Y1V10 · p.89–96<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><p class=\"setup\">Joins Ayanokōji on the walk to school; she is stiff at first but walks with him. Admits the exam is the toughest for Class B and considers bearing the risk herself. Offers to use her cross-class praise vote on Ayanokōji; he declines. Asahina Nazuna greets Ichinose and asks to borrow Ayanokōji; Ichinose leaves.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/asahina-nazuna.html\">Asahina Nazuna<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “In the face of such a terrible exam… I really have no choice but to do something, don’t I?”<span class=\"pg\">p.93<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “Not exactly. I just feel like I have to fight, and bear responsibility for the risk on my own.”<span class=\"pg\">p.94<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “Since I have a praise vote I can use on someone in another class, I could use it on you.”<span class=\"pg\">p.96<\/span><\/li><\/ul><details class=\"more\"><summary>17 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Yeah, I can’t think of anyone more worthy than you, as the one who saved me.”<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Morning walk; offers her praise vote.<span class=\"pg\">p.89–96<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Asahina Nazuna<\/b> Greets Asahina before leaving.<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Morning Ayanokōji-kun~!”<span class=\"pg\">p.92<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wow, uhh… it’s pretty cold again today, huh?”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Did you plan on walking to school with someone?”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well then… do you mind if I join you?”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah, well… Yeah, I think this exam is the toughest we’ve had by far.”<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh? No way. I definitely didn’t say anything like that.”<span class=\"pg\">p.95<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I told you that I never said anything about dropping out myself. But, if you really think so then I guess you’re probably right about that.”<span class=\"pg\">p.95<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “R-really?”<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Haa… Keep it a secret from everyone okay?”<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’s not much more I can tell you. It’s not something I’d like other people to hear about. Furthermore, you’re in Class C. No matter what kind of exam it is, there are times where we just aren’t able to collaborate.”<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Anywho, the school is pretty terrible, isn’t it? What with making someone drop out of school and all. Even if you manage to get praise votes from the kids in the other classes, someone still has to leave in the end.”<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Err, yes. He’s a good friend…”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I understand. Well then, Ayanokōji-kun, I’ll be going on ahead.”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh no! Please excuse me.”<span class=\"pg\">p.97<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v10-p252-1\">→ After: Ch.6: Saving Class B<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y1v10-p96-1","v":"y1v10","y":1,"o":12,"k":"action spoken","w":"ichinose-honami nagumo-miyabi ayanokouji-kiyotaka asahina-nazuna","q":"asahina nazuna ch 3  conversation with ayanokoji greets ichinose and borrows ayanokoji to speak with him alone   good morning honami  tells ayanokoji ichinose cares deeply for her friends and would not sit back  reveals ichinose asked nagumo for points and nagumo consented   bingo again  reveals nagumo s condition is for the two of them to get into a relationship   the condition he set for lending the points to her  is for the two of them to get into a relationship  says she hopes ayanokoji can do something  he says he cannot  speaks on her behalf about the deal with nagumo  reveals his condition for lending points  asks him to help ichinose   sorry honami  see ya   she s a real good kid isn t she  cute  smart  even among the second years  nobody has anything bad to say about her   could it be that you ve managed to gain her affection   how boring  well whatever  i happened to see the two of you acting all buddy buddy  so i wanted to tell you something   honami cares deeply for her friends  or how should i put it  you know she s not the type of person who would sit back and let someone from class b be expelled  right   it seems she s gone and asked miyabi for assistance  can you guess how he responded   of course there isn t  sure  it d be a different story if we were only talking about a few thousand points  in that case  there d be plenty of room for discussion  but once it gets into the hundred thousands or the millions  nobody s gonna give away that many   the condition he set for lending the points to her  is for the two of them to get into a relationship   i ve already told you  it s for my class  if miyabi lends all those private points to a first year  the rest of us may suffer as a result  furthermore  in exchange for protecting her friends  honami ll have to go through something painful   i dunno  but  if it s you  you ll probably be able to do something about it one way or another   that s okay  even if you don t do anything  i won t hold it against you  it s just wishful thinking on my part either way  that said  even though you say you can t  i think you just might take the chance anyway  slaps ayanokoji on the back and runs toward the school after asking him to help","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y1v10-p96-1\"><h3><span class=\"ttl\"><a href=\"../../../people/asahina-nazuna.html#sc-asahina-nazuna-y1v10-p96-1\">Ch.3: Conversation with Ayanokōji<\/a><\/span><span class=\"meta\">Y1V10 · p.96–103<\/span><span class=\"by\">notes on <a href=\"../../../people/asahina-nazuna.html\">Asahina Nazuna<\/a><\/span><\/h3><p class=\"setup\">Greets Ichinose and borrows Ayanokōji to speak with him alone. Tells Ayanokōji Ichinose cares deeply for her friends and would not sit back. Reveals Ichinose asked Nagumo for points and Nagumo consented. Reveals Nagumo’s condition is for the two of them to get into a relationship. Says she hopes Ayanokōji can do something; he says he cannot.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Asahina Nazuna<\/b> “Good morning Honami.”<span class=\"pg\">p.96<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Asahina Nazuna<\/b> “Bingo again.”<span class=\"pg\">p.99<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Asahina Nazuna<\/b> “The condition he set for lending the points to her… is for the two of them to get into a relationship.”<span class=\"pg\">p.101<\/span><\/li><\/ul><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Speaks on her behalf about the deal with Nagumo.<span class=\"pg\">p.96–103<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Reveals his condition for lending points.<span class=\"pg\">p.99–101<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Asks him to help Ichinose.<span class=\"pg\">p.96–103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry Honami. See ya.”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “She’s a real good kid isn’t she? Cute. Smart. Even among the second-years, nobody has anything bad to say about her.”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Could it be that you’ve managed to gain her affection?”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How boring. Well whatever. I happened to see the two of you acting all buddy buddy, so I wanted to tell you something.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Honami cares deeply for her friends, or how should I put it… You know she’s not the type of person who would sit back and let someone from Class B be expelled, right?”<span class=\"pg\">p.99<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seems she’s gone and asked Miyabi for assistance. Can you guess how he responded?”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course there isn’t. Sure, it’d be a different story if we were only talking about a few thousand points. In that case, there’d be plenty of room for discussion. But once it gets into the hundred thousands or the millions? Nobody’s gonna give away that many.”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The condition he set for lending the points to her… is for the two of them to get into a relationship.”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve already told you. It’s for my class. If Miyabi lends all those private points to a first-year, the rest of us may suffer as a result. Furthermore, in exchange for protecting her friends, Honami’ll have to go through something painful.”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I dunno. But, if it’s you, you’ll probably be able to do something about it one way or another.”<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s okay. Even if you don’t do anything, I won’t hold it against you. It’s just wishful thinking on my part either way. That said, even though you say you can’t, I think you just might take the chance anyway.”<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Slaps Ayanokōji on the back and runs toward the school after asking him to help.<span class=\"pg\">p.103<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nagumo-miyabi-y1v10-p97-1","v":"y1v10","y":1,"o":12,"k":"","w":"nagumo-miyabi","q":"nagumo miyabi ch 3  ichinose s deal asahina reveals ichinose asked nagumo for points and he consented  nagumo s condition for lending points is a relationship with ichinose  nagumo does not appear in person  his actions are reported by asahina","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v10-p97-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nagumo-miyabi.html#sc-nagumo-miyabi-y1v10-p97-1\">Ch.3: Ichinose’s deal<\/a><\/span><span class=\"meta\">Y1V10 · p.97–103<\/span><span class=\"by\">notes on <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/span><\/h3><p class=\"setup\">Asahina reveals Ichinose asked Nagumo for points and he consented. Nagumo’s condition for lending points is a relationship with Ichinose.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Nagumo does not appear in person; his actions are reported by Asahina.<span class=\"pg\">p.99–101<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v10-p12-1\">← Before: Ch.1: Exam results and the hallway encounter<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v10-p165-1\">→ After: Ch.4: Third-year politics<\/button><\/div><\/article>"},{"i":"sc-kamuro-masumi-y1v10-p117-1","v":"y1v10","y":1,"o":12,"k":"action spoken","w":"sakayanagi-arisu ayanokouji-kiyotaka kamuro-masumi","q":"kamuro masumi ch 3  walk with sakayanagi walks with sakayanagi  asks about her father s suspension   suspended  your father  if i m not mistaken  he s the board chairman right  asks why sakayanagi keeps an eye on ayanokoji   i ve tried not being bothered by it until now  but you  why have you been keeping your eye on ayanokoji  says sakayanagi has never been so fixated on someone before   you ve never been so fixated on someone like this before  sakayanagi sends her back to the dorms  kamuro leaves without resisting  accompanies her and questions her interest in ayanokoji  questions sakayanagi s fixation on him   ayanokoji   totally  mashima sensei s usually pretty composed but even he s been giving off a sorta shaken vibe recently   what  you know something   so you re saying that the two of you just coincidentally reunited here  that s such a slim possibility though   then  is he really a difficult person to handle  sorry  but i just don t see it at all   you can ask anyone and they d probably be thinking the same thing  you ve never been so fixated on someone like this before   whatever  turns and walks down the stairway when sakayanagi sends her back to the dorms","h":"<article class=\"card\" id=\"sc-kamuro-masumi-y1v10-p117-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kamuro-masumi.html#sc-kamuro-masumi-y1v10-p117-1\">Ch.3: Walk with Sakayanagi<\/a><\/span><span class=\"meta\">Y1V10 · p.117–120<\/span><span class=\"by\">notes on <a href=\"../../../people/kamuro-masumi.html\">Kamuro Masumi<\/a><\/span><\/h3><p class=\"setup\">Walks with Sakayanagi; asks about her father’s suspension. Asks why Sakayanagi keeps an eye on Ayanokōji. Says Sakayanagi has never been so fixated on someone before. Sakayanagi sends her back to the dorms; Kamuro leaves without resisting.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kamuro Masumi<\/b> “Suspended… Your father… If I’m not mistaken, he’s the board chairman right?”<span class=\"pg\">p.117<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kamuro Masumi<\/b> “I’ve tried not being bothered by it until now, but you… Why have you been keeping your eye on Ayanokōji?”<span class=\"pg\">p.118<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kamuro Masumi<\/b> “You’ve never been so fixated on someone like this before.”<span class=\"pg\">p.119<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Accompanies her and questions her interest in Ayanokōji.<span class=\"pg\">p.117–120<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Questions Sakayanagi’s fixation on him.<span class=\"pg\">p.118–119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokōji…”<span class=\"pg\">p.116<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Totally. Mashima-sensei’s usually pretty composed but even he’s been giving off a sorta shaken vibe recently.”<span class=\"pg\">p.117<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What, you know something?”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So you’re saying that the two of you just coincidentally reunited here? That’s such a slim possibility though.”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then, is he really a difficult person to handle? Sorry, but I just don’t see it at all.”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You can ask anyone and they’d probably be thinking the same thing. You’ve never been so fixated on someone like this before.”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Whatever.”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Turns and walks down the stairway when Sakayanagi sends her back to the dorms.<span class=\"pg\">p.120<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kamuro-masumi-y1v10-p266-1\">→ After: Ch.6: With Sakayanagi and Yamauchi<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-arisu-y1v10-p117-1","v":"y1v10","y":1,"o":12,"k":"action spoken","w":"ayanokouji-kiyotaka kamuro-masumi katsuragi-kouhei sakayanagi-arisu","q":"sakayanagi arisu ch 3  sakayanagi s decision and postponed match walks with kamuro  discusses her father s suspension and the supplementary exam   it s a personal matter that i m a bit ashamed of  but my father was suspended from his position a few days ago  tells kamuro she knows ayanokoji from long ago   i simply know him from a long time ago  is this answer not acceptable enough  asks ayanokoji to postpone their match  promises not to cast censure votes for him   for this exam  i won t do anything that would put you at a disadvantage  that is to say  i absolutely won t cast you any censure votes  says she has already decided class a will expel katsuragi kohei   katsuragi kohei kun   he s the former leader of class a who opposed me earlier in the year  there s no need for two people to stand at the top of the same class  after all  postpones match  promises no censure votes  walks and talks with kamuro before sending her back  decides to expel him from class a  walks with kamuro and discusses her father s suspension and the supplementary exam  sends kamuro back to the dorms and speaks with ayanokoji alone in the special building  proposes postponing their match for this supplementary exam and promises not to cast ayanokoji any censure votes  states she has already decided class a will expel katsuragi kohei and has informed her class   i had been wondering what i would have to do if you didn t agree  now  i ll be free to focus my attention on class a s internal politics   i had already decided who would be expelled as soon as the exam was announced   i already told them all a long time ago  had i waited until the last minute to inform them  it would ve only caused anxiety in its own way  by making it known ahead of time  it s easier on the rest of the class  don t you agree   what a coincidence  ayanokoji kun   where are you off to now   is that so  it seems that you re living your life to the fullest  if you don t mind  could you spare me just a little of your time   at any rate  ayanokoji kun  masumi san  don t you think this supplemental exam is far too unreasonable  they ve decided to force expulsions on us just because nobody has been expelled yet  setting up an exam like this one  thinking about it rationally  it s ridiculous   don t you think it s possible that the school hastily prepared the exam  all for the sake of forcing a certain someone s expulsion   i ve tried not being bothered by it until now  but you  why have you been keeping your eye on ayanokoji   you ve become quite inquisitive lately  haven t you  up until now  i don t think you ve ever thrown me this kind of question before   nobody will bother us if we talk here   well  masumi san  i apologize  but please head on back to the dorms without me   yes  wouldn t you have found it troublesome if i went and revealed something   it s about the promise we made with each other   yes  that was certainly the plan  however  if it s alright with you  i would like to put it off until next time  this supplementary exam isn t a competition between the classes  rather  it s a screening process for us to evaluate our own peers  the only way we can influence the other classes is with praise votes  and we can t attack one another even if we wanted to  so wouldn t it be fine if we postponed our match until next time   thank you very much  i had been wondering what i would have to do if you didn t agree  now  i ll be free to focus my attention on class a s internal politics  though   you are certainly right about that  either way  please have some peace of mind  that s all i m trying to say   fufu  you re quite the funny one   though  i have no idea what class b will do  for this entire exam  i m looking forward to seeing who gets expelled from that intimate class the most  though  perhaps ichinose san has come up with something interesting   you re right  we can leave our conversation here for the time being  after all  the next special exam begins next week","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y1v10-p117-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y1v10-p117-1\">Ch.3: Sakayanagi’s decision and postponed match<\/a><\/span><span class=\"meta\">Y1V10 · p.117–127<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><p class=\"setup\">Walks with Kamuro; discusses her father’s suspension and the supplementary exam. Tells Kamuro she knows Ayanokōji from long ago. Asks Ayanokōji to postpone their match; promises not to cast censure votes for him. Says she has already decided Class A will expel Katsuragi Kōhei.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/kamuro-masumi.html\">Kamuro Masumi<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “It’s a personal matter that I’m a bit ashamed of, but my father was suspended from his position a few days ago.”<span class=\"pg\">p.117<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “I simply know him from a long time ago. Is this answer not acceptable enough?”<span class=\"pg\">p.118<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “For this exam, I won’t do anything that would put you at a disadvantage. That is to say, I absolutely won’t cast you any censure votes.”<span class=\"pg\">p.121<\/span><\/li><\/ul><details class=\"more\"><summary>29 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Katsuragi Kōhei-kun.”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “He’s the former leader of Class A who opposed me earlier in the year. There’s no need for two people to stand at the top of the same class, after all.”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Postpones match; promises no censure votes.<span class=\"pg\">p.117–127<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamuro Masumi<\/b> Walks and talks with Kamuro before sending her back.<span class=\"pg\">p.117–120<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Decides to expel him from Class A.<span class=\"pg\">p.122, 125<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Walks with Kamuro and discusses her father’s suspension and the supplementary exam.<span class=\"pg\">p.117<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Sends Kamuro back to the dorms and speaks with Ayanokōji alone in the special building.<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Proposes postponing their match for this supplementary exam and promises not to cast Ayanokōji any censure votes.<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> States she has already decided Class A will expel Katsuragi Kōhei and has informed her class.<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I had been wondering what I would have to do if you didn’t agree. Now, I’ll be free to focus my attention on Class A’s internal politics.”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I had already decided who would be expelled as soon as the exam was announced.”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I already told them all a long time ago. Had I waited until the last minute to inform them, it would’ve only caused anxiety in its own way. By making it known ahead of time, it’s easier on the rest of the class, don’t you agree?”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What a coincidence. Ayanokōji-kun.”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Where are you off to now?”<span class=\"pg\">p.116<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is that so? It seems that you’re living your life to the fullest. If you don’t mind, could you spare me just a little of your time?”<span class=\"pg\">p.116<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “At any rate… Ayanokōji-kun, Masumi-san. Don’t you think this supplemental exam is far too unreasonable? They’ve decided to force expulsions on us just because nobody has been expelled yet. Setting up an exam like this one… Thinking about it rationally, it’s ridiculous.”<span class=\"pg\">p.116<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t you think it’s possible that the school hastily prepared the exam… all for the sake of forcing a certain someone’s expulsion?”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve tried not being bothered by it until now, but you… Why have you been keeping your eye on Ayanokōji?”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’ve become quite inquisitive lately, haven’t you? Up until now, I don’t think you’ve ever thrown me this kind of question before.”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nobody will bother us if we talk here.”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, Masumi-san. I apologize, but please head on back to the dorms without me.”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. Wouldn’t you have found it troublesome if I went and revealed something?”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s about the promise we made with each other.”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes, that was certainly the plan. However… if it’s alright with you, I would like to put it off until next time. This supplementary exam isn’t a competition between the classes. Rather, it’s a screening process for us to evaluate our own peers. The only way we can influence the other classes is with praise votes, and we can’t attack one another even if we wanted to… So wouldn’t it be fine if we postponed our match until next time?”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Thank you very much. I had been wondering what I would have to do if you didn’t agree. Now, I’ll be free to focus my attention on Class A’s internal politics. Though…”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You are certainly right about that. Either way, please have some peace of mind. That’s all I’m trying to say.”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Fufu, you’re quite the funny one.”<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Though, I have no idea what Class B will do. For this entire exam, I’m looking forward to seeing who gets expelled from that intimate class the most. Though, perhaps Ichinose-san has come up with something interesting?”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re right. We can leave our conversation here for the time being. After all, the next special exam begins next week.”<span class=\"pg\">p.126<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y1v10-p180-1\">→ After: Ch.4: Supporting Yamauchi<\/button><\/div><\/article>"},{"i":"sc-katsuragi-kouhei-y1v10-p122-1","v":"y1v10","y":1,"o":12,"k":"","w":"sakayanagi-arisu totsuka-yahiko katsuragi-kouhei","q":"katsuragi kohei ch 3  target of class a sakayanagi reveals she has already decided class a will expel katsuragi  sakayanagi names him as the target  yahiko and some others still follow him but are outnumbered  targeted for expulsion by sakayanagi s faction in the class poll  chosen by sakayanagi to be expelled from class a  yahiko still follows him but is outnumbered  does not appear in person  sakayanagi names him as the class a target and says he has likely accepted his fate","h":"<article class=\"card\" id=\"sc-katsuragi-kouhei-y1v10-p122-1\"><h3><span class=\"ttl\"><a href=\"../../../people/katsuragi-kouhei.html#sc-katsuragi-kouhei-y1v10-p122-1\">Ch.3: Target of Class A<\/a><\/span><span class=\"meta\">Y1V10 · p.122, 125<\/span><span class=\"by\">notes on <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/span><\/h3><p class=\"setup\">Sakayanagi reveals she has already decided Class A will expel Katsuragi. Sakayanagi names him as the target; Yahiko and some others still follow him but are outnumbered.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/totsuka-yahiko.html\">Totsuka Yahiko<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Position<\/span> Targeted for expulsion by Sakayanagi’s faction in the Class Poll.<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Chosen by Sakayanagi to be expelled from Class A.<span class=\"pg\">p.122, 125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Totsuka Yahiko<\/b> Yahiko still follows him but is outnumbered.<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Does not appear in person; Sakayanagi names him as the Class A target and says he has likely accepted his fate.<span class=\"pg\">p.122, 125<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-katsuragi-kouhei-y1v10-p262-1\">→ After: Ch.6: Class A votes him out<\/button><\/div><\/article>"},{"i":"sc-totsuka-yahiko-y1v10-p125-1","v":"y1v10","y":1,"o":12,"k":"","w":"katsuragi-kouhei totsuka-yahiko","q":"totsuka yahiko ch 3  following katsuragi mentioned as one of the students who still follow katsuragi  though outnumbered  still follows him despite sakayanagi s decision  does not appear in person  named as one of the few still following katsuragi","h":"<article class=\"card\" id=\"sc-totsuka-yahiko-y1v10-p125-1\"><h3><span class=\"ttl\"><a href=\"../../../people/totsuka-yahiko.html#sc-totsuka-yahiko-y1v10-p125-1\">Ch.3: Following Katsuragi<\/a><\/span><span class=\"meta\">Y1V10 · p.125<\/span><span class=\"by\">notes on <a href=\"../../../people/totsuka-yahiko.html\">Totsuka Yahiko<\/a><\/span><\/h3><p class=\"setup\">Mentioned as one of the students who still follow Katsuragi, though outnumbered.<\/p><p class=\"with\">with <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Still follows him despite Sakayanagi’s decision.<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Does not appear in person; named as one of the few still following Katsuragi.<span class=\"pg\">p.125<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-totsuka-yahiko-y1v10-p263-1\">→ After: Ch.6: Defending Katsuragi<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v10-p128-1","v":"y1v10","y":1,"o":12,"k":"action spoken","w":"ayanokouji-kiyotaka hirata-yousuke","q":"hirata yosuke ch 3  conversation in his room meets ayanokoji after school and asks to talk in his room   thanks for coming today  says he has been unable to sleep and cannot find a way to save the class   this exam  i just can t think of a solution  no matter how many times i think about it  nothing comes to mind  asks ayanokoji if there is a way to save 20 million points or avoid expulsion   if  if there s a way to save the class  please tell me  asks if it is fine for someone to be expelled   ayanokoji kun  do you think it s fine for someone to be expelled  seeks his help to avoid an expulsion   could i bother you for a moment  ayanokoji kun   if it s alright with you  could you join me for a bit after school  i need to talk with you   alright  how about meeting near the southern entrance of keyaki mall at half past four   i m happy to hear that  anyway  how about we walk for a bit   sorry ayanokoji kun  do you mind if i change our plans a little   is it a problem if we talk in my room instead  i think i d feel better if we did   thanks for understanding   our first year is already almost over  how did yours go  ayanokoji kun   yeah  it was definitely tough  but i still had fun  ever since enrolling here  i feel like i ve been able to successfully build trusting relationships with the people around me   honestly  there were never any problems until this exam started   yep  sorry  i m well aware that you don t want to talk about it   do you really think it s impossible to save up 20 million private points   i ve tried running the numbers  but it s just not possible to get that many points  yesterday  i tried to casually bring it up with my upperclassmen in the soccer club  but they re all waiting for the special exams they ll be facing after this   yeah   is that so  well  thank you  looks worn out with dark circles beneath his eyes after thinking about the exam","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v10-p128-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v10-p128-1\">Ch.3: Conversation in his room<\/a><\/span><span class=\"meta\">Y1V10 · p.128–132<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Meets Ayanokōji after school and asks to talk in his room. Says he has been unable to sleep and cannot find a way to save the class. Asks Ayanokōji if there is a way to save 20 million points or avoid expulsion. Asks if it is fine for someone to be expelled.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “Thanks for coming today.”<span class=\"pg\">p.128<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “This exam… I just can’t think of a solution. No matter how many times I think about it, nothing comes to mind.”<span class=\"pg\">p.130<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “If… if there’s a way to save the class, please tell me.”<span class=\"pg\">p.130<\/span><\/li><\/ul><details class=\"more\"><summary>18 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Ayanokōji-kun, do you think it’s fine for someone to be expelled?”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Seeks his help to avoid an expulsion.<span class=\"pg\">p.128–132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Could I bother you for a moment, Ayanokōji-kun?”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If it’s alright with you, could you join me for a bit after school? I need to talk with you.”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Alright, how about meeting near the southern entrance of Keyaki Mall at half-past four?”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m happy to hear that. Anyway, how about we walk for a bit?”<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry Ayanokōji-kun. Do you mind if I change our plans a little?”<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is it a problem if we talk in my room instead? I think I’d feel better if we did.”<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Thanks for understanding.”<span class=\"pg\">p.129<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Our first year is already almost over. How did yours go, Ayanokōji-kun?”<span class=\"pg\">p.129<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah. It was definitely tough, but I still had fun. Ever since enrolling here, I feel like I’ve been able to successfully build trusting relationships with the people around me.”<span class=\"pg\">p.129<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Honestly… There were never any problems until this exam started.”<span class=\"pg\">p.129<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yep. Sorry… I’m well aware that you don’t want to talk about it.”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you really think it’s impossible to save up 20 million private points?”<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve tried running the numbers, but it’s just not possible to get that many points. Yesterday, I tried to casually bring it up with my upperclassmen in the soccer club, but they’re all waiting for the special exams they’ll be facing after this.”<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah…”<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is that so… Well, thank you.”<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Looks worn out with dark circles beneath his eyes after thinking about the exam.<span class=\"pg\">p.132<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v10-p30-1\">← Before: Ch.2: The Class Vote<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v10-p150-1\">→ After: Ch.4: Classroom atmosphere<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v10-p148-1","v":"y1v10","y":1,"o":12,"k":"action spoken","w":"horikita-manabu karuizawa-kei kushida-kikyou tachibana-akane yamauchi-haruki sakayanagi-arisu ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 4  the target and the mastermind walks to school with sudo  sudo says he does not want to be expelled  notices the classroom atmosphere has shifted to unusual unity  horikita notices the change  ayanokoji messages keisei about a possible large group  ayanokoji group discusses the large group at lunch  hirata looks distraught  receives a message and leaves to meet someone  meets horikita manabu and tachibana akane at a rest area  manabu explains third years need private points for their own exams  ayanokoji and manabu discuss suzune and nagumo s moves   i ll do what i can  kei calls to warn that around half the class plans to vote him out   everyone s gonna vote you out of school  calls horikita manabu to propose a strategy  calls kushida  she reveals yamauchi is the tentative mastermind   is that so   do you know how many people are going to vote against me   thanks for letting me know this  decides to contact horikita manabu and calls him about the supplemental exam   i need to talk to you about the supplemental exam  it s fairly important   something happened in my class  a large group was formed and they ve decided on who exactly they ll be trying to expel   me   more than half of my class has already agreed to vote against me  offers manabu a proposal and secures his cooperation for the next day  calls kushida to find out who the mastermind is   could it be that you re the mastermind  kushida   it s yamauchi kun   you ve been a great help  kushida   it s yamauchi kun   sakayanagi san from class a seems to be the one supporting yamauchi kun  ends the call with kushida  decides to relay information to manabu  meets him  later calls to propose strategy  present at the meeting  warns him he is the target  reveals yamauchi as tentative mastermind  named as tentative mastermind  named as supporting yamauchi behind the scenes","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v10-p148-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v10-p148-1\">Ch.4: The target and the mastermind<\/a><\/span><span class=\"meta\">Y1V10 · p.148–181<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Walks to school with Sudō; Sudō says he does not want to be expelled. Notices the classroom atmosphere has shifted to unusual unity. Horikita notices the change; Ayanokōji messages Keisei about a possible large group. Ayanokōji Group discusses the large group at lunch; Hirata looks distraught. Receives a message and leaves to meet someone. Meets Horikita Manabu and Tachibana Akane at a rest area. Manabu explains third-years need private points for their own exams. Ayanokōji and Manabu discuss Suzune and Nagumo’s moves. Kei calls to warn that around half the class plans to vote him out. Calls Horikita Manabu to propose a strategy. Calls Kushida; she reveals Yamauchi is the tentative mastermind. Ends the call with Kushida; decides to relay information to Manabu.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a> · <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"../../../people/tachibana-akane.html\">Tachibana Akane<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Manabu<\/b> “I’ll do what I can.”<span class=\"pg\">p.166<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “everyone’s gonna vote you out of school.”<span class=\"pg\">p.168<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Is that so?”<span class=\"pg\">p.168<\/span><\/li><\/ul><details class=\"more\"><summary>20 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Do you know how many people are going to vote against me?”<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Thanks for letting me know this.”<span class=\"pg\">p.169<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Decides to contact Horikita Manabu and calls him about the supplemental exam.<span class=\"pg\">p.171<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I need to talk to you about the supplemental exam. It’s fairly important.”<span class=\"pg\">p.171<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Something happened in my class. A large group was formed and they’ve decided on who exactly they’ll be trying to expel.”<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Me.”<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “More than half of my class has already agreed to vote against me.”<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Offers Manabu a proposal and secures his cooperation for the next day.<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Calls Kushida to find out who the mastermind is.<span class=\"pg\">p.174<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Could it be that you’re the mastermind, Kushida?”<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s Yamauchi-kun.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’ve been a great help, Kushida.”<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s Yamauchi-kun.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sakayanagi-san from Class A seems to be the one supporting Yamauchi-kun.”<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Meets him; later calls to propose strategy.<span class=\"pg\">p.162–167, 171–173<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tachibana Akane<\/b> Present at the meeting.<span class=\"pg\">p.162–167<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Warns him he is the target.<span class=\"pg\">p.168–170<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Reveals Yamauchi as tentative mastermind.<span class=\"pg\">p.174–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Named as tentative mastermind.<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Named as supporting Yamauchi behind the scenes.<span class=\"pg\">p.180<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v10-p85-1\">← Before: Ch.3: Morning conversations and after-school meetings<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v10-p182-1\">→ After: Ch.5: Good and Evil<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v10-p149-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"sudou-ken","q":"sudo ken ch 4  morning walk walks to school with ayanokoji  says he has been improving and does not want to be expelled   sorta  even if it s just a short one  i thought i d get a workout in   i may be stupid and short tempered  but i ve been making huge improvements recently  that s why i absolutely don t wanna be expelled   nah  that sounds about right  the strong willed are the ones who ll make it through this exam","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v10-p149-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y1v10-p149-1\">Ch.4: Morning walk<\/a><\/span><span class=\"meta\">Y1V10 · p.149<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"setup\">Walks to school with Ayanokōji; says he has been improving and does not want to be expelled.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “Sorta. Even if it’s just a short one, I thought I’d get a workout in.”<span class=\"pg\">p.149<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “I may be stupid and short-tempered, but I’ve been making huge improvements recently. That’s why I absolutely don’t wanna be expelled.”<span class=\"pg\">p.149<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “Nah, that sounds about right. The strong-willed are the ones who’ll make it through this exam.”<span class=\"pg\">p.149<\/span><\/li><\/ul><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v10-p30-1\">← Before: Ch.2: The Class Vote<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v10-p184-1\">→ After: Ch.5: Objection to expelling Yamauchi<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v10-p150-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"hirata-yousuke","q":"hirata yosuke ch 4  classroom atmosphere greets ayanokoji  the classroom atmosphere has shifted to unusual unity   good morning ayanokoji kun  looks at ayanokoji with the same expression as always  does not seem to notice anything strange  ayanokoji group observes hirata looking distraught at lunch  hirata is walking listlessly by himself  looking distraught despite being safe from expulsion","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v10-p150-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v10-p150-1\">Ch.4: Classroom atmosphere<\/a><\/span><span class=\"meta\">Y1V10 · p.150–151<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Greets Ayanokōji; the classroom atmosphere has shifted to unusual unity. Looks at Ayanokōji with the same expression as always; does not seem to notice anything strange. Ayanokōji Group observes Hirata looking distraught at lunch.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “Good morning Ayanokōji-kun.”<span class=\"pg\">p.150<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Hirata is walking listlessly by himself, looking distraught despite being safe from expulsion.<span class=\"pg\">p.154<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v10-p128-1\">← Before: Ch.3: Conversation in his room<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v10-p200-1\">→ After: Ch.5: Refusal and collapse<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y1v10-p152-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ayanokouji-kiyotaka horikita-suzune","q":"horikita suzune ch 4  classroom atmosphere notices the unusual unity in the classroom  asks what happened   what happened  suggests ayanokoji ask them himself if interested  discusses the classroom atmosphere with him","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v10-p152-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v10-p152-1\">Ch.4: Classroom atmosphere<\/a><\/span><span class=\"meta\">Y1V10 · p.152–153<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Notices the unusual unity in the classroom; asks what happened. Suggests Ayanokōji ask them himself if interested.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “…What happened?”<span class=\"pg\">p.152<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Discusses the classroom atmosphere with him.<span class=\"pg\">p.152–153<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v10-p30-1\">← Before: Ch.2: The Class Vote<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v10-p182-1\">→ After: Ch.5: Good and Evil<\/button><\/div><\/article>"},{"i":"sc-yukimura-teruhiko-y1v10-p152-1","v":"y1v10","y":1,"o":12,"k":"","w":"yukimura-teruhiko","q":"yukimura teruhiko ch 4  classroom atmosphere messages ayanokoji that he has no idea about the classroom change but notices something is different  confirms the gloomy atmosphere is gone after ayanokoji points it out  reports to the ayanokoji group that there were signs a large group formed","h":"<article class=\"card\" id=\"sc-yukimura-teruhiko-y1v10-p152-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yukimura-teruhiko.html#sc-yukimura-teruhiko-y1v10-p152-1\">Ch.4: Classroom atmosphere<\/a><\/span><span class=\"meta\">Y1V10 · p.152–153<\/span><span class=\"by\">notes on <a href=\"../../../people/yukimura-teruhiko.html\">Yukimura Teruhiko<\/a><\/span><\/h3><p class=\"setup\">Messages Ayanokōji that he has no idea about the classroom change but notices something is different. Confirms the gloomy atmosphere is gone after Ayanokōji points it out. Reports to the Ayanokōji Group that there were signs a large group formed.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yukimura-teruhiko-y1v10-p85-1\">← Before: Ch.3: Group chat strategy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yukimura-teruhiko-y1v10-p226-1\">→ After: Ch.5: Cafe discussion<\/button><\/div><\/article>"},{"i":"sc-hasebe-haruka-y1v10-p154-1","v":"y1v10","y":1,"o":12,"k":"","w":"hasebe-haruka","q":"hasebe haruka ch 4  ayanokoji group discussion discusses the large group at lunch with the ayanokoji group  suggests talking about something more positive","h":"<article class=\"card\" id=\"sc-hasebe-haruka-y1v10-p154-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hasebe-haruka.html#sc-hasebe-haruka-y1v10-p154-1\">Ch.4: Ayanokōji Group discussion<\/a><\/span><span class=\"meta\">Y1V10 · p.154–161<\/span><span class=\"by\">notes on <a href=\"../../../people/hasebe-haruka.html\">Hasebe Haruka<\/a><\/span><\/h3><p class=\"setup\">Discusses the large group at lunch with the Ayanokōji Group. Suggests talking about something more positive.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hasebe-haruka-y1v10-p85-1\">← Before: Ch.3: Group chat strategy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hasebe-haruka-y1v10-p226-1\">→ After: Ch.5: Cafe discussion<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v10-p154-1","v":"y1v10","y":1,"o":12,"k":"","w":"miyake-akito","q":"miyake akito ch 4  ayanokoji group discussion discusses the large group at lunch with the ayanokoji group  notes hirata looks distraught","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v10-p154-1\"><h3><span class=\"ttl\"><a href=\"../../../people/miyake-akito.html#sc-miyake-akito-y1v10-p154-1\">Ch.4: Ayanokōji Group discussion<\/a><\/span><span class=\"meta\">Y1V10 · p.154–161<\/span><span class=\"by\">notes on <a href=\"../../../people/miyake-akito.html\">Miyake Akito<\/a><\/span><\/h3><p class=\"setup\">Discusses the large group at lunch with the Ayanokōji Group. Notes Hirata looks distraught.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v10-p85-1\">← Before: Ch.3: Group chat strategy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v10-p226-1\">→ After: Ch.5: Cafe discussion and advice<\/button><\/div><\/article>"},{"i":"sc-sakura-airi-y1v10-p154-1","v":"y1v10","y":1,"o":12,"k":"","w":"sakura-airi","q":"sakura airi ch 4  ayanokoji group discussion discusses the large group at lunch with the ayanokoji group  expresses worry about being targeted","h":"<article class=\"card\" id=\"sc-sakura-airi-y1v10-p154-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakura-airi.html#sc-sakura-airi-y1v10-p154-1\">Ch.4: Ayanokōji Group discussion<\/a><\/span><span class=\"meta\">Y1V10 · p.154–161<\/span><span class=\"by\">notes on <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a><\/span><\/h3><p class=\"setup\">Discusses the large group at lunch with the Ayanokōji Group. Expresses worry about being targeted.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakura-airi-y1v10-p85-1\">← Before: Ch.3: Group chat strategy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sakura-airi-y1v10-p226-1\">→ After: Ch.5: Cafe discussion<\/button><\/div><\/article>"},{"i":"sc-horikita-manabu-y1v10-p162-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ayanokouji-kiyotaka tachibana-akane horikita-suzune horikita-manabu","q":"horikita manabu ch 4  meeting and strategy meets ayanokoji with tachibana at a rest area  explains third years need private points for their own exams   the special exam given to the third years will probably be decided by the number of private points we have  we don t have enough to leave any behind for our underclassmen  discusses suzune and nagumo s moves   i ll do what i can  ayanokoji calls him to propose a strategy  he agrees to act tomorrow  meets him and agrees to cooperate  present at the meeting  discusses suzune s situation","h":"<article class=\"card\" id=\"sc-horikita-manabu-y1v10-p162-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-manabu.html#sc-horikita-manabu-y1v10-p162-1\">Ch.4: Meeting and strategy<\/a><\/span><span class=\"meta\">Y1V10 · p.162–167, 171–173<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/span><\/h3><p class=\"setup\">Meets Ayanokōji with Tachibana at a rest area. Explains third-years need private points for their own exams. Discusses Suzune and Nagumo’s moves. Ayanokōji calls him to propose a strategy; he agrees to act tomorrow.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/tachibana-akane.html\">Tachibana Akane<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Manabu<\/b> “The special exam given to the third-years will probably be decided by the number of private points we have. We don’t have enough to leave any behind for our underclassmen.”<span class=\"pg\">p.163<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Manabu<\/b> “I’ll do what I can.”<span class=\"pg\">p.166<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Meets him and agrees to cooperate.<span class=\"pg\">p.162–167, 171–173<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tachibana Akane<\/b> Present at the meeting.<span class=\"pg\">p.162–167<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Discusses Suzune’s situation.<span class=\"pg\">p.164<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-manabu-y1v10-p12-1\">← Before: Ch.1: Exam results and the hallway encounter<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-manabu-y1v10-p162-2\">→ After: Ch.4: Meeting with Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-horikita-manabu-y1v10-p162-2","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ayanokouji-kiyotaka horikita-manabu","q":"horikita manabu ch 4  meeting with ayanokoji meets ayanokoji at a rest area and asks about suzune   sorry for calling you out here  reacts to news of the supplemental exam   i hear a supplemental special exam has begun  dismisses ayanokoji s involvement   you re doing something unnecessary  says suzune will not approach him   suzune isn t going to approach me  says he and suzune are too different   you re asking for the impossible  horikita and i are far too different  replies that ayanokoji is more similar to suzune than he is   at least more so than me  answers ayanokoji s call after doing the dishes   what is it  agrees to ayanokoji s proposal   indeed  i wouldn t have agreed if that were not the case  agrees to act the next day   alright  we ll act tomorrow  meets him and agrees to cooperate","h":"<article class=\"card\" id=\"sc-horikita-manabu-y1v10-p162-2\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-manabu.html#sc-horikita-manabu-y1v10-p162-2\">Ch.4: Meeting with Ayanokōji<\/a><\/span><span class=\"meta\">Y1V10 · p.162–168<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/span><\/h3><p class=\"setup\">Meets Ayanokōji at a rest area and asks about Suzune. Reacts to news of the supplemental exam. Dismisses Ayanokōji’s involvement. Says Suzune will not approach him. Says he and Suzune are too different. Replies that Ayanokōji is more similar to Suzune than he is. Answers Ayanokōji’s call after doing the dishes. Agrees to Ayanokōji’s proposal. Agrees to act the next day.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Sorry for calling you out here.”<span class=\"pg\">p.162<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Manabu<\/b> “I hear a supplemental special exam has begun.”<span class=\"pg\">p.163<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Manabu<\/b> “You’re doing something unnecessary.”<span class=\"pg\">p.163<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Suzune isn’t going to approach me.”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re asking for the impossible. Horikita and I are far too different.”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “At least more so than me.”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What is it?”<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Indeed. I wouldn’t have agreed if that were not the case.”<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “...Alright. We’ll act tomorrow.”<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Meets him and agrees to cooperate.<span class=\"pg\">p.162–168<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-manabu-y1v10-p162-1\">← Before: Ch.4: Meeting and strategy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-manabu-y1v10-p186-1\">→ After: Ch.5: Meeting with Suzune<\/button><\/div><\/article>"},{"i":"sc-tachibana-akane-y1v10-p162-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"horikita-manabu ayanokouji-kiyotaka tachibana-akane","q":"tachibana akane ch 4  meeting with manabu and ayanokoji present at the rest area meeting with horikita manabu and ayanokoji   greetings  apologizes to manabu for her mistake that cost class a 20 million points   i m so sorry  if only i were more reliable  stays beside him at the meeting  meets him at the rest area","h":"<article class=\"card\" id=\"sc-tachibana-akane-y1v10-p162-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tachibana-akane.html#sc-tachibana-akane-y1v10-p162-1\">Ch.4: Meeting with Manabu and Ayanokōji<\/a><\/span><span class=\"meta\">Y1V10 · p.162–167<\/span><span class=\"by\">notes on <a href=\"../../../people/tachibana-akane.html\">Tachibana Akane<\/a><\/span><\/h3><p class=\"setup\">Present at the rest area meeting with Horikita Manabu and Ayanokōji. Apologizes to Manabu for her mistake that cost Class A 20 million points.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Tachibana Akane<\/b> “…Greetings.”<span class=\"pg\">p.162<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tachibana Akane<\/b> “I’m so sorry. If only I were more reliable…”<span class=\"pg\">p.163<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Stays beside him at the meeting.<span class=\"pg\">p.162–167<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Meets him at the rest area.<span class=\"pg\">p.162–167<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nagumo-miyabi-y1v10-p165-1","v":"y1v10","y":1,"o":12,"k":"","w":"nagumo-miyabi","q":"nagumo miyabi ch 4  third year politics tachibana reports nagumo has been in close contact with third year class b recently  nagumo does not appear in person  his moves are discussed at the meeting","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v10-p165-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nagumo-miyabi.html#sc-nagumo-miyabi-y1v10-p165-1\">Ch.4: Third-year politics<\/a><\/span><span class=\"meta\">Y1V10 · p.165–166<\/span><span class=\"by\">notes on <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/span><\/h3><p class=\"setup\">Tachibana reports Nagumo has been in close contact with third-year Class B recently.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Nagumo does not appear in person; his moves are discussed at the meeting.<span class=\"pg\">p.166<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v10-p97-1\">← Before: Ch.3: Ichinose’s deal<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v10-p257-1\">→ After: Ch.6: Lending points to Ichinose<\/button><\/div><\/article>"},{"i":"sc-karuizawa-kei-y1v10-p168-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ayanokouji-kiyotaka karuizawa-kei","q":"karuizawa kei ch 4  warning ayanokoji calls ayanokoji to warn him that around half the class plans to vote him out   jeez  finally you pick up   everyone s gonna vote you out of school  says she does not know exactly who is behind it but the group is large  ayanokoji thanks her for the information  warns him he is the target of the class poll","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y1v10-p168-1\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y1v10-p168-1\">Ch.4: Warning Ayanokōji<\/a><\/span><span class=\"meta\">Y1V10 · p.168–170<\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><p class=\"setup\">Calls Ayanokōji to warn him that around half the class plans to vote him out. Says she does not know exactly who is behind it but the group is large. Ayanokōji thanks her for the information.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “Jeez, finally you pick up…!”<span class=\"pg\">p.168<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “everyone’s gonna vote you out of school.”<span class=\"pg\">p.168<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Warns him he is the target of the Class Poll.<span class=\"pg\">p.168–170<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y1v10-p30-1\">← Before: Ch.2: The Class Vote<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y1v10-p168-2\">→ After: Ch.4: Warning by phone<\/button><\/div><\/article>"},{"i":"sc-karuizawa-kei-y1v10-p168-2","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ayanokouji-kiyotaka karuizawa-kei","q":"karuizawa kei ch 4  warning by phone calls ayanokoji in a panic to warn him   jeez  finally you pick up  tells him the whole class plans to vote him out   no duh i m panicked  like  something absolutely terrible s happened kiyotaka  says around half the class has agreed to vote against him   i dunno exactly  but  from the feel of it  it s prolly already around half the class  urges him to do something   you re gonna do something  right  like  you can do something about it  right  asks what he will do   it s no big deal or anything  but  for real  what re you gonna do  says he could have been expelled unnoticed without her   you may seem perfect  but even you have flaws okay  if i wasn t here  isn t it totally possible you could ve been expelled without noticing anything  warns him by phone","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y1v10-p168-2\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y1v10-p168-2\">Ch.4: Warning by phone<\/a><\/span><span class=\"meta\">Y1V10 · p.168–170<\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><p class=\"setup\">Calls Ayanokōji in a panic to warn him. Tells him the whole class plans to vote him out. Says around half the class has agreed to vote against him. Urges him to do something. Asks what he will do. Says he could have been expelled unnoticed without her.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “Jeez, finally you pick up…!”<span class=\"pg\">p.168<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “No duh I’m panicked… Like, something absolutely terrible’s happened Kiyotaka.”<span class=\"pg\">p.168<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “I dunno exactly… But, from the feel of it, it’s prolly already around half the class.”<span class=\"pg\">p.169<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “You’re gonna do something, right? Like, you can do something about it, right?”<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s no big deal or anything, but… For real, what’re you gonna do?”<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You may seem perfect, but even you have flaws okay? If I wasn’t here, isn’t it totally possible you could’ve been expelled without noticing anything?”<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Warns him by phone.<span class=\"pg\">p.168–170<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y1v10-p168-1\">← Before: Ch.4: Warning Ayanokōji<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y1v10-p371-1\">→ After: Short Stories: Neighbour<\/button><\/div><\/article>"},{"i":"sc-kushida-kikyou-y1v10-p174-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ayanokouji-kiyotaka yamauchi-haruki sakayanagi-arisu kushida-kikyou","q":"kushida kikyo ch 4  revealing the mastermind ayanokoji calls kushida  she says she knows he is in a pinch  kushida says she is the only one who knows who the mastermind is   i regret to have to inform you this  but i m the only one who knows who the mastermind is  kushida reveals yamauchi haruki is the tentative mastermind   it s yamauchi kun  kushida reveals sakayanagi arisu is supporting yamauchi behind the scenes   sakayanagi san from class a seems to be the one supporting yamauchi kun  reveals yamauchi as tentative mastermind and sakayanagi s support  named as tentative mastermind  named as supporting yamauchi","h":"<article class=\"card\" id=\"sc-kushida-kikyou-y1v10-p174-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kushida-kikyou.html#sc-kushida-kikyou-y1v10-p174-1\">Ch.4: Revealing the mastermind<\/a><\/span><span class=\"meta\">Y1V10 · p.174–181<\/span><span class=\"by\">notes on <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/span><\/h3><p class=\"setup\">Ayanokōji calls Kushida; she says she knows he is in a pinch. Kushida says she is the only one who knows who the mastermind is. Kushida reveals Yamauchi Haruki is the tentative mastermind. Kushida reveals Sakayanagi Arisu is supporting Yamauchi behind the scenes.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> “I regret to have to inform you this, but I’m the only one who knows who the mastermind is.”<span class=\"pg\">p.176<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> “It’s Yamauchi-kun.”<span class=\"pg\">p.179<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> “Sakayanagi-san from Class A seems to be the one supporting Yamauchi-kun.”<span class=\"pg\">p.180<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Reveals Yamauchi as tentative mastermind and Sakayanagi’s support.<span class=\"pg\">p.174–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Named as tentative mastermind.<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Named as supporting Yamauchi.<span class=\"pg\">p.180<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kushida-kikyou-y1v10-p30-1\">← Before: Ch.2: The Class Vote<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kushida-kikyou-y1v10-p174-2\">→ After: Ch.4: Revealing the mastermind<\/button><\/div><\/article>"},{"i":"sc-kushida-kikyou-y1v10-p174-2","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ayanokouji-kiyotaka kushida-kikyou","q":"kushida kikyo ch 4  revealing the mastermind greets ayanokoji and notes he is in a pinch   good evening  ayanokoji kun  i somehow thought i d be getting a call from you today   yep  looks like you re in quite the pinch  refuses to leak information because she would be targeted next   oh don t tell me that you wanted me to clue you in just because of our cooperative relationship  okay  if i leaked any information to you  i d be the one being targeted next time  after all  names yamauchi as the tentative mastermind   it s yamauchi kun  confirms sakayanagi is supporting yamauchi from behind the scenes   it s surprising  but  yes  that s exactly what s going on  tells him who is behind the expulsion plot","h":"<article class=\"card\" id=\"sc-kushida-kikyou-y1v10-p174-2\"><h3><span class=\"ttl\"><a href=\"../../../people/kushida-kikyou.html#sc-kushida-kikyou-y1v10-p174-2\">Ch.4: Revealing the mastermind<\/a><\/span><span class=\"meta\">Y1V10 · p.174–180<\/span><span class=\"by\">notes on <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/span><\/h3><p class=\"setup\">Greets Ayanokōji and notes he is in a pinch. Refuses to leak information because she would be targeted next. Names Yamauchi as the tentative mastermind. Confirms Sakayanagi is supporting Yamauchi from behind the scenes.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> “Good evening, Ayanokōji-kun. I somehow thought I’d be getting a call from you today.”<span class=\"pg\">p.174<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> “Yep. Looks like you’re in quite the pinch.”<span class=\"pg\">p.174<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> “Oh don’t tell me that you wanted me to clue you in just because of our cooperative relationship, okay? If I leaked any information to you, I’d be the one being targeted next time, after all~”<span class=\"pg\">p.174<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “It’s Yamauchi-kun.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s surprising, but, yes, that’s exactly what’s going on.”<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Tells him who is behind the expulsion plot.<span class=\"pg\">p.174–180<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kushida-kikyou-y1v10-p174-1\">← Before: Ch.4: Revealing the mastermind<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kushida-kikyou-y1v10-p206-1\">→ After: Ch.5: Retraction under pressure<\/button><\/div><\/article>"},{"i":"sc-yamauchi-haruki-y1v10-p179-1","v":"y1v10","y":1,"o":12,"k":"","w":"sakayanagi-arisu kushida-kikyou yamauchi-haruki","q":"yamauchi haruki ch 4  named as mastermind kushida reveals yamauchi haruki is the tentative mastermind targeting ayanokoji  tentative mastermind of the group targeting ayanokoji in the class poll  supported behind the scenes by sakayanagi arisu  kushida reveals him as the tentative mastermind","h":"<article class=\"card\" id=\"sc-yamauchi-haruki-y1v10-p179-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamauchi-haruki.html#sc-yamauchi-haruki-y1v10-p179-1\">Ch.4: Named as mastermind<\/a><\/span><span class=\"meta\">Y1V10 · p.179–180<\/span><span class=\"by\">notes on <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a><\/span><\/h3><p class=\"setup\">Kushida reveals Yamauchi Haruki is the tentative mastermind targeting Ayanokōji.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Position<\/span> Tentative mastermind of the group targeting Ayanokōji in the Class Poll.<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Supported behind the scenes by Sakayanagi Arisu.<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Kushida reveals him as the tentative mastermind.<span class=\"pg\">p.179–180<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamauchi-haruki-y1v10-p30-1\">← Before: Ch.2: The Class Vote<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamauchi-haruki-y1v10-p197-1\">→ After: Ch.5: Exposed and cornered<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-arisu-y1v10-p180-1","v":"y1v10","y":1,"o":12,"k":"","w":"yamauchi-haruki ayanokouji-kiyotaka sakayanagi-arisu","q":"sakayanagi arisu ch 4  supporting yamauchi kushida reveals sakayanagi arisu is supporting yamauchi behind the scenes to target ayanokoji  this appears to violate her earlier agreement to postpone their match and not cast censure votes for ayanokoji  supports him behind the scenes  her support of yamauchi targets him","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y1v10-p180-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y1v10-p180-1\">Ch.4: Supporting Yamauchi<\/a><\/span><span class=\"meta\">Y1V10 · p.180–181<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><p class=\"setup\">Kushida reveals Sakayanagi Arisu is supporting Yamauchi behind the scenes to target Ayanokōji.<\/p><p class=\"with\">with <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> This appears to violate her earlier agreement to postpone their match and not cast censure votes for Ayanokōji.<span class=\"pg\">p.180–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Supports him behind the scenes.<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Her support of Yamauchi targets him.<span class=\"pg\">p.180–181<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y1v10-p117-1\">← Before: Ch.3: Sakayanagi’s decision and postponed match<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y1v10-p262-1\">→ After: Ch.6: Orchestrating Yamauchi and Class A’s decision<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v10-p182-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"horikita-suzune hirata-yousuke horikita-manabu yamauchi-haruki kushida-kikyou kouenji-rokusuke sudou-ken ike-kanji ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 5  good and evil in the morning classroom  most students glance at ayanokoji and look away  he realises the large group has begun acting to expel him  sudo arrives with horikita  horikita asks ayanokoji what he did and he denies doing anything  horikita meets her brother manabu at the special building  as relayed in the chapter  to seek courage before the vote  after school  horikita stands before the class and nominates yamauchi haruki for expulsion   for this special exam  i have decided that we should expel yamauchi haruki kun  horikita exposes yamauchi s collusion with sakayanagi and his targeting of ayanokoji  koenji supports hearing her out  kushida retracts her support for yamauchi after the class turns against him  sudo objects to expelling yamauchi  hirata later refuses to accept the discussion and breaks down  chabashira closes by telling the class to think carefully before voting tomorrow  the ayanokoji group goes to the cafe to discuss the fallout and plans to cast censure votes for yamauchi  ayanokoji finds hirata on a bench and talks with him alone   could i entrust it to you  hirata says he can no longer lead the class  ayanokoji listens as hirata struggles with the idea of leaving someone behind  confronts the class and nominates yamauchi  meets suzune and helps her find resolve  chapter scene  breaks down in class and later asks ayanokoji to lead the class  exposed as mastermind colluding with sakayanagi and targeting ayanokoji  retracts her support for yamauchi when blamed  supports horikita s nomination to avoid his own risk  objects to expelling yamauchi but backs down  drawn into accusations and questions yamauchi s ties to sakayanagi","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v10-p182-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v10-p182-1\">Ch.5: Good and Evil<\/a><\/span><span class=\"meta\">Y1V10 · p.182–237<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">In the morning classroom, most students glance at Ayanokōji and look away; he realises the large group has begun acting to expel him. Sudō arrives with Horikita; Horikita asks Ayanokōji what he did and he denies doing anything. Horikita meets her brother Manabu at the special building (as relayed in the chapter) to seek courage before the vote. After school, Horikita stands before the class and nominates Yamauchi Haruki for expulsion. Horikita exposes Yamauchi’s collusion with Sakayanagi and his targeting of Ayanokōji; Kōenji supports hearing her out. Kushida retracts her support for Yamauchi after the class turns against him. Sudō objects to expelling Yamauchi; Hirata later refuses to accept the discussion and breaks down. Chabashira closes by telling the class to think carefully before voting tomorrow. The Ayanokōji Group goes to the cafe to discuss the fallout and plans to cast censure votes for Yamauchi. Ayanokōji finds Hirata on a bench and talks with him alone. Hirata says he can no longer lead the class; Ayanokōji listens as Hirata struggles with the idea of leaving someone behind.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> <span class=\"n\">+2 more<\/span><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “For this special exam… I have decided that we should expel Yamauchi Haruki-kun.”<span class=\"pg\">p.201<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “Could I entrust it to you?”<span class=\"pg\">p.235<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Confronts the class and nominates Yamauchi.<span class=\"pg\">p.184, 197–225<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Meets Suzune and helps her find resolve (chapter scene).<span class=\"pg\">p.186–195<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Breaks down in class and later asks Ayanokōji to lead the class.<span class=\"pg\">p.221–237<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Exposed as mastermind colluding with Sakayanagi and targeting Ayanokōji.<span class=\"pg\">p.197–225<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Retracts her support for Yamauchi when blamed.<span class=\"pg\">p.206–212<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Supports Horikita’s nomination to avoid his own risk.<span class=\"pg\">p.209–215<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Objects to expelling Yamauchi but backs down.<span class=\"pg\">p.184, 216–217<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Drawn into accusations and questions Yamauchi’s ties to Sakayanagi.<span class=\"pg\">p.206, 211<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v10-p148-1\">← Before: Ch.4: The target and the mastermind<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v10-p286-1\">→ After: Epilogue: The dropouts and the deals behind them<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y1v10-p182-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"horikita-manabu ayanokouji-kiyotaka yamauchi-haruki kushida-kikyou hirata-yousuke sudou-ken horikita-suzune","q":"horikita suzune ch 5  good and evil arrives at school with sudo and quietly asks ayanokoji what he did regarding her  at lunch break  she recalls receiving a message from her brother manabu the night before asking if there was anything she regretted  she asks manabu to meet in person and arranges to talk at the special building  she tells manabu she wants to face the supplementary exam head on and asks him to give her courage   what i wanted to talk with you about today  please  give me courage  manabu asks about school and ayanokoji  she says she wants to surpass him someday  manabu tells her she can grow at her own pace  and suzune admits she is scared of the distance between them  after school  horikita asks the class to stay and says she has something to say about the special exam  she nominates yamauchi haruki for expulsion and states her reason   for this special exam  i have decided that we should expel yamauchi haruki kun  she explains yamauchi s low contribution compared to others and insists the nomination is not based on sentiment  when kushida is drawn into the accusations  horikita rebukes her for using her influence irresponsibly  she exposes yamauchi s collusion with sakayanagi and his attempt to have ayanokoji expelled  she tells the class the choice is between yamauchi and ayanokoji based on contribution and betrayal  and invites others to vote as they see fit  she rejects sudo s plea to protect yamauchi  arguing the exam is about theory rather than sentiment  hirata refuses to accept the process  horikita says there is no other way under the exam s rules  meets him at the special building and gains resolve from their conversation  questions him in the morning  defends him as the better choice than yamauchi  nominates him for expulsion and exposes his collusion with sakayanagi  rebukes her for helping target ayanokoji  overrules his attempt to stop the discussion  rejects his plea to protect yamauchi   it s me  suzune   yes   uh  your message  why did you send me it   n no that s not it   if it s okay with you  would you be willing to meet with me in person   y yes   it s something i want to ask you about in person   this will be the last time  after this  i will not involve myself with you ever again   sorry to keep you waiting   if we don t count what happened immediately after i enrolled here  about three years   it has to do with this supplementary exam  you re aware of what the firstyears are going through  right   yes   it s nothing like that  i had never considered asking you for that kind of support   i want to face this exam head on  other people are forming groups  trying to take control of the votes in order to ensure that they re safe from expulsion  but  they ll definitely regret doing that later on down the line  that s why i  i want to stand up against them   i don t have any plans after this   i i m sorry  that  uh   whether or not i enjoy being here  i honestly don t know  at the very least  it s not boring   my shortcomings   you somehow  seem different today   that s because  you ve always been my role model   i understand  that it s absolutely impossible for me to catch up with you  but still  striving to shorten the distance as much as possible shouldn t be a bad thing   what do i  think of him   he s an irritable classmate  even though he s capable enough to be recognized by you  i don t like how he doesn t even try to make use of it  but  i think that  someday  i ll be able to catch up with him and  hopefully  surpass him   my own pace   yes   what can i do  what can i do to get rid of this distance","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v10-p182-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v10-p182-1\">Ch.5: Good and Evil<\/a><\/span><span class=\"meta\">Y1V10 · p.182–237<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Arrives at school with Sudō and quietly asks Ayanokōji what he did regarding her. At lunch break, she recalls receiving a message from her brother Manabu the night before asking if there was anything she regretted. She asks Manabu to meet in person and arranges to talk at the special building. She tells Manabu she wants to face the supplementary exam head-on and asks him to give her courage. Manabu asks about school and Ayanokōji; she says she wants to surpass him someday. Manabu tells her she can grow at her own pace, and Suzune admits she is scared of the distance between them. After school, Horikita asks the class to stay and says she has something to say about the special exam. She nominates Yamauchi Haruki for expulsion and states her reason. She explains Yamauchi’s low contribution compared to others and insists the nomination is not based on sentiment. When Kushida is drawn into the accusations, Horikita rebukes her for using her influence irresponsibly. She exposes Yamauchi’s collusion with Sakayanagi and his attempt to have Ayanokōji expelled. She tells the class the choice is between Yamauchi and Ayanokōji based on contribution and betrayal, and invites others to vote as they see fit. She rejects Sudō’s plea to protect Yamauchi, arguing the exam is about theory rather than sentiment. Hirata refuses to accept the process; Horikita says there is no other way under the exam’s rules.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “What I wanted to talk with you about today… Please, give me courage.”<span class=\"pg\">p.191<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “For this special exam… I have decided that we should expel Yamauchi Haruki-kun.”<span class=\"pg\">p.201<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “…It’s me. Suzune.”<span class=\"pg\">p.187<\/span><\/li><\/ul><details class=\"more\"><summary>31 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Meets him at the special building and gains resolve from their conversation.<span class=\"pg\">p.186–195<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Questions him in the morning; defends him as the better choice than Yamauchi.<span class=\"pg\">p.184, 214<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Nominates him for expulsion and exposes his collusion with Sakayanagi.<span class=\"pg\">p.201–218<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Rebukes her for helping target Ayanokōji.<span class=\"pg\">p.207–209<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Overrules his attempt to stop the discussion.<span class=\"pg\">p.200, 219–221<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Rejects his plea to protect Yamauchi.<span class=\"pg\">p.216–217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes…”<span class=\"pg\">p.187<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Uh, your message… Why did you send me it…”<span class=\"pg\">p.187<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “N-no that’s not it.”<span class=\"pg\">p.187<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If it’s okay with you… would you be willing to meet with me in person?”<span class=\"pg\">p.187<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Y-yes.”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s something I want to ask you about in person.”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This will be the last time… After this, I will not involve myself with you ever again.”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry to keep you waiting…”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…If we don’t count what happened immediately after I enrolled here, about three years…”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It has to do with this supplementary exam. You’re aware of what the firstyears are going through, right?”<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes.”<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s nothing like that. I had never considered asking you for that kind of support.”<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I want to face this exam head-on. Other people are forming groups, trying to take control of the votes in order to ensure that they’re safe from expulsion. But, they’ll definitely regret doing that later on down the line. That’s why I… I want to stand up against them.”<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t have any plans after this…”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I-I’m sorry. That, uh…”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Whether or not I enjoy being here… I honestly don’t know. At the very least, it’s not boring.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “My shortcomings…?”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You somehow… seem different today.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s because… you’ve always been my role model.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…I understand. That it’s absolutely impossible for me to catch up with you. But still, striving to shorten the distance as much as possible shouldn’t be a bad thing.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…What do I, think of him?”<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “He’s an irritable classmate. Even though he’s capable enough to be recognized by you, I don’t like how he doesn’t even try to make use of it. But, I think that, someday, I’ll be able to catch up with him and, hopefully, surpass him.”<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “My own pace…”<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Yes…”<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What can I do…? What can I do to get rid of this distance…?”<span class=\"pg\">p.195<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v10-p152-1\">← Before: Ch.4: Classroom atmosphere<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v10-p286-1\">→ After: Epilogue: Morning vote and aftermath<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v10-p184-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"horikita-suzune yamauchi-haruki ike-kanji sudou-ken","q":"sudo ken ch 5  objection to expelling yamauchi arrives at school with horikita in the morning  horikita names sudo just behind ike in her assessment of low contribution candidates  he accepts her point  when yamauchi is cornered  sudo says he understands the situation but is against expelling his friend   hold up  suzune  i think i understand the gist of the situation  i also get that haruki is the one in the wrong here  but  i m against having haruki get expelled  horikita argues protecting one person means abandoning another  sudo falls silent and apologises to yamauchi  at the cafe discussion  the ayanokoji group lists sudo among boys likely to give yamauchi support or sympathy votes  arrives with her and argues against her nomination of yamauchi  tries to protect him as a friend  named alongside him among low contribution candidates","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v10-p184-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y1v10-p184-1\">Ch.5: Objection to expelling Yamauchi<\/a><\/span><span class=\"meta\">Y1V10 · p.184–229<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"setup\">Arrives at school with Horikita in the morning. Horikita names Sudō just behind Ike in her assessment of low-contribution candidates; he accepts her point. When Yamauchi is cornered, Sudō says he understands the situation but is against expelling his friend. Horikita argues protecting one person means abandoning another; Sudō falls silent and apologises to Yamauchi. At the cafe discussion, the Ayanokōji Group lists Sudō among boys likely to give Yamauchi support or sympathy votes.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “Hold up, Suzune… I think I understand the gist of the situation. I also get that Haruki is the one in the wrong here… But, I’m against having Haruki get expelled.”<span class=\"pg\">p.216<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Arrives with her and argues against her nomination of Yamauchi.<span class=\"pg\">p.184, 216–217<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Tries to protect him as a friend.<span class=\"pg\">p.216–217<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Named alongside him among low-contribution candidates.<span class=\"pg\">p.203<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v10-p149-1\">← Before: Ch.4: Morning walk<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v10-p299-1\">→ After: Epilogue: Yamauchi’s expulsion<\/button><\/div><\/article>"},{"i":"sc-horikita-manabu-y1v10-p186-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"horikita-suzune ayanokouji-kiyotaka horikita-manabu","q":"horikita manabu ch 5  meeting with suzune meets suzune at the special building after she asks to talk in person  asks suzune how long it has been since they talked alone and recalls when he pushed her away before entering the school  listens as suzune explains the supplementary exam and asks him for courage  asks suzune what she thinks of the school and whether she enjoys it  tells her she has overcome focusing only on herself and has broadened her horizons  asks for her impression of ayanokoji and tells her she will never catch up to him but can grow at her own pace   it s unfortunate  but you ll never be able to catch up to ayanokoji  encourages suzune to take a step forward and tells her he will help her find the answers she is looking for  meets her  questions her  and helps her find resolve before the class vote  gives suzune his assessment that she will not catch up to ayanokoji   you said you wanted to talk   what did you want to talk about   is that really important right now  is this really what you needed to talk to me about over the phone   in person   when you first enrolled here  i suggested that it would be better for you to drop out  the moment you rejected my offer  your relationship with me was over  you do understand that  don t you   alright  i understand   how long has it been since the two of us talked alone like this   i see  it has probably been around that long   you said that you wanted to talk with me  so let s hear it   mhm  each class is being forced to expel one student   and   if you re asking about my own personal supply of private points  it was nearly exhausted back during the training camp  in which case  you re just wasting your time   how much time do you have   really   then  i d like to ask you a few things before i hear you out  what do you think of this school   are you enjoying it here   is that so   it seems you ve managed to overcome one of your shortcomings   indeed  you focused so much on yourself that you never paid attention to what was going on around you  by broadening your own horizons  you ve managed to break away from spending your days in boredom   you only ever paid attention to my academic achievements  always obsessed with scoring high on tests   role model  huh   what do you think of ayanokoji   just tell me your honest impression of him   that said  there s no need for you to catch up with him  it s absolutely fine for you to grow at your own pace   are you scared   to get closer  you have to be willing to take a step forward   let me help you find the answers you re looking for  so tell me  what do you want to put forward to your class","h":"<article class=\"card\" id=\"sc-horikita-manabu-y1v10-p186-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-manabu.html#sc-horikita-manabu-y1v10-p186-1\">Ch.5: Meeting with Suzune<\/a><\/span><span class=\"meta\">Y1V10 · p.186–195<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/span><\/h3><p class=\"setup\">Meets Suzune at the special building after she asks to talk in person. Asks Suzune how long it has been since they talked alone and recalls when he pushed her away before entering the school. Listens as Suzune explains the supplementary exam and asks him for courage. Asks Suzune what she thinks of the school and whether she enjoys it. Tells her she has overcome focusing only on herself and has broadened her horizons. Asks for her impression of Ayanokōji and tells her she will never catch up to him but can grow at her own pace. Encourages Suzune to take a step forward and tells her he will help her find the answers she is looking for.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Manabu<\/b> “It’s unfortunate, but you’ll never be able to catch up to Ayanokōji.”<span class=\"pg\">p.194<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Manabu<\/b> “You said you wanted to talk?”<span class=\"pg\">p.187<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Manabu<\/b> “What did you want to talk about?”<span class=\"pg\">p.187<\/span><\/li><\/ul><details class=\"more\"><summary>27 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Meets her, questions her, and helps her find resolve before the class vote.<span class=\"pg\">p.186–195<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Gives Suzune his assessment that she will not catch up to Ayanokōji.<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is that really important right now? Is this really what you needed to talk to me about over the phone?”<span class=\"pg\">p.187<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In person?”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “When you first enrolled here, I suggested that it would be better for you to drop out. The moment you rejected my offer, your relationship with me was over. You do understand that, don’t you?”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Alright, I understand.”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How long has it been since the two of us talked alone like this?”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see. It has probably been around that long.”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You said that you wanted to talk with me, so let’s hear it.”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Mhm. Each class is being forced to expel one student.”<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “And?”<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you’re asking about my own personal supply of private points, it was nearly exhausted back during the training camp. In which case, you’re just wasting your time.”<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How much time do you have?”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Really?”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then, I’d like to ask you a few things before I hear you out. What do you think of this school?”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you enjoying it here?”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is that so?”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seems you’ve managed to overcome one of your shortcomings.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Indeed. You focused so much on yourself that you never paid attention to what was going on around you. By broadening your own horizons, you’ve managed to break away from spending your days in boredom.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You only ever paid attention to my academic achievements, always obsessed with scoring high on tests.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Role model, huh?”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do you think of Ayanokōji?”<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Just tell me your honest impression of him.”<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That said, there’s no need for you to catch up with him. It’s absolutely fine for you to grow at your own pace.”<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you scared?”<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “To get closer, you have to be willing to take a step forward.”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let me help you find the answers you’re looking for. So tell me, what do you want to put forward to your class?”<span class=\"pg\">p.195<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-manabu-y1v10-p162-2\">← Before: Ch.4: Meeting with Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-chabashira-sae-y1v10-p197-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"horikita-suzune hirata-yousuke chabashira-sae","q":"chabashira sae ch 5  observing the class discussion ends homeroom after school and remains in the classroom as horikita asks everyone to stay  watches as horikita begins a class discussion about the special exam  is visibly impressed when horikita says they should decide who to expel rather than avoid the issue  after hirata declares he will vote for horikita and the discussion ends  chabashira asks if horikita is finished and then addresses the class  she tells the students she will not give her perspective on their discussion but urges them to think carefully before voting tomorrow   i m not going to provide my perspective on this discussion of yours  i believe everybody s participation has been valuable  i hope you all think carefully before you cast your votes tomorrow  observes her leadership of the class discussion and confirms when she is finished  witnesses his refusal to accept expelling a classmate","h":"<article class=\"card\" id=\"sc-chabashira-sae-y1v10-p197-1\"><h3><span class=\"ttl\"><a href=\"../../../people/chabashira-sae.html#sc-chabashira-sae-y1v10-p197-1\">Ch.5: Observing the class discussion<\/a><\/span><span class=\"meta\">Y1V10 · p.197–226<\/span><span class=\"by\">notes on <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/span><\/h3><p class=\"setup\">Ends homeroom after school and remains in the classroom as Horikita asks everyone to stay. Watches as Horikita begins a class discussion about the special exam. Is visibly impressed when Horikita says they should decide who to expel rather than avoid the issue. After Hirata declares he will vote for Horikita and the discussion ends, Chabashira asks if Horikita is finished and then addresses the class. She tells the students she will not give her perspective on their discussion but urges them to think carefully before voting tomorrow.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Chabashira Sae<\/b> “I’m not going to provide my perspective on this discussion of yours. I believe everybody’s participation has been valuable. I hope you all think carefully before you cast your votes tomorrow.”<span class=\"pg\">p.226<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Observes her leadership of the class discussion and confirms when she is finished.<span class=\"pg\">p.197–226<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Witnesses his refusal to accept expelling a classmate.<span class=\"pg\">p.221–225<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y1v10-p30-1\">← Before: Ch.2: The Class Vote<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y1v10-p291-1\">→ After: Epilogue: Conducting the vote and aftermath<\/button><\/div><\/article>"},{"i":"sc-yamauchi-haruki-y1v10-p197-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"horikita-suzune kushida-kikyou sakayanagi-arisu ayanokouji-kiyotaka ike-kanji yamauchi-haruki","q":"yamauchi haruki ch 5  exposed and cornered tries to leave with ike after school before horikita can speak  but is forced to stay  horikita nominates him for expulsion as the student with the lowest contribution to the class  he protests and tries to deflect blame onto others  including ike and sudo   w why me  horikitaa  when horikita presses for the mastermind  yamauchi first blames ike  then says kushida asked him to help target ayanokoji   no  no  so  err  kikyo chan came to me  asking for help  she said that there was someone who was in a lot of trouble  so she needed me to cast my censure vote for ayanokoji  he insists kushida told him to do it as the class turns against him  horikita exposes his collusion with sakayanagi  yamauchi denies it and claims having her contact is not suspicious   i i m telling you  why would i join up with class a  i d never betray my friends  this is really the first time i ve ever heard about this  come on and give me a break already  he reacts strongly when horikita suggests sakayanagi may have offered him a relationship as motivation  he argues that targeting ayanokoji was unreasonable and that he was only trying to protect himself  after kushida retracts her support  yamauchi panics as the class consensus turns toward expelling him  publicly nominated for expulsion in the class poll after being exposed as colluding with sakayanagi to target ayanokoji  nominates and corners him in front of the class  tries to shift blame to her  but she retracts support  exposed as colluding with her behind the scenes  targeted him for censure votes under the scheme  tries to leave with him and later questions his ties to sakayanagi","h":"<article class=\"card\" id=\"sc-yamauchi-haruki-y1v10-p197-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamauchi-haruki.html#sc-yamauchi-haruki-y1v10-p197-1\">Ch.5: Exposed and cornered<\/a><\/span><span class=\"meta\">Y1V10 · p.197–225<\/span><span class=\"by\">notes on <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a><\/span><\/h3><p class=\"setup\">Tries to leave with Ike after school before Horikita can speak, but is forced to stay. Horikita nominates him for expulsion as the student with the lowest contribution to the class. He protests and tries to deflect blame onto others, including Ike and Sudō. When Horikita presses for the mastermind, Yamauchi first blames Ike, then says Kushida asked him to help target Ayanokōji. He insists Kushida told him to do it as the class turns against him. Horikita exposes his collusion with Sakayanagi; Yamauchi denies it and claims having her contact is not suspicious. He reacts strongly when Horikita suggests Sakayanagi may have offered him a relationship as motivation. He argues that targeting Ayanokōji was unreasonable and that he was only trying to protect himself. After Kushida retracts her support, Yamauchi panics as the class consensus turns toward expelling him.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yamauchi Haruki<\/b> “W-why me, Horikitaa!?”<span class=\"pg\">p.202<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yamauchi Haruki<\/b> “No, no! So, err… Kikyō-chan came to me, asking for help… She said that there was someone who was in a lot of trouble, so she needed me to cast my censure vote for Ayanokōji.”<span class=\"pg\">p.206<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yamauchi Haruki<\/b> “I-I’m telling you… Why would I join up with Class A!? I’d never betray my friends! This is really the first time I’ve ever heard about this! Come on and give me a break already…!”<span class=\"pg\">p.211<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Position<\/span> Publicly nominated for expulsion in the Class Poll after being exposed as colluding with Sakayanagi to target Ayanokōji.<span class=\"pg\">p.201–225<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Nominates and corners him in front of the class.<span class=\"pg\">p.201–218<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Tries to shift blame to her, but she retracts support.<span class=\"pg\">p.206–218<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Exposed as colluding with her behind the scenes.<span class=\"pg\">p.210–215<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Targeted him for censure votes under the scheme.<span class=\"pg\">p.206–215<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Tries to leave with him and later questions his ties to Sakayanagi.<span class=\"pg\">p.198, 206, 211<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamauchi-haruki-y1v10-p179-1\">← Before: Ch.4: Named as mastermind<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamauchi-haruki-y1v10-p266-1\">→ After: Ch.6: Manipulated by Sakayanagi<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v10-p200-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"horikita-suzune ayanokouji-kiyotaka yamauchi-haruki hirata-yousuke","q":"hirata yosuke ch 5  refusal and collapse tries to stop horikita from throwing the class into chaos by nominating someone for expulsion   no way  i m against you throwing the class into chaos like this  after the class turns against yamauchi  hirata insists the discussion is wrong and says it would be better to hold a fair vote without this  hirata kicks over his desk and shouts at horikita to stop   would you just stop  horikita san  he declares he will cast his censure vote for horikita for causing problems for the class   that s why i m going to cast my vote for you tomorrow  horikita san  i won t allow you to cause problems for this class again  leaves the classroom alone after chabashira dismisses the class  sits alone on a bench outside the dorms with a defeated expression  when ayanokoji speaks to him  hirata says he wanted to talk as well  he says he hates leaving someone behind and asks ayanokoji to lead class c in his stead   having to leave someone behind  i hate it   could i entrust it to you  he says it is impossible for him to continue leading and that he can no longer do it   that s impossible  i  just can t do that anymore   i m glad i talked with you  i  i really feel like i might be able to find an answer now  opposes her nomination process and says he will vote for her  talks with him on the bench and asks him to lead the class  refuses to accept expelling him despite the accusations","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v10-p200-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v10-p200-1\">Ch.5: Refusal and collapse<\/a><\/span><span class=\"meta\">Y1V10 · p.200–237<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Tries to stop Horikita from throwing the class into chaos by nominating someone for expulsion. After the class turns against Yamauchi, Hirata insists the discussion is wrong and says it would be better to hold a fair vote without this. Hirata kicks over his desk and shouts at Horikita to stop. He declares he will cast his censure vote for Horikita for causing problems for the class. Leaves the classroom alone after Chabashira dismisses the class. Sits alone on a bench outside the dorms with a defeated expression. When Ayanokōji speaks to him, Hirata says he wanted to talk as well. He says he hates leaving someone behind and asks Ayanokōji to lead Class C in his stead. He says it is impossible for him to continue leading and that he can no longer do it.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “No way. I’m against you throwing the class into chaos like this.”<span class=\"pg\">p.200<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “Would you just stop, Horikita-san?”<span class=\"pg\">p.221<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “That’s why I’m going to cast my vote for you tomorrow, Horikita-san. I won’t allow you to cause problems for this class again.”<span class=\"pg\">p.225<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Having to leave someone behind… I hate it.”<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Could I entrust it to you?”<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s impossible. I… just can’t do that anymore.”<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m glad I talked with you. I… I really feel like I might be able to find an answer now.”<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Opposes her nomination process and says he will vote for her.<span class=\"pg\">p.200, 221–225<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Talks with him on the bench and asks him to lead the class.<span class=\"pg\">p.233–237<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Refuses to accept expelling him despite the accusations.<span class=\"pg\">p.219–221<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v10-p150-1\">← Before: Ch.4: Classroom atmosphere<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v10-p288-1\">→ After: Epilogue: Volunteering and aftermath<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y1v10-p200-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"horikita-suzune yamauchi-haruki ayanokouji-kiyotaka kouenji-rokusuke","q":"koenji rokusuke ch 5  supporting horikita s nomination encourages horikita to speak when she asks the class to stay  saying he has given up his time to hear her  remarks that trying to expel someone else to survive is natural in this exam and questions condemning yamauchi alone  presses yamauchi on why he targeted ayanokoji and calls it unpleasant that yamauchi colluded with class a  states that horikita s proposal is desirable and gives her his support   no objections here  i believe that horikita girl s proposal is quite desirable  we certainly don t want to keep around someone who could potentially betray the class  i certainly couldn t spend time with a student who could potentially betray the class  she has my support  supports her move to nominate yamauchi  questions and condemns him for colluding with class a  asks why yamauchi targeted him","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y1v10-p200-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y1v10-p200-1\">Ch.5: Supporting Horikita’s nomination<\/a><\/span><span class=\"meta\">Y1V10 · p.200–215<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><p class=\"setup\">Encourages Horikita to speak when she asks the class to stay, saying he has given up his time to hear her. Remarks that trying to expel someone else to survive is natural in this exam and questions condemning Yamauchi alone. Presses Yamauchi on why he targeted Ayanokōji and calls it unpleasant that Yamauchi colluded with Class A. States that Horikita’s proposal is desirable and gives her his support.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “No objections here. I believe that Horikita-girl’s proposal is quite desirable. We certainly don’t want to keep around someone who could potentially betray the class. I certainly couldn’t spend time with a student who could…”<span class=\"pg\">p.215<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “No objections here. I believe that Horikita-girl’s proposal is quite desirable. We certainly don’t want to keep around someone who could potentially betray the class. I certainly couldn’t spend time with a student who could potentially betray the class. She has my support.”<span class=\"pg\">p.215<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Supports her move to nominate Yamauchi.<span class=\"pg\">p.200, 215<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Questions and condemns him for colluding with Class A.<span class=\"pg\">p.209–215<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Asks why Yamauchi targeted him.<span class=\"pg\">p.210<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y1v10-p30-1\">← Before: Ch.2: The Class Vote<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y1v10-p299-1\">→ After: Epilogue: Provoking Yamauchi<\/button><\/div><\/article>"},{"i":"sc-kushida-kikyou-y1v10-p206-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"yamauchi-haruki horikita-suzune ayanokouji-kiyotaka kushida-kikyou","q":"kushida kikyo ch 5  retraction under pressure ike names kushida as the one who asked him to help  drawing attention to her role as intermediary  yamauchi claims kushida told him to target ayanokoji  kushida is shocked and tries to defend herself   m me  as the class sides with her over yamauchi  kushida weeps and says she only wanted to help   you re so cruel yamauchi kun  i  even though i really didn t want to abandon ayanokoji kun  you came asking for my help  but  even though i did the best i could  horikita rebukes kushida for using her influence to gather votes against ayanokoji  kushida falters under horikita s pressure but maintains her outward persona  she publicly retracts her support for yamauchi and asks the class to take back the votes she requested   i  take back everything  i made a mistake  i wanted to help yamauchi kun  but i didn t realize the gravity of the situation  i m taking back what i asked of everyone  distances herself from him and retracts her support  is rebuked by her for her role in gathering votes  frames her earlier actions as reluctant help despite not wanting to abandon him","h":"<article class=\"card\" id=\"sc-kushida-kikyou-y1v10-p206-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kushida-kikyou.html#sc-kushida-kikyou-y1v10-p206-1\">Ch.5: Retraction under pressure<\/a><\/span><span class=\"meta\">Y1V10 · p.206–218<\/span><span class=\"by\">notes on <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/span><\/h3><p class=\"setup\">Ike names Kushida as the one who asked him to help, drawing attention to her role as intermediary. Yamauchi claims Kushida told him to target Ayanokōji; Kushida is shocked and tries to defend herself. As the class sides with her over Yamauchi, Kushida weeps and says she only wanted to help. Horikita rebukes Kushida for using her influence to gather votes against Ayanokōji. Kushida falters under Horikita’s pressure but maintains her outward persona. She publicly retracts her support for Yamauchi and asks the class to take back the votes she requested.<\/p><p class=\"with\">with <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> “M-me!?”<span class=\"pg\">p.207<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> “You’re so cruel Yamauchi-kun… I… even though I really didn’t want to abandon Ayanokōji-kun, you came asking for my help… but, even though I did the best I could…”<span class=\"pg\">p.208<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> “…I… take back everything… I made a mistake… I wanted to help Yamauchi-kun… but I didn’t realize the gravity of the situation. I’m taking back what I asked of everyone…”<span class=\"pg\">p.218<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Distances herself from him and retracts her support.<span class=\"pg\">p.206–218<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Is rebuked by her for her role in gathering votes.<span class=\"pg\">p.208–209<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Frames her earlier actions as reluctant help despite not wanting to abandon him.<span class=\"pg\">p.208<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kushida-kikyou-y1v10-p174-2\">← Before: Ch.4: Revealing the mastermind<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kushida-kikyou-y1v10-p304-1\">→ After: Epilogue: Results and aftermath<\/button><\/div><\/article>"},{"i":"sc-hasebe-haruka-y1v10-p226-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ayanokouji-kiyotaka yamauchi-haruki sakura-airi hasebe-haruka","q":"hasebe haruka ch 5  cafe discussion invites ayanokoji to the cafe with the group after class  says she will not let someone from their group be expelled even if yamauchi s group targets them   if they want to aim for us then bring it on  i absolutely won t let somebody from our group be expelled  says yamauchi is a good choice for their censure votes  backs airi s intuition about karuizawa and sato not voting against ayanokoji  supports him in the cafe discussion  supports casting censure votes for him  defends her intuition about the girls  votes","h":"<article class=\"card\" id=\"sc-hasebe-haruka-y1v10-p226-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hasebe-haruka.html#sc-hasebe-haruka-y1v10-p226-1\">Ch.5: Cafe discussion<\/a><\/span><span class=\"meta\">Y1V10 · p.226–232<\/span><span class=\"by\">notes on <a href=\"../../../people/hasebe-haruka.html\">Hasebe Haruka<\/a><\/span><\/h3><p class=\"setup\">Invites Ayanokōji to the cafe with the group after class. Says she will not let someone from their group be expelled even if Yamauchi’s group targets them. Says Yamauchi is a good choice for their censure votes. Backs Airi’s intuition about Karuizawa and Satō not voting against Ayanokōji.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hasebe Haruka<\/b> “If they want to aim for us then bring it on! I absolutely won’t let somebody from our group be expelled.”<span class=\"pg\">p.227<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Supports him in the cafe discussion.<span class=\"pg\">p.227–232<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Supports casting censure votes for him.<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakura Airi<\/b> Defends her intuition about the girls’ votes.<span class=\"pg\">p.230<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hasebe-haruka-y1v10-p154-1\">← Before: Ch.4: Ayanokōji Group discussion<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v10-p226-1","v":"y1v10","y":1,"o":12,"k":"","w":"ayanokouji-kiyotaka hirata-yousuke miyake-akito","q":"miyake akito ch 5  cafe discussion and advice nods in agreement that there is no reason for ayanokoji to be expelled  after seeing hirata on a bench  advises ayanokoji to be careful because no one knows who hirata will vote for tomorrow  supports him in the group and cautions him before he approaches hirata  notes his defeated state and warns ayanokoji to be careful","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v10-p226-1\"><h3><span class=\"ttl\"><a href=\"../../../people/miyake-akito.html#sc-miyake-akito-y1v10-p226-1\">Ch.5: Cafe discussion and advice<\/a><\/span><span class=\"meta\">Y1V10 · p.226–234<\/span><span class=\"by\">notes on <a href=\"../../../people/miyake-akito.html\">Miyake Akito<\/a><\/span><\/h3><p class=\"setup\">Nods in agreement that there is no reason for Ayanokōji to be expelled. After seeing Hirata on a bench, advises Ayanokōji to be careful because no one knows who Hirata will vote for tomorrow.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Supports him in the group and cautions him before he approaches Hirata.<span class=\"pg\">p.228, 233–234<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Notes his defeated state and warns Ayanokōji to be careful.<span class=\"pg\">p.233–234<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v10-p154-1\">← Before: Ch.4: Ayanokōji Group discussion<\/button><\/div><\/article>"},{"i":"sc-sakura-airi-y1v10-p226-1","v":"y1v10","y":1,"o":12,"k":"","w":"ayanokouji-kiyotaka horikita-suzune sakura-airi","q":"sakura airi ch 5  cafe discussion nods in agreement that there is no reason for ayanokoji to be expelled  suggests sato and karuizawa probably will not vote against ayanokoji  saying it is just a feeling  encourages ayanokoji despite her own anxiety about remaining censure votes  wonders how horikita found out about yamauchi s betrayal  supports and encourages him in the cafe discussion  wonders how she learned of yamauchi s betrayal","h":"<article class=\"card\" id=\"sc-sakura-airi-y1v10-p226-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakura-airi.html#sc-sakura-airi-y1v10-p226-1\">Ch.5: Cafe discussion<\/a><\/span><span class=\"meta\">Y1V10 · p.226–232<\/span><span class=\"by\">notes on <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a><\/span><\/h3><p class=\"setup\">Nods in agreement that there is no reason for Ayanokōji to be expelled. Suggests Satō and Karuizawa probably will not vote against Ayanokōji, saying it is just a feeling. Encourages Ayanokōji despite her own anxiety about remaining censure votes. Wonders how Horikita found out about Yamauchi’s betrayal.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Supports and encourages him in the cafe discussion.<span class=\"pg\">p.228–231<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Wonders how she learned of Yamauchi’s betrayal.<span class=\"pg\">p.231<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakura-airi-y1v10-p154-1\">← Before: Ch.4: Ayanokōji Group discussion<\/button><\/div><\/article>"},{"i":"sc-yukimura-teruhiko-y1v10-p226-1","v":"y1v10","y":1,"o":12,"k":"","w":"ayanokouji-kiyotaka yamauchi-haruki hasebe-haruka miyake-akito sakura-airi yukimura-teruhiko","q":"yukimura teruhiko ch 5  cafe discussion joins the ayanokoji group after class when they go to the cafe to discuss the fallout  agrees there is no reason for ayanokoji to be expelled and that yamauchi is the obvious censure target  notes horikita will likely give ayanokoji a praise vote and yamauchi a censure vote  and asks airi about the girls  votes  analyses the likely vote distribution  saying remaining censure votes may scatter among other options  supports him in the ayanokoji group discussion  treats him as the obvious censure target  discusses the vote with the group  discusses the vote with the group  asks her about likely votes among the girls","h":"<article class=\"card\" id=\"sc-yukimura-teruhiko-y1v10-p226-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yukimura-teruhiko.html#sc-yukimura-teruhiko-y1v10-p226-1\">Ch.5: Cafe discussion<\/a><\/span><span class=\"meta\">Y1V10 · p.226–232<\/span><span class=\"by\">notes on <a href=\"../../../people/yukimura-teruhiko.html\">Yukimura Teruhiko<\/a><\/span><\/h3><p class=\"setup\">Joins the Ayanokōji Group after class when they go to the cafe to discuss the fallout. Agrees there is no reason for Ayanokōji to be expelled and that Yamauchi is the obvious censure target. Notes Horikita will likely give Ayanokōji a praise vote and Yamauchi a censure vote, and asks Airi about the girls’ votes. Analyses the likely vote distribution, saying remaining censure votes may scatter among other options.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/hasebe-haruka.html\">Hasebe Haruka<\/a> · <a href=\"../../../people/miyake-akito.html\">Miyake Akito<\/a> · <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a><\/p><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Supports him in the Ayanokōji Group discussion.<span class=\"pg\">p.228–232<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Treats him as the obvious censure target.<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> Discusses the vote with the group.<span class=\"pg\">p.227–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Miyake Akito<\/b> Discusses the vote with the group.<span class=\"pg\">p.227–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakura Airi<\/b> Asks her about likely votes among the girls.<span class=\"pg\">p.229–230<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yukimura-teruhiko-y1v10-p152-1\">← Before: Ch.4: Classroom atmosphere<\/button><\/div><\/article>"},{"i":"sc-ishizaki-daichi-y1v10-p239-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ryuuen-kakeru ibuki-mio ishizaki-daichi","q":"ishizaki daichi ch 6  trying to save ryuen has been forced into gathering censure votes against ryuen while wanting to prevent his expulsion  takes ibuki aside to ask about ryuen s private points   come with me for a bit  ibuki  admits he does not want ryuen expelled and worries about class d without him   i don t really want to admit it  but i feel the same way  agrees with ibuki s plan to recover ryuen s private points for class d  wants to save him despite the exam s pressure  talks with her about the points and the plan","h":"<article class=\"card\" id=\"sc-ishizaki-daichi-y1v10-p239-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ishizaki-daichi.html#sc-ishizaki-daichi-y1v10-p239-1\">Ch.6: Trying to save Ryūen<\/a><\/span><span class=\"meta\">Y1V10 · p.239–246<\/span><span class=\"by\">notes on <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a><\/span><\/h3><p class=\"setup\">Has been forced into gathering censure votes against Ryūen while wanting to prevent his expulsion. Takes Ibuki aside to ask about Ryūen’s private points. Admits he does not want Ryūen expelled and worries about Class D without him. Agrees with Ibuki’s plan to recover Ryūen’s private points for Class D.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ishizaki Daichi<\/b> “Come with me for a bit, Ibuki.”<span class=\"pg\">p.242<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ishizaki Daichi<\/b> “I don’t really want to admit it, but I feel the same way.”<span class=\"pg\">p.245<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Wants to save him despite the exam’s pressure.<span class=\"pg\">p.239–246<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Talks with her about the points and the plan.<span class=\"pg\">p.242–246<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ishizaki-daichi-y1v10-p319-1\">→ After: Epilogue: Saving Ryūen (flashback)<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y1v10-p239-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ibuki-mio ryuuen-kakeru","q":"ryuen kakeru ch 6  accepting expulsion understands ishizaki is under pressure as the one credited with defeating him and decides not to resist the class s vote to expel him  leaves the classroom right after school  not wanting to waste time before the exam ends  receives a visit from ibuki  appears from the bath in boxers   kuku  i just got out of the bath  come in  transfers all his private points to ibuki after she demands them   kuku  well aren t you the smart one  whatever  take em  they re useless to me anyway  grabs ibuki when she tries to leave  then lets go and tells her to say goodbye  when ibuki asks if he is satisfied with his time at school  he is silent  ibuki leaves  meets her in his room and transfers private points to her before her departure","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y1v10-p239-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y1v10-p239-1\">Ch.6: Accepting expulsion<\/a><\/span><span class=\"meta\">Y1V10 · p.239–246<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Understands Ishizaki is under pressure as the one credited with defeating him and decides not to resist the class’s vote to expel him. Leaves the classroom right after school, not wanting to waste time before the exam ends. Receives a visit from Ibuki; appears from the bath in boxers. Transfers all his private points to Ibuki after she demands them. Grabs Ibuki when she tries to leave, then lets go and tells her to say goodbye. When Ibuki asks if he is satisfied with his time at school, he is silent; Ibuki leaves.<\/p><p class=\"with\">with <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “Kuku. I just got out of the bath, come in.”<span class=\"pg\">p.248<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “Kuku, well aren’t you the smart one. Whatever, take em. They’re useless to me anyway.”<span class=\"pg\">p.248<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Meets her in his room and transfers private points to her before her departure.<span class=\"pg\">p.247–251<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y1v10-p30-1\">← Before: Ch.2: The Class Vote<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y1v10-p249-1\">→ After: Ch.6/Epilogue: Added voice lines<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y1v10-p240-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"manabe-shiho ishizaki-daichi ryuuen-kakeru ibuki-mio","q":"ibuki mio ch 6  seeing ryuen off and recovering points watches ryuen leave the classroom after school  manabe provokes her about being less important   well well  that s quite the miserable look on your face  now isn t it  are you really  that  sad to see ryuuen get expelled  goes with ishizaki to talk about ryuen s private points   come with me for a bit  ibuki  decides to recover ryuen s private points and meet him that night   i m going to see ryuen tonight and recover the private points  i might be the only one who can  visits ryuen s dorm room  he answers in boxers after a bath  demands his private points and receives them transferred to her phone   your private points  hand them over  is grabbed by ryuen  kicked toward the wall  then released after a warning about suzune   are you satisfied with your time here  at this school  leaves ryuen s room with his points and calls someone to report she has them  visits him  recovers his private points  and receives a warning  goes with him to talk and agrees to recover the points  provoked by her after ryuen leaves","h":"<article class=\"card\" id=\"sc-ibuki-mio-y1v10-p240-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y1v10-p240-1\">Ch.6: Seeing Ryūen off and recovering points<\/a><\/span><span class=\"meta\">Y1V10 · p.240–251<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"setup\">Watches Ryūen leave the classroom after school; Manabe provokes her about being less important. Goes with Ishizaki to talk about Ryūen’s private points. Decides to recover Ryūen’s private points and meet him that night. Visits Ryūen’s dorm room; he answers in boxers after a bath. Demands his private points and receives them transferred to her phone. Is grabbed by Ryūen, kicked toward the wall, then released after a warning about Suzune. Leaves Ryūen’s room with his points and calls someone to report she has them.<\/p><p class=\"with\">with <a href=\"../../../people/manabe-shiho.html\">Manabe Shiho<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Manabe Shiho<\/b> “Well well, that’s quite the miserable look on your face, now isn’t it? Are you really ‘that’ sad to see Ryuuen get expelled?”<span class=\"pg\">p.241<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ishizaki Daichi<\/b> “Come with me for a bit, Ibuki.”<span class=\"pg\">p.242<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “I’m going to see Ryūen tonight and recover the private points. I might be the only one who can.”<span class=\"pg\">p.246<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Your private points. Hand them over.”<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you satisfied with your time here, at this school?”<span class=\"pg\">p.250<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Visits him, recovers his private points, and receives a warning.<span class=\"pg\">p.247–251<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Goes with him to talk and agrees to recover the points.<span class=\"pg\">p.242, 246<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Manabe Shiho<\/b> Provoked by her after Ryūen leaves.<span class=\"pg\">p.241<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y1v10-p245-1\">→ After: Ch.6/Epilogue: Added voice lines<\/button><\/div><\/article>"},{"i":"sc-manabe-shiho-y1v10-p240-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ibuki-mio manabe-shiho","q":"manabe shiho ch 6  provoking ibuki sees ryuen leave and approaches ibuki with provocation   well well  that s quite the miserable look on your face  now isn t it  are you really  that  sad to see ryuuen get expelled   you re gonna cast a censure vote for me  aren t you ibuki san  says ibuki will be targeted after ryuen is expelled  provokes her after ryuen leaves the classroom","h":"<article class=\"card\" id=\"sc-manabe-shiho-y1v10-p240-1\"><h3><span class=\"ttl\"><a href=\"../../../people/manabe-shiho.html#sc-manabe-shiho-y1v10-p240-1\">Ch.6: Provoking Ibuki<\/a><\/span><span class=\"meta\">Y1V10 · p.240–242<\/span><span class=\"by\">notes on <a href=\"../../../people/manabe-shiho.html\">Manabe Shiho<\/a><\/span><\/h3><p class=\"setup\">Sees Ryūen leave and approaches Ibuki with provocation. Says Ibuki will be targeted after Ryūen is expelled.<\/p><p class=\"with\">with <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Manabe Shiho<\/b> “Well well, that’s quite the miserable look on your face, now isn’t it? Are you really ‘that’ sad to see Ryuuen get expelled?”<span class=\"pg\">p.241<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Manabe Shiho<\/b> “You’re gonna cast a censure vote for me, aren’t you Ibuki-san?”<span class=\"pg\">p.241<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Provokes her after Ryūen leaves the classroom.<span class=\"pg\">p.240–242<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-manabe-shiho-y1v10-p315-1\">→ After: Epilogue: Expelled from Class D<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y1v10-p245-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ishizaki-daichi ichinose-honami ibuki-mio","q":"ibuki mio ch 6 epilogue  added voice lines asks ishizaki whether he really wants ryuen expelled   you don t really want ryuen to be expelled  do you  reports by phone that she has recovered all of ryuen s private points   it s me  i ve gotten all of ryuen s private points  tells ayanokoji she wants manabe expelled   manabe  it s just my personal preference though  calls ichinose an idiot for throwing away her points   you re an idiot  aren t you ichinose  discusses saving ryuen with him  makes the deal to save ryuen with her","h":"<article class=\"card\" id=\"sc-ibuki-mio-y1v10-p245-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y1v10-p245-1\">Ch.6/Epilogue: Added voice lines<\/a><\/span><span class=\"meta\">Y1V10 · p.245, 334, 338, 344<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"setup\">Asks Ishizaki whether he really wants Ryūen expelled. Reports by phone that she has recovered all of Ryūen’s private points. Tells Ayanokōji she wants Manabe expelled. Calls Ichinose an idiot for throwing away her points.<\/p><p class=\"with\">with <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “You don’t really want Ryūen to be expelled, do you?”<span class=\"pg\">p.245<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “It’s me. I’ve gotten all of Ryūen’s private points.”<span class=\"pg\">p.334<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “Manabe. It’s just my personal preference though.”<span class=\"pg\">p.338<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “You’re an idiot, aren’t you Ichinose?”<span class=\"pg\">p.344<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Discusses saving Ryūen with him.<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Makes the deal to save Ryūen with her.<span class=\"pg\">p.338, 344<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y1v10-p240-1\">← Before: Ch.6: Seeing Ryūen off and recovering points<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y1v10-p245-2\">→ After: Ch.6: Recalling Ayanokōji’s words<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y1v10-p245-2","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ayanokouji-kiyotaka ibuki-mio","q":"ibuki mio ch 6  recalling ayanokoji s words ibuki recalls ayanokoji s warning about the exam   this exam isn t simple enough for you to be able to save someone just because you say you want to  remembers his words while deciding whether to act","h":"<article class=\"card\" id=\"sc-ibuki-mio-y1v10-p245-2\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y1v10-p245-2\">Ch.6: Recalling Ayanokōji’s words<\/a><\/span><span class=\"meta\">Y1V10 · p.245<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"setup\">Ibuki recalls Ayanokōji’s warning about the exam.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “This exam isn’t simple enough for you to be able to save someone just because you say you want to.”<span class=\"pg\">p.245<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Remembers his words while deciding whether to act.<span class=\"pg\">p.245<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y1v10-p245-1\">← Before: Ch.6/Epilogue: Added voice lines<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y1v10-p319-1\">→ After: Epilogue: Saving Ryūen (flashback)<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y1v10-p249-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ibuki-mio ayanokouji-kiyotaka ryuuen-kakeru","q":"ryuen kakeru ch 6 epilogue  added voice lines says goodbye to ibuki after transferring his private points   goodbye ibuki  comments on surviving the class poll at the bulletin board   kuku  it seems like the grim reaper has taken pity on me  complains that being saved by ishizaki and ibuki is an annoying gift   so you re sayin  i was saved by ishizaki and ibuki  huh  what an annoying gift they ve given me  answers ayanokoji s question about a future exam with a laugh   kuku  who knows  transfers points to her and later acknowledges her role  speaks with him about how he was saved","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y1v10-p249-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y1v10-p249-1\">Ch.6/Epilogue: Added voice lines<\/a><\/span><span class=\"meta\">Y1V10 · p.249, 316, 348<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Says goodbye to Ibuki after transferring his private points. Comments on surviving the Class Poll at the bulletin board. Complains that being saved by Ishizaki and Ibuki is an annoying gift. Answers Ayanokōji’s question about a future exam with a laugh.<\/p><p class=\"with\">with <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “Goodbye Ibuki.”<span class=\"pg\">p.249<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “Kuku. It seems like the Grim Reaper has taken pity on me.”<span class=\"pg\">p.316<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “So you’re sayin’ I was saved by Ishizaki and Ibuki, huh? What an annoying gift they’ve given me.”<span class=\"pg\">p.348<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Kuku. Who knows?”<span class=\"pg\">p.348<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Transfers points to her and later acknowledges her role.<span class=\"pg\">p.249, 348<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Speaks with him about how he was saved.<span class=\"pg\">p.316, 347–348<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y1v10-p239-1\">← Before: Ch.6: Accepting expulsion<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y1v10-p315-1\">→ After: Epilogue: Survival and aftermath<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v10-p252-1","v":"y1v10","y":1,"o":12,"k":"","w":"ichinose-honami hoshinomiya-chie","q":"hoshinomiya chie ch 6  listening to ichinose as homeroom teacher listens to ichinose speak to class b after school  she feels uneasy about the exam and worries about the class unity being damaged by an expulsion  listens as ichinose assures the class no one will be expelled","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v10-p252-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hoshinomiya-chie.html#sc-hoshinomiya-chie-y1v10-p252-1\">Ch.6: Listening to Ichinose<\/a><\/span><span class=\"meta\">Y1V10 · p.252–253<\/span><span class=\"by\">notes on <a href=\"../../../people/hoshinomiya-chie.html\">Hoshinomiya Chie<\/a><\/span><\/h3><p class=\"setup\">As homeroom teacher listens to Ichinose speak to Class B after school; she feels uneasy about the exam and worries about the class unity being damaged by an expulsion.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Listens as Ichinose assures the class no one will be expelled.<span class=\"pg\">p.252–253<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ichinose-honami-y1v10-p252-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"kanzaki-ryuuji shibata-sou hoshinomiya-chie nagumo-miyabi ichinose-honami","q":"ichinose honami ch 6  saving class b after school on friday  ichinose stands at the podium and thanks class b for honoring her request to stay together  hoshinomiya worries that someone s expulsion could damage the class  but ichinose says she will not let anyone be expelled   i imagine everyone is quite worried  but i d like you all to feel at ease  i won t let a single one of us be expelled  responds to kanzaki s concern by saying she will act now that she has the power to change things   it s fine  kanzaki kun  you once told me that if somebody has the power to change things  they re nothing more than a fool if they don t make use of it  right  that s why i ve been reflecting on what i could do for all of you  explains the plan  collect all private points to pay the 20 million override and says the class is about four million short  says she asked student council president nagumo for the remainder with no interest and a three month repayment period   from student council president nagumo  when i brought our situation up with him  he told me he d be willing to supply the rest  reassures the class that none of them will be expelled  he questions her plan and she is grateful for his support  supports her and transfers his points  her teacher worries but listens as ichinose addresses the class  borrows the remaining private points from him with no interest   everyone  thank you for everything you ve done this past week  i m grateful that you all went along with my selfish request   there s only one way to ensure that everyone survives this provisional exam  right   that s why i d like to ask everybody to entrust me with all your private points  you won t have any spending points until april  but this way  everyone can be saved   yup  just as calculated  we re roughly four million points short   of course  we ll have to pay him back afterward   our repayment period is three months  and there s no interest   because of this  i feel like i ll be inconveniencing everyone for a little while  is that alright","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v10-p252-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y1v10-p252-1\">Ch.6: Saving Class B<\/a><\/span><span class=\"meta\">Y1V10 · p.252–256<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><p class=\"setup\">After school on Friday, Ichinose stands at the podium and thanks Class B for honoring her request to stay together. Hoshinomiya worries that someone’s expulsion could damage the class, but Ichinose says she will not let anyone be expelled. Responds to Kanzaki’s concern by saying she will act now that she has the power to change things. Explains the plan: collect all private points to pay the 20 million override and says the class is about four million short. Says she asked student council president Nagumo for the remainder with no interest and a three-month repayment period. Reassures the class that none of them will be expelled.<\/p><p class=\"with\">with <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a> · <a href=\"../../../people/shibata-sou.html\">Shibata Sō<\/a> · <a href=\"../../../people/hoshinomiya-chie.html\">Hoshinomiya Chie<\/a> · <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “I imagine everyone is quite worried, but I’d like you all to feel at ease. I won’t let a single one of us be expelled.”<span class=\"pg\">p.253<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “It’s fine. Kanzaki-kun, you once told me that if somebody has the power to change things, they’re nothing more than a fool if they don’t make use of it, right? That’s why I’ve been reflecting on what I could do for all of you.”<span class=\"pg\">p.253<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “From student council president Nagumo. When I brought our situation up with him, he told me he’d be willing to supply the rest.”<span class=\"pg\">p.255<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> He questions her plan and she is grateful for his support.<span class=\"pg\">p.253, 255–256<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shibata Sō<\/b> Supports her and transfers his points.<span class=\"pg\">p.253–254<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hoshinomiya Chie<\/b> Her teacher worries but listens as Ichinose addresses the class.<span class=\"pg\">p.252–253<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Borrows the remaining private points from him with no interest.<span class=\"pg\">p.255<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Everyone, thank you for everything you’ve done this past week. I’m grateful that you all went along with my selfish request.”<span class=\"pg\">p.252<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’s only one way to ensure that everyone survives this provisional exam, right?”<span class=\"pg\">p.254<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s why I’d like to ask everybody to entrust me with all your private points. You won’t have any spending points until April, but this way, everyone can be saved.”<span class=\"pg\">p.254<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yup, just as calculated, we’re roughly four million points short.”<span class=\"pg\">p.255<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course, we’ll have to pay him back afterward.”<span class=\"pg\">p.255<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Our repayment period is three months, and there’s no interest.”<span class=\"pg\">p.256<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Because of this, I feel like I’ll be inconveniencing everyone for a little while… Is that alright?”<span class=\"pg\">p.256<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v10-p89-1\">← Before: Ch.3: Morning walk and Asahina’s interruption<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v10-p253-1\">→ After: Ch.6/Epilogue: Added voice lines<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v10-p253-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"nagumo-miyabi ayanokouji-kiyotaka ichinose-honami","q":"ichinose honami ch 6 epilogue  added voice lines states she will not let a single class b student be expelled   i won t let a single one of us be expelled  asks nagumo whether he likes her before agreeing to date him   senpai  d do you  uh  do you like me  steels her resolve to protect everyone on her own   i  will protect everyone  confirms she will use class b s twenty million points to save one of her classmates   with twenty million points  i ll save one of my classmates  right  tells ayanokoji she will rise to class a with her friends   i m gonna rise up to class a together with all my friends and graduate  asks him whether he likes her  confirms the deal and reports her resolve","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v10-p253-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y1v10-p253-1\">Ch.6/Epilogue: Added voice lines<\/a><\/span><span class=\"meta\">Y1V10 · p.253, 259, 261, 344, 350<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><p class=\"setup\">States she will not let a single Class B student be expelled. Asks Nagumo whether he likes her before agreeing to date him. Steels her resolve to protect everyone on her own. Confirms she will use Class B’s twenty million points to save one of her classmates. Tells Ayanokōji she will rise to Class A with her friends.<\/p><p class=\"with\">with <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “I won’t let a single one of us be expelled.”<span class=\"pg\">p.253<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “Senpai… D-do you, uh… do you like me?”<span class=\"pg\">p.259<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “I… will protect everyone.”<span class=\"pg\">p.261<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “With twenty million points, I’ll save one of my classmates… Right?”<span class=\"pg\">p.344<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m gonna rise up to Class A together with all my friends and graduate.”<span class=\"pg\">p.350<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Asks him whether he likes her.<span class=\"pg\">p.259<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Confirms the deal and reports her resolve.<span class=\"pg\">p.344, 350<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v10-p252-1\">← Before: Ch.6: Saving Class B<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v10-p342-1\">→ After: Epilogue: Saving Ryūen and Class B (flashback and call)<\/button><\/div><\/article>"},{"i":"sc-kanzaki-ryuuji-y1v10-p253-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ichinose-honami kanzaki-ryuuji","q":"kanzaki ryuji ch 6  questioning the plan expresses concern when ichinose says she will prevent any expulsions  asking if she is sure   are you sure  ichinose  saying that so confidently  asks how she will make up the four million points shortfall and presses for details about borrowing from nagumo   now how are you going to make up for the rest  i can t imagine that anyone from any of the other classes would be willing to give us so many  not even the upperclassmen  agrees to support ichinose s plan once the repayment terms are clear  questions and supports her plan to save the class","h":"<article class=\"card\" id=\"sc-kanzaki-ryuuji-y1v10-p253-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kanzaki-ryuuji.html#sc-kanzaki-ryuuji-y1v10-p253-1\">Ch.6: Questioning the plan<\/a><\/span><span class=\"meta\">Y1V10 · p.253–256<\/span><span class=\"by\">notes on <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/span><\/h3><p class=\"setup\">Expresses concern when Ichinose says she will prevent any expulsions, asking if she is sure. Asks how she will make up the four million points shortfall and presses for details about borrowing from Nagumo. Agrees to support Ichinose’s plan once the repayment terms are clear.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> “Are you sure, Ichinose? Saying that so confidently…”<span class=\"pg\">p.253<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> “Now how are you going to make up for the rest? I can’t imagine that anyone from any of the other classes would be willing to give us so many, not even the upperclassmen.”<span class=\"pg\">p.255<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Questions and supports her plan to save the class.<span class=\"pg\">p.253–256<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-shibata-sou-y1v10-p253-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ichinose-honami shibata-sou","q":"shibata so ch 6  supporting ichinose says he is prepared to do whatever ichinose asks even without a full explanation   it s okay  ichinose  we re prepared for what we have to do  questions whether class b has enough points to reach 20 million  transfers his private points along with the rest of the class  trusts her plan and contributes his points","h":"<article class=\"card\" id=\"sc-shibata-sou-y1v10-p253-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shibata-sou.html#sc-shibata-sou-y1v10-p253-1\">Ch.6: Supporting Ichinose<\/a><\/span><span class=\"meta\">Y1V10 · p.253–255<\/span><span class=\"by\">notes on <a href=\"../../../people/shibata-sou.html\">Shibata Sō<\/a><\/span><\/h3><p class=\"setup\">Says he is prepared to do whatever Ichinose asks even without a full explanation. Questions whether Class B has enough points to reach 20 million. Transfers his private points along with the rest of the class.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shibata Sō<\/b> “It’s okay, Ichinose. We’re prepared for what we have to do.”<span class=\"pg\">p.253<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Trusts her plan and contributes his points.<span class=\"pg\">p.253–255<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nagumo-miyabi-y1v10-p257-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ichinose-honami nagumo-miyabi","q":"nagumo miyabi ch 6  lending points to ichinose takes ichinose s call and confirms their arrangement   honami  this is about our little arrangement  right  asks how many more points she needs after she collects her classmates  points   how many more do you need  answers without hesitation when ichinose asks whether he likes her   i wouldn t have made this a condition if i didn t like you  warns her about his deadline before transferring the points   be careful  i m a man who s fussy about keeping deadlines  confirms the conditions and pressures her to decide","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y1v10-p257-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nagumo-miyabi.html#sc-nagumo-miyabi-y1v10-p257-1\">Ch.6: Lending points to Ichinose<\/a><\/span><span class=\"meta\">Y1V10 · p.257–259<\/span><span class=\"by\">notes on <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/span><\/h3><p class=\"setup\">Takes Ichinose’s call and confirms their arrangement. Asks how many more points she needs after she collects her classmates’ points. Answers without hesitation when Ichinose asks whether he likes her. Warns her about his deadline before transferring the points.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “Honami? This is about our little arrangement, right?”<span class=\"pg\">p.257<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “How many more do you need?”<span class=\"pg\">p.258<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “I wouldn’t have made this a condition if I didn’t like you.”<span class=\"pg\">p.259<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Be careful. I’m a man who’s fussy about keeping deadlines.”<span class=\"pg\">p.259<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Confirms the conditions and pressures her to decide.<span class=\"pg\">p.257–259<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y1v10-p165-1\">← Before: Ch.4: Third-year politics<\/button><\/div><\/article>"},{"i":"sc-katsuragi-kouhei-y1v10-p262-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"sakayanagi-arisu totsuka-yahiko katsuragi-kouhei","q":"katsuragi kohei ch 6  class a votes him out at mashima s class time  sakayanagi nominates him for expulsion  he remains silent with arms crossed  totsuka protests but katsuragi rejects the attempt to speak for him   stop it  yahiko  explains his expulsion is responsibility for the secret contract with class d that has been sending private points to ryuen   i fully intend to accept what s coming to me  tells totsuka to align with sakayanagi after he is gone and warns him not to oppose her   that said  after i m gone  you should align yourself with sakayanagi  if you foolishly go against her  her next target will be you  yahiko  voted for expulsion by class a  37 in favor  excluding katsuragi  totsuka  sakayanagi  is nominated by her and accepts the outcome  tries to defend him  he restrains and advises him","h":"<article class=\"card\" id=\"sc-katsuragi-kouhei-y1v10-p262-1\"><h3><span class=\"ttl\"><a href=\"../../../people/katsuragi-kouhei.html#sc-katsuragi-kouhei-y1v10-p262-1\">Ch.6: Class A votes him out<\/a><\/span><span class=\"meta\">Y1V10 · p.262–265<\/span><span class=\"by\">notes on <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/span><\/h3><p class=\"setup\">At Mashima’s class time, Sakayanagi nominates him for expulsion; he remains silent with arms crossed. Totsuka protests but Katsuragi rejects the attempt to speak for him. Explains his expulsion is responsibility for the secret contract with Class D that has been sending private points to Ryūen. Tells Totsuka to align with Sakayanagi after he is gone and warns him not to oppose her.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/totsuka-yahiko.html\">Totsuka Yahiko<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> “Stop it, Yahiko.”<span class=\"pg\">p.263<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> “I fully intend to accept what’s coming to me.”<span class=\"pg\">p.264<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> “That said, after I’m gone, you should align yourself with Sakayanagi. If you foolishly go against her, her next target will be you, Yahiko.”<span class=\"pg\">p.265<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Position<\/span> Voted for expulsion by Class A (37 in favor, excluding Katsuragi, Totsuka, Sakayanagi).<span class=\"pg\">p.262–265<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Is nominated by her and accepts the outcome.<span class=\"pg\">p.262–265<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Totsuka Yahiko<\/b> Tries to defend him; he restrains and advises him.<span class=\"pg\">p.263–265<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-katsuragi-kouhei-y1v10-p122-1\">← Before: Ch.3: Target of Class A<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-katsuragi-kouhei-y1v10-p292-1\">→ After: Epilogue: Totsuka’s expulsion<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-arisu-y1v10-p262-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"katsuragi-kouhei totsuka-yahiko yamauchi-haruki kamuro-masumi hashimoto-masayoshi kitou-hayato mashima-tomonari sakayanagi-arisu","q":"sakayanagi arisu ch 6  orchestrating yamauchi and class a s decision in class a  nominates katsuragi kohei for expulsion and leads the vote   for this exam  i think it d be wonderful if we had katsuragi kun take his exit  confirms the unanimous approval of class a  except totsuka  katsuragi  herself  to expel katsuragi  calls yamauchi after school and arranges to meet him later that night  meets yamauchi at keyaki mall karaoke with kamuro  uses a gentle persona to manipulate him   if you got expelled  we wouldn t be able to meet like this anymore  that  that s the one thing i absolutely don t want to have happen  offers to have class a give yamauchi praise votes and instructs him to target ayanokoji   there are about twenty people who follow me in class a  i ll have all of them use their praise votes on you  yamauchi kun  promises another meeting and tells yamauchi not to reveal the vote plan  after frantically reassuring her about trust  warns him that eavesdropping or recording will end their relationship  learns horikita exposed her collaboration with yamauchi  discusses the leak  karuizawa  with kamuro  hashimoto  and kito  says she allowed karuizawa into yamauchi s group to see how ayanokoji would react and to test him   should it know that it s become someone s prey  even a herbivore will try to fight for it s life if it comes down to it  turns off her phone to avoid yamauchi s messages  saying she forgot to mention an important story about him  nominates and secures his expulsion from class a  overrides his protests  manipulates him into targeting ayanokoji and promises support  meets yamauchi with her and discusses the plan  debates the karuizawa leak and strategy  present at the discussion  her homeroom teacher oversees the class a vote","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y1v10-p262-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y1v10-p262-1\">Ch.6: Orchestrating Yamauchi and Class A’s decision<\/a><\/span><span class=\"meta\">Y1V10 · p.262–285<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><p class=\"setup\">In Class A, nominates Katsuragi Kōhei for expulsion and leads the vote. Confirms the unanimous approval of Class A (except Totsuka, Katsuragi, herself) to expel Katsuragi. Calls Yamauchi after school and arranges to meet him later that night. Meets Yamauchi at Keyaki Mall karaoke with Kamuro; uses a gentle persona to manipulate him. Offers to have Class A give Yamauchi praise votes and instructs him to target Ayanokōji. Promises another meeting and tells Yamauchi not to reveal the vote plan. After frantically reassuring her about trust, warns him that eavesdropping or recording will end their relationship. Learns Horikita exposed her collaboration with Yamauchi; discusses the leak (Karuizawa) with Kamuro, Hashimoto, and Kitō. Says she allowed Karuizawa into Yamauchi’s group to see how Ayanokōji would react and to test him. Turns off her phone to avoid Yamauchi’s messages, saying she forgot to mention an important story about him.<\/p><p class=\"with\">with <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/totsuka-yahiko.html\">Totsuka Yahiko<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/kamuro-masumi.html\">Kamuro Masumi<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"../../../people/kitou-hayato.html\">Kitō Hayato<\/a> <span class=\"n\">+1 more<\/span><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “For this exam, I think it’d be wonderful if we had Katsuragi-kun take his exit.”<span class=\"pg\">p.262<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “If you got expelled, we wouldn’t be able to meet like this anymore. That… That’s the one thing I absolutely don’t want to have happen.”<span class=\"pg\">p.271<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “There are about twenty people who follow me in Class A. I’ll have all of them use their praise votes on you, Yamauchi-kun.”<span class=\"pg\">p.273<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Should it know that it’s become someone’s prey, even a herbivore will try to fight for it’s life if it comes down to it.”<span class=\"pg\">p.284<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Nominates and secures his expulsion from Class A.<span class=\"pg\">p.262–265<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Totsuka Yahiko<\/b> Overrides his protests.<span class=\"pg\">p.263–265<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Manipulates him into targeting Ayanokōji and promises support.<span class=\"pg\">p.266–276<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamuro Masumi<\/b> Meets Yamauchi with her and discusses the plan.<span class=\"pg\">p.266–285<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Debates the Karuizawa leak and strategy.<span class=\"pg\">p.282–284<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> Present at the discussion.<span class=\"pg\">p.282<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mashima Tomonari<\/b> Her homeroom teacher oversees the Class A vote.<span class=\"pg\">p.262–263<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y1v10-p180-1\">← Before: Ch.4: Supporting Yamauchi<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y1v10-p269-1\">→ After: Ch.6/Epilogue: Added voice lines<\/button><\/div><\/article>"},{"i":"sc-totsuka-yahiko-y1v10-p263-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"katsuragi-kouhei sakayanagi-arisu totsuka-yahiko","q":"totsuka yahiko ch 6  defending katsuragi protests when sakayanagi nominates katsuragi for expulsion   wha  what do you mean  that doesn t seem fair  tries to argue against the expulsion by citing the contract s benefits and possible ryuen expulsion  begs katsuragi not to be expelled and is told to follow sakayanagi afterward  leaves frustrated  defends him and is advised by him to align with sakayanagi  opposes her decision to expel katsuragi","h":"<article class=\"card\" id=\"sc-totsuka-yahiko-y1v10-p263-1\"><h3><span class=\"ttl\"><a href=\"../../../people/totsuka-yahiko.html#sc-totsuka-yahiko-y1v10-p263-1\">Ch.6: Defending Katsuragi<\/a><\/span><span class=\"meta\">Y1V10 · p.263–265<\/span><span class=\"by\">notes on <a href=\"../../../people/totsuka-yahiko.html\">Totsuka Yahiko<\/a><\/span><\/h3><p class=\"setup\">Protests when Sakayanagi nominates Katsuragi for expulsion. Tries to argue against the expulsion by citing the contract’s benefits and possible Ryūen expulsion. Begs Katsuragi not to be expelled and is told to follow Sakayanagi afterward; leaves frustrated.<\/p><p class=\"with\">with <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Totsuka Yahiko<\/b> “Wha… What do you mean!? That doesn’t seem fair!”<span class=\"pg\">p.263<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Defends him and is advised by him to align with Sakayanagi.<span class=\"pg\">p.263–265<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Opposes her decision to expel Katsuragi.<span class=\"pg\">p.263–264<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-totsuka-yahiko-y1v10-p125-1\">← Before: Ch.3: Following Katsuragi<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-totsuka-yahiko-y1v10-p293-1\">→ After: Epilogue: Expulsion from Class A<\/button><\/div><\/article>"},{"i":"sc-kamuro-masumi-y1v10-p266-1","v":"y1v10","y":1,"o":12,"k":"","w":"sakayanagi-arisu yamauchi-haruki hashimoto-masayoshi kamuro-masumi","q":"kamuro masumi ch 6  with sakayanagi and yamauchi leaves school with sakayanagi and hears her accept yamauchi s call  notes sakayanagi has been talking with yamauchi a lot and asks what she is planning  meets yamauchi with sakayanagi at keyaki mall karaoke  feels uneasy about the situation  frisk searches yamauchi at sakayanagi s request to check for recording devices  listens as sakayanagi says horikita exposed the collaboration with yamauchi  points out sakayanagi messed up by letting karuizawa into the group  criticises the lack of written contracts and says ayanokoji may not be easily expelled  stays with her through the yamauchi meetings and post mortem discussion  meets him at karaoke and searches him  debates the failed plan with him and sakayanagi","h":"<article class=\"card\" id=\"sc-kamuro-masumi-y1v10-p266-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kamuro-masumi.html#sc-kamuro-masumi-y1v10-p266-1\">Ch.6: With Sakayanagi and Yamauchi<\/a><\/span><span class=\"meta\">Y1V10 · p.266–284<\/span><span class=\"by\">notes on <a href=\"../../../people/kamuro-masumi.html\">Kamuro Masumi<\/a><\/span><\/h3><p class=\"setup\">Leaves school with Sakayanagi and hears her accept Yamauchi’s call. Notes Sakayanagi has been talking with Yamauchi a lot and asks what she is planning. Meets Yamauchi with Sakayanagi at Keyaki Mall karaoke; feels uneasy about the situation. Frisk-searches Yamauchi at Sakayanagi’s request to check for recording devices. Listens as Sakayanagi says Horikita exposed the collaboration with Yamauchi; points out Sakayanagi messed up by letting Karuizawa into the group. Criticises the lack of written contracts and says Ayanokōji may not be easily expelled.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Stays with her through the Yamauchi meetings and post-mortem discussion.<span class=\"pg\">p.266–284<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Meets him at karaoke and searches him.<span class=\"pg\">p.270–276<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Debates the failed plan with him and Sakayanagi.<span class=\"pg\">p.282–284<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kamuro-masumi-y1v10-p117-1\">← Before: Ch.3: Walk with Sakayanagi<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kamuro-masumi-y1v10-p269-1\">→ After: Ch.6: With Sakayanagi and Yamauchi<\/button><\/div><\/article>"},{"i":"sc-yamauchi-haruki-y1v10-p266-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"sakayanagi-arisu kamuro-masumi ayanokouji-kiyotaka yamauchi-haruki","q":"yamauchi haruki ch 6  manipulated by sakayanagi receives calls from sakayanagi and arranges to meet her that night at keyaki mall karaoke  meets sakayanagi with kamuro present  feels embarrassed but hopeful  fears expulsion and is reassured by sakayanagi s false concern  says he is worried about jealous classmates voting against him and claims he is the only one who can meet sakayanagi  is told sakayanagi will have class a give him praise votes and is instructed to target ayanokoji  agrees to the plan   a are you serious  is promised another meeting and told not to reveal the vote plan  is warned not to betray sakayanagi s trust and is frisked by kamuro  meets her and is drawn into her plan to target ayanokoji  meets her at karaoke and is searched by her  selected as the target to be expelled under sakayanagi s plan","h":"<article class=\"card\" id=\"sc-yamauchi-haruki-y1v10-p266-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamauchi-haruki.html#sc-yamauchi-haruki-y1v10-p266-1\">Ch.6: Manipulated by Sakayanagi<\/a><\/span><span class=\"meta\">Y1V10 · p.266–276<\/span><span class=\"by\">notes on <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a><\/span><\/h3><p class=\"setup\">Receives calls from Sakayanagi and arranges to meet her that night at Keyaki Mall karaoke. Meets Sakayanagi with Kamuro present; feels embarrassed but hopeful. Fears expulsion and is reassured by Sakayanagi’s false concern. Says he is worried about jealous classmates voting against him and claims he is the only one who can meet Sakayanagi. Is told Sakayanagi will have Class A give him praise votes and is instructed to target Ayanokōji; agrees to the plan. Is promised another meeting and told not to reveal the vote plan. Is warned not to betray Sakayanagi’s trust and is frisked by Kamuro.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/kamuro-masumi.html\">Kamuro Masumi<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yamauchi Haruki<\/b> “A-are you serious?”<span class=\"pg\">p.273<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Meets her and is drawn into her plan to target Ayanokōji.<span class=\"pg\">p.266–276<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamuro Masumi<\/b> Meets her at karaoke and is searched by her.<span class=\"pg\">p.270–276<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Selected as the target to be expelled under Sakayanagi’s plan.<span class=\"pg\">p.273–275<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamauchi-haruki-y1v10-p197-1\">← Before: Ch.5: Exposed and cornered<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamauchi-haruki-y1v10-p291-1\">→ After: Epilogue: Expulsion from Class C<\/button><\/div><\/article>"},{"i":"sc-kamuro-masumi-y1v10-p269-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"sakayanagi-arisu kamuro-masumi","q":"kamuro masumi ch 6  with sakayanagi and yamauchi reacts with disbelief when sakayanagi says she likes yamauchi   caught your eye  do you like him  accuses sakayanagi of messing up by letting karuizawa into the plan   you messed up  didn t you  sakayanagi  questions her manipulation of yamauchi and the leak","h":"<article class=\"card\" id=\"sc-kamuro-masumi-y1v10-p269-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kamuro-masumi.html#sc-kamuro-masumi-y1v10-p269-1\">Ch.6: With Sakayanagi and Yamauchi<\/a><\/span><span class=\"meta\">Y1V10 · p.269, 283<\/span><span class=\"by\">notes on <a href=\"../../../people/kamuro-masumi.html\">Kamuro Masumi<\/a><\/span><\/h3><p class=\"setup\">Reacts with disbelief when Sakayanagi says she likes Yamauchi. Accuses Sakayanagi of messing up by letting Karuizawa into the plan.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kamuro Masumi<\/b> “Caught your eye…? Do you like him?”<span class=\"pg\">p.269<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kamuro Masumi<\/b> “You messed up, didn’t you, Sakayanagi?”<span class=\"pg\">p.283<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Questions her manipulation of Yamauchi and the leak.<span class=\"pg\">p.269, 283<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kamuro-masumi-y1v10-p266-1\">← Before: Ch.6: With Sakayanagi and Yamauchi<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-arisu-y1v10-p269-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"katsuragi-kouhei kamuro-masumi sakayanagi-arisu","q":"sakayanagi arisu ch 6 epilogue  added voice lines tells kamuro she is training yamauchi to use him as a spy within class c   i m training him  to see whether or not i can use him as a spy within class c  promises yamauchi that about twenty class a students will use their praise votes on him   there are about twenty people who follow me in class a  i ll have all of them use their praise votes on you  yamauchi kun  decides to make ayanokoji the sacrifice in yamauchi s place   in which case  let s have him be the sacrifice  tells kamuro that ayanokoji is powerful  beyond katsuragi  ryuen  and ichinose   he s powerful   people like katsuragi kun  ryuen kun  and ichinose san wouldn t even stand a chance against him  says she hopes to see ayanokoji take things seriously before having him expelled   i hope i can see him take things seriously before i have him expelled  explains that even a herbivore will fight when it knows it has become prey   should it know that it s become someone s prey  even a herbivore will try to fight for it s life if it comes down to it  reveals to katsuragi that she never intended to expel him   expulsion  you  you weren t the target in the first place  tells katsuragi he has no reason to bear a grudge against her   there s no reason for you to bear a grudge against me  katsuragi kun  spares him and warns him  discusses ayanokoji s strength with her","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y1v10-p269-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y1v10-p269-1\">Ch.6/Epilogue: Added voice lines<\/a><\/span><span class=\"meta\">Y1V10 · p.269, 273–274, 277–278, 284, 294, 298<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><p class=\"setup\">Tells Kamuro she is training Yamauchi to use him as a spy within Class C. Promises Yamauchi that about twenty Class A students will use their praise votes on him. Decides to make Ayanokōji the sacrifice in Yamauchi’s place. Tells Kamuro that Ayanokōji is powerful, beyond Katsuragi, Ryūen, and Ichinose. Says she hopes to see Ayanokōji take things seriously before having him expelled. Explains that even a herbivore will fight when it knows it has become prey. Reveals to Katsuragi that she never intended to expel him. Tells Katsuragi he has no reason to bear a grudge against her.<\/p><p class=\"with\">with <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/kamuro-masumi.html\">Kamuro Masumi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “I’m training him. To see whether or not I can use him as a spy within Class C.”<span class=\"pg\">p.269<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “There are about twenty people who follow me in Class A. I’ll have all of them use their praise votes on you, Yamauchi-kun.”<span class=\"pg\">p.273<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “In which case, let’s have him be the sacrifice.”<span class=\"pg\">p.274<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “He’s powerful.”<span class=\"pg\">p.277<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “People like Katsuragi-kun, Ryūen-kun, and Ichinose-san wouldn’t even stand a chance against him.”<span class=\"pg\">p.277<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I hope I can see him take things seriously before I have him expelled.”<span class=\"pg\">p.278<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Should it know that it’s become someone’s prey, even a herbivore will try to fight for it’s life if it comes down to it.”<span class=\"pg\">p.284<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Expulsion? You? You weren’t the target in the first place.”<span class=\"pg\">p.294<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’s no reason for you to bear a grudge against me, Katsuragi-kun.”<span class=\"pg\">p.298<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Spares him and warns him.<span class=\"pg\">p.294, 298<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamuro Masumi<\/b> Discusses Ayanokōji’s strength with her.<span class=\"pg\">p.277–278<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y1v10-p262-1\">← Before: Ch.6: Orchestrating Yamauchi and Class A’s decision<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y1v10-p292-1\">→ After: Epilogue: Results and the acting director<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v10-p282-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"sakayanagi-arisu kamuro-masumi kitou-hayato hashimoto-masayoshi","q":"hashimoto masayoshi ch 6  post mortem with sakayanagi present in the karaoke room with sakayanagi  kamuro  and kito as sakayanagi discusses the leak of her plan   sakayanagi  the leak came from karuizawa  like i told you before  if you wanted to make sure ayanokoji got expelled  it would ve been better to avoid pulling karuizawa into yamauchi s group  explains why karuizawa should have been kept out of the plan and argues sakayanagi let greed get to her  says it is unclear who will be expelled now that ayanokoji is not the target anymore in effect  critiques her handling of the karuizawa leak  discusses the plan with her  present at the discussion","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v10-p282-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y1v10-p282-1\">Ch.6: Post-mortem with Sakayanagi<\/a><\/span><span class=\"meta\">Y1V10 · p.282–284<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">Present in the karaoke room with Sakayanagi, Kamuro, and Kitō as Sakayanagi discusses the leak of her plan. Explains why Karuizawa should have been kept out of the plan and argues Sakayanagi let greed get to her. Says it is unclear who will be expelled now that Ayanokōji is not the target anymore in effect.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/kamuro-masumi.html\">Kamuro Masumi<\/a> · <a href=\"../../../people/kitou-hayato.html\">Kitō Hayato<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> “Sakayanagi, the leak came from Karuizawa. Like I told you before, if you wanted to make sure Ayanokōji got expelled, it would’ve been better to avoid pulling Karuizawa into Yamauchi’s group.”<span class=\"pg\">p.282<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Critiques her handling of the Karuizawa leak.<span class=\"pg\">p.282–284<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamuro Masumi<\/b> Discusses the plan with her.<span class=\"pg\">p.282–284<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> Present at the discussion.<span class=\"pg\">p.282<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v10-p283-1\">→ After: Ch.6: Post-mortem with Sakayanagi<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v10-p283-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"sakayanagi-arisu hashimoto-masayoshi","q":"hashimoto masayoshi ch 6  post mortem with sakayanagi points out that yamauchi might have had a way out if the plan had not come to light   but  if things hadn t come to light  yamauchi might ve had a way out too  discusses the consequences of the leak","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v10-p283-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y1v10-p283-1\">Ch.6: Post-mortem with Sakayanagi<\/a><\/span><span class=\"meta\">Y1V10 · p.283<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">Points out that Yamauchi might have had a way out if the plan had not come to light.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> “But, if things hadn’t come to light, Yamauchi might’ve had a way out too.”<span class=\"pg\">p.283<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Discusses the consequences of the leak.<span class=\"pg\">p.283<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v10-p282-1\">← Before: Ch.6: Post-mortem with Sakayanagi<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v10-p298-1\">→ After: Epilogue: After Totsuka’s expulsion<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v10-p286-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"hirata-yousuke yamauchi-haruki sakayanagi-arisu ryuuen-kakeru ichinose-honami ibuki-mio ishizaki-daichi horikita-suzune ayanokouji-kiyotaka","q":"ayanokoji kiyotaka epilogue  the dropouts and the deals behind them on the morning of the class poll  ayanokoji and horikita discuss whether either of them acted before the vote  hirata apologises to horikita and says he has decided she is necessary for the class  hirata volunteers to be expelled  ayanokoji recognises this as the answer hirata had reached   i want everyone to cast a censure vote for me  koenji provokes yamauchi before the results  chabashira enters to announce class c s votes  chabashira announces ayanokoji received 42 praise votes  placing first in class c  yamauchi is announced expelled with 33 censure votes  koenji stops yamauchi s attack and chabashira orders yamauchi to leave  horikita confronts ayanokoji after class  asking how much he anticipated and whether he told her brother about sakayanagi and yamauchi  at the bulletin board  ayanokoji sees the expulsions  totsuka yahiko  class a  none  class b  yamauchi haruki  class c  manabe shiho  class d  ryuen and katsuragi discuss the results at the board  ryuen then takes ayanokoji behind the school building  flashback  ishizaki and ibuki come to ayanokoji s room asking how to prevent ryuen s expulsion  flashback  ayanokoji arranges for ichinose to come to his room and brokers a deal using ryuen s private points to secure class b s praise votes for ryuen  ichinose agrees to ask class b to cast 40 praise votes for ryuen in exchange for the points transferred by ibuki  ayanokoji explains to ryuen that he used the situation to build trust with ichinose  ichinose calls to report class b avoided expulsion by paying 20 million points to negate kanzaki s expulsion  ayanokoji meets sakayanagi at the special building  acting director tsukishiro appears  kicks sakayanagi s cane  and restrains ayanokoji while delivering a message from his father  ayanokoji proposes to sakayanagi that they have their match in the next exam  volunteers to be expelled and is devastated after yamauchi s expulsion  expelled from class c after the class poll  meets her and agrees to face her in the next exam  speaks with him and reflects on saving him via ichinose and class d  brokers the deal to save ryuen and later speaks with her by phone  works with her and ishizaki to transfer ryuen s points and target manabe  seeks help to save ryuen and cooperates in the plan  discusses the morning of the vote and confronts him afterward","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v10-p286-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v10-p286-1\">Epilogue: The dropouts and the deals behind them<\/a><\/span><span class=\"meta\">Y1V10 · p.286–362<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">On the morning of the Class Poll, Ayanokōji and Horikita discuss whether either of them acted before the vote. Hirata apologises to Horikita and says he has decided she is necessary for the class. Hirata volunteers to be expelled; Ayanokōji recognises this as the answer Hirata had reached. Kōenji provokes Yamauchi before the results; Chabashira enters to announce Class C’s votes. Chabashira announces Ayanokōji received 42 praise votes, placing first in Class C. Yamauchi is announced expelled with 33 censure votes; Kōenji stops Yamauchi’s attack and Chabashira orders Yamauchi to leave. Horikita confronts Ayanokōji after class, asking how much he anticipated and whether he told her brother about Sakayanagi and Yamauchi. At the bulletin board, Ayanokōji sees the expulsions: Totsuka Yahiko (Class A), none (Class B), Yamauchi Haruki (Class C), Manabe Shiho (Class D). Ryūen and Katsuragi discuss the results at the board; Ryūen then takes Ayanokōji behind the school building. Flashback: Ishizaki and Ibuki come to Ayanokōji’s room asking how to prevent Ryūen’s expulsion. Flashback: Ayanokōji arranges for Ichinose to come to his room and brokers a deal using Ryūen’s private points to secure Class B’s praise votes for Ryūen. Ichinose agrees to ask Class B to cast 40 praise votes for Ryūen in exchange for the points transferred by Ibuki. Ayanokōji explains to Ryūen that he used the situation to build trust with Ichinose. Ichinose calls to report Class B avoided expulsion by paying 20 million points to negate Kanzaki’s expulsion. Ayanokōji meets Sakayanagi at the special building; acting director Tsukishiro appears, kicks Sakayanagi’s cane, and restrains Ayanokōji while delivering a message from his father. Ayanokōji proposes to Sakayanagi that they have their match in the next exam.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a> <span class=\"n\">+2 more<\/span><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “I want everyone to cast a censure vote for me.”<span class=\"pg\">p.289<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Volunteers to be expelled and is devastated after Yamauchi’s expulsion.<span class=\"pg\">p.288–291, 304–311<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Expelled from Class C after the Class Poll.<span class=\"pg\">p.301–309<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Meets her and agrees to face her in the next exam.<span class=\"pg\">p.354–361<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Speaks with him and reflects on saving him via Ichinose and Class D.<span class=\"pg\">p.316–318, 347–348<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Brokers the deal to save Ryūen and later speaks with her by phone.<span class=\"pg\">p.335–346, 349–353<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Works with her and Ishizaki to transfer Ryūen’s points and target Manabe.<span class=\"pg\">p.319–346<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Seeks help to save Ryūen and cooperates in the plan.<span class=\"pg\">p.319–346<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Discusses the morning of the vote and confronts him afterward.<span class=\"pg\">p.286–287, 311–315<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v10-p182-1\">← Before: Ch.5: Good and Evil<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v10-p287-1\">→ After: Epilogue: Added voice lines<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y1v10-p286-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ayanokouji-kiyotaka hirata-yousuke horikita-suzune","q":"horikita suzune epilogue  morning vote and aftermath on the morning of the class poll  asks ayanokoji if he truly stayed uninvolved and says he is the one who saved her  responds when hirata apologises and asks what he is doing  questions hirata for trying to sacrifice himself instead of choosing who is unnecessary   think about what you re saying  have you gone insane  after the results  follows ayanokoji and asks how much he anticipated and whether he told her brother about sakayanagi and yamauchi   ayanokoji kun  questions him before and after the vote  tries to stop him from volunteering for expulsion","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v10-p286-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v10-p286-1\">Epilogue: Morning vote and aftermath<\/a><\/span><span class=\"meta\">Y1V10 · p.286–315<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">On the morning of the Class Poll, asks Ayanokōji if he truly stayed uninvolved and says he is the one who saved her. Responds when Hirata apologises and asks what he is doing. Questions Hirata for trying to sacrifice himself instead of choosing who is unnecessary. After the results, follows Ayanokōji and asks how much he anticipated and whether he told her brother about Sakayanagi and Yamauchi.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Think about what you’re saying… Have you gone insane?”<span class=\"pg\">p.290<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Ayanokōji-kun!!”<span class=\"pg\">p.315<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Questions him before and after the vote.<span class=\"pg\">p.286–287, 311–315<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Tries to stop him from volunteering for expulsion.<span class=\"pg\">p.288–291<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v10-p182-1\">← Before: Ch.5: Good and Evil<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v10-p370-1\">→ After: Short Stories: Neighbour<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v10-p287-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"horikita-suzune ishizaki-daichi ichinose-honami ayanokouji-kiyotaka","q":"ayanokoji kiyotaka epilogue  added voice lines denies having done anything when horikita asks   does it look like i ve done something  tells ishizaki and ibuki the exam is not simple enough to save someone just by wanting to   this exam isn t so simple that you can save someone just because you want to  teases ichinose about having started dating nagumo otherwise   would ve started dating nagumo  talks with her on the morning of the vote  advises him on saving ryuen  speaks with her by phone after the exam","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v10-p287-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v10-p287-1\">Epilogue: Added voice lines<\/a><\/span><span class=\"meta\">Y1V10 · p.287, 332, 350<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Denies having done anything when Horikita asks. Tells Ishizaki and Ibuki the exam is not simple enough to save someone just by wanting to. Teases Ichinose about having started dating Nagumo otherwise.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Does it look like I’ve done something?”<span class=\"pg\">p.287<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “This exam isn’t so simple that you can save someone just because you want to.”<span class=\"pg\">p.332<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Would’ve started dating Nagumo?”<span class=\"pg\">p.350<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Talks with her on the morning of the vote.<span class=\"pg\">p.287<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Advises him on saving Ryūen.<span class=\"pg\">p.332<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Speaks with her by phone after the exam.<span class=\"pg\">p.350<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v10-p286-1\">← Before: Epilogue: The dropouts and the deals behind them<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v10-p366-1\">→ After: Short Stories<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v10-p288-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"horikita-suzune yamauchi-haruki wang-mei-yu hirata-yousuke","q":"hirata yosuke epilogue  volunteering and aftermath before the vote  apologises to horikita for saying he would vote against her the previous day  stands at the podium and says he has decided horikita is necessary and asks everyone to cast censure votes for him   i decided that you are necessary for the success of our class   i want everyone to cast a censure vote for me  says he is prepared to be expelled and refuses to change his mind  claims he has come to hate the class and asks them to let him make it easier  learns from koenji that a message had circulated asking classmates not to vote against him  is announced as second in class c for praise votes  remains sitting motionless at his desk after yamauchi s expulsion  barely responding to mii chan  apologises to her and insists she is necessary  his attempted self sacrifice fails and yamauchi is expelled  is defended by her and later does not respond when she calls out to him   there s no reason for you guys to stick up for me  i ve already come to hate all of you   so please let me make this easier on all of us","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v10-p288-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v10-p288-1\">Epilogue: Volunteering and aftermath<\/a><\/span><span class=\"meta\">Y1V10 · p.288–311<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Before the vote, apologises to Horikita for saying he would vote against her the previous day. Stands at the podium and says he has decided Horikita is necessary and asks everyone to cast censure votes for him. Says he is prepared to be expelled and refuses to change his mind. Claims he has come to hate the class and asks them to let him make it easier. Learns from Kōenji that a message had circulated asking classmates not to vote against him. Is announced as second in Class C for praise votes. Remains sitting motionless at his desk after Yamauchi’s expulsion, barely responding to Mii-chan.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/wang-mei-yu.html\">Wang Mei-Yu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “I decided that you are necessary for the success of our class.”<span class=\"pg\">p.289<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “I want everyone to cast a censure vote for me.”<span class=\"pg\">p.289<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “There’s no reason for you guys to stick up for me. I’ve already come to hate all of you.”<span class=\"pg\">p.291<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Apologises to her and insists she is necessary.<span class=\"pg\">p.288–291<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> His attempted self-sacrifice fails and Yamauchi is expelled.<span class=\"pg\">p.291, 306–310<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Wang Mei-Yu<\/b> Is defended by her and later does not respond when she calls out to him.<span class=\"pg\">p.290, 311<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So please let me make this easier on all of us.”<span class=\"pg\">p.291<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v10-p200-1\">← Before: Ch.5: Refusal and collapse<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v10-p290-1\">→ After: Epilogue: Volunteering<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v10-p290-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"horikita-suzune hirata-yousuke","q":"hirata yosuke epilogue  volunteering volunteers to be expelled and says he is prepared for it   it ll be fine if i m expelled  i m prepared to do at least that much  says he is volunteering as the one to be expelled   so i m volunteering  volunteers in her place","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v10-p290-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v10-p290-1\">Epilogue: Volunteering<\/a><\/span><span class=\"meta\">Y1V10 · p.290<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Volunteers to be expelled and says he is prepared for it. Says he is volunteering as the one to be expelled.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “It’ll be fine if I’m expelled. I’m prepared to do at least that much.”<span class=\"pg\">p.290<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “So I’m volunteering.”<span class=\"pg\">p.290<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Volunteers in her place.<span class=\"pg\">p.290<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v10-p288-1\">← Before: Epilogue: Volunteering and aftermath<\/button><\/div><\/article>"},{"i":"sc-shinohara-satsuki-y1v10-p290-1","v":"y1v10","y":1,"o":12,"k":"","w":"hirata-yousuke shinohara-satsuki","q":"shinohara satsuki epilogue  defending hirata speaks up with other girls to defend hirata when he volunteers to be expelled  refuses to accept his offer to be expelled","h":"<article class=\"card\" id=\"sc-shinohara-satsuki-y1v10-p290-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shinohara-satsuki.html#sc-shinohara-satsuki-y1v10-p290-1\">Epilogue: Defending Hirata<\/a><\/span><span class=\"meta\">Y1V10 · p.290<\/span><span class=\"by\">notes on <a href=\"../../../people/shinohara-satsuki.html\">Shinohara Satsuki<\/a><\/span><\/h3><p class=\"setup\">Speaks up with other girls to defend Hirata when he volunteers to be expelled.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Refuses to accept his offer to be expelled.<span class=\"pg\">p.290<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-wang-mei-yu-y1v10-p290-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"hirata-yousuke wang-mei-yu","q":"wang mei yu epilogue  reacting to hirata exclaims in shock when hirata asks the class to cast censure votes for him   h how could any of us do something like that  timidly calls out to hirata after yamauchi s expulsion  but he does not respond  objects to his self sacrifice and worries about him afterward","h":"<article class=\"card\" id=\"sc-wang-mei-yu-y1v10-p290-1\"><h3><span class=\"ttl\"><a href=\"../../../people/wang-mei-yu.html#sc-wang-mei-yu-y1v10-p290-1\">Epilogue: Reacting to Hirata<\/a><\/span><span class=\"meta\">Y1V10 · p.290–311<\/span><span class=\"by\">notes on <a href=\"../../../people/wang-mei-yu.html\">Wang Mei-Yu<\/a><\/span><\/h3><p class=\"setup\">Exclaims in shock when Hirata asks the class to cast censure votes for him. Timidly calls out to Hirata after Yamauchi’s expulsion, but he does not respond.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Wang Mei-Yu<\/b> “H-how could any of us do something like that!?”<span class=\"pg\">p.290<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Objects to his self-sacrifice and worries about him afterward.<span class=\"pg\">p.290, 311<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-chabashira-sae-y1v10-p291-1","v":"y1v10","y":1,"o":12,"k":"","w":"yamauchi-haruki ayanokouji-kiyotaka hirata-yousuke chabashira-sae","q":"chabashira sae epilogue  conducting the vote and aftermath enters the classroom and begins the class poll  directing students to the voting room  tells yamauchi to be quiet and announces she will reveal the results  announces the praise vote rankings and states ayanokoji placed first with 42 votes  announces yamauchi haruki received 33 censure votes and is expelled  tries to calm yamauchi  asks for proof of his promise with sakayanagi  and orders him to leave  on monday  announces the final special exam to class c  oversees his expulsion from the class  announces his first place praise vote result  announces his second place praise vote result","h":"<article class=\"card\" id=\"sc-chabashira-sae-y1v10-p291-1\"><h3><span class=\"ttl\"><a href=\"../../../people/chabashira-sae.html#sc-chabashira-sae-y1v10-p291-1\">Epilogue: Conducting the vote and aftermath<\/a><\/span><span class=\"meta\">Y1V10 · p.291–362<\/span><span class=\"by\">notes on <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/span><\/h3><p class=\"setup\">Enters the classroom and begins the Class Poll, directing students to the voting room. Tells Yamauchi to be quiet and announces she will reveal the results. Announces the praise-vote rankings and states Ayanokōji placed first with 42 votes. Announces Yamauchi Haruki received 33 censure votes and is expelled. Tries to calm Yamauchi, asks for proof of his promise with Sakayanagi, and orders him to leave. On Monday, announces the final special exam to Class C.<\/p><p class=\"with\">with <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Oversees his expulsion from the class.<span class=\"pg\">p.291, 303–309<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Announces his first-place praise-vote result.<span class=\"pg\">p.306<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Announces his second-place praise-vote result.<span class=\"pg\">p.304<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y1v10-p197-1\">← Before: Ch.5: Observing the class discussion<\/button><\/div><\/article>"},{"i":"sc-yamauchi-haruki-y1v10-p291-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"sakayanagi-arisu kouenji-rokusuke hirata-yousuke yamauchi-haruki","q":"yamauchi haruki epilogue  expulsion from class c urges classmates to vote for hirata so he can avoid expulsion  grows restless before the results and argues with koenji  claims sakayanagi promised him twenty praise votes from class a and says he will be safe   sakayanagi chan promised that she would give me twenty praise votes  in other words  even if most of the class voted against me  i still won t be the one who gets expelled  is announced as the student with the most censure votes in class c  33  and is told he will be expelled  denies the result and demands sakayanagi be confronted  but cannot prove the promise  snaps after koenji s provocation  swings a chair at him  and is stopped  breaks down crying and leaves the classroom after chabashira orders him out  expelled from class c in the class poll  believed her promise of class a praise votes  which was not fulfilled  is provoked by him and attacks him after the results  tries to use hirata s offer to save himself","h":"<article class=\"card\" id=\"sc-yamauchi-haruki-y1v10-p291-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamauchi-haruki.html#sc-yamauchi-haruki-y1v10-p291-1\">Epilogue: Expulsion from Class C<\/a><\/span><span class=\"meta\">Y1V10 · p.291–309<\/span><span class=\"by\">notes on <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a><\/span><\/h3><p class=\"setup\">Urges classmates to vote for Hirata so he can avoid expulsion. Grows restless before the results and argues with Kōenji. Claims Sakayanagi promised him twenty praise votes from Class A and says he will be safe. Is announced as the student with the most censure votes in Class C (33) and is told he will be expelled. Denies the result and demands Sakayanagi be confronted, but cannot prove the promise. Snaps after Kōenji’s provocation, swings a chair at him, and is stopped. Breaks down crying and leaves the classroom after Chabashira orders him out.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yamauchi Haruki<\/b> “Sakayanagi-chan promised that she would give me twenty praise votes! In other words, even if most of the class voted against me, I still won’t be the one who gets expelled!”<span class=\"pg\">p.302<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Position<\/span> Expelled from Class C in the Class Poll.<span class=\"pg\">p.306–309, 315<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Believed her promise of Class A praise votes, which was not fulfilled.<span class=\"pg\">p.301–307<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Is provoked by him and attacks him after the results.<span class=\"pg\">p.299–308<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Tries to use Hirata’s offer to save himself.<span class=\"pg\">p.291<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamauchi-haruki-y1v10-p266-1\">← Before: Ch.6: Manipulated by Sakayanagi<\/button><\/div><\/article>"},{"i":"sc-katsuragi-kouhei-y1v10-p292-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"totsuka-yahiko sakayanagi-arisu ryuuen-kakeru katsuragi-kouhei","q":"katsuragi kohei epilogue  totsuka s expulsion stands up when totsuka is announced expelled with 36 censure votes instead of him   how absurd  what s going on  demands an explanation from sakayanagi and learns she lied about expelling him  tells totsuka the decision cannot be overturned and watches him leave with mashima  accepts sakayanagi s warning and agrees not to oppose class a  at the bulletin board  speaks with ryuen about remaining in school and the contract  remains in class a while totsuka is expelled  fails to protect him from expulsion  learns he was spared and submits to her control  speaks with him at the bulletin board","h":"<article class=\"card\" id=\"sc-katsuragi-kouhei-y1v10-p292-1\"><h3><span class=\"ttl\"><a href=\"../../../people/katsuragi-kouhei.html#sc-katsuragi-kouhei-y1v10-p292-1\">Epilogue: Totsuka’s expulsion<\/a><\/span><span class=\"meta\">Y1V10 · p.292–317<\/span><span class=\"by\">notes on <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/span><\/h3><p class=\"setup\">Stands up when Totsuka is announced expelled with 36 censure votes instead of him. Demands an explanation from Sakayanagi and learns she lied about expelling him. Tells Totsuka the decision cannot be overturned and watches him leave with Mashima. Accepts Sakayanagi’s warning and agrees not to oppose Class A. At the bulletin board, speaks with Ryūen about remaining in school and the contract.<\/p><p class=\"with\">with <a href=\"../../../people/totsuka-yahiko.html\">Totsuka Yahiko<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> “How absurd! What’s going on!?”<span class=\"pg\">p.293<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Position<\/span> Remains in Class A while Totsuka is expelled.<span class=\"pg\">p.292–298<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Totsuka Yahiko<\/b> Fails to protect him from expulsion.<span class=\"pg\">p.293–296<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Learns he was spared and submits to her control.<span class=\"pg\">p.294–298<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Speaks with him at the bulletin board.<span class=\"pg\">p.316–317<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-katsuragi-kouhei-y1v10-p262-1\">← Before: Ch.6: Class A votes him out<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-katsuragi-kouhei-y1v10-p294-1\">→ After: Epilogue: Spared from expulsion<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-arisu-y1v10-p292-1","v":"y1v10","y":1,"o":12,"k":"","w":"katsuragi-kouhei totsuka-yahiko mashima-tomonari ayanokouji-kiyotaka sakayanagi-arisu","q":"sakayanagi arisu epilogue  results and the acting director in class a  receives 36 praise votes in the class poll  reveals totsuka yahiko  not katsuragi  received 36 censure votes and is expelled  tells katsuragi she lied when she said he would be expelled and explains totsuka was unnecessary  asks mashima whether consequences would follow if katsuragi had been expelled  then warns katsuragi not to oppose class a  meets ayanokoji at the special building and explains she used class a praise votes to protect him while manipulating yamauchi  says she targeted yamauchi in part as revenge for him bumping into her at the mixed training camp  acting director tsukishiro appears  sakayanagi falls when her cane is kicked away and is helped by ayanokoji  questions tsukishiro s actions and agrees to face ayanokoji in the next exam  spares him and expels totsuka instead  warning him to remain obedient  has him expelled from class a  receives the results and questions him  explains her actions and accepts his proposal for a match in the next exam","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y1v10-p292-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y1v10-p292-1\">Epilogue: Results and the acting director<\/a><\/span><span class=\"meta\">Y1V10 · p.292–361<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><p class=\"setup\">In Class A, receives 36 praise votes in the Class Poll. Reveals Totsuka Yahiko, not Katsuragi, received 36 censure votes and is expelled. Tells Katsuragi she lied when she said he would be expelled and explains Totsuka was unnecessary. Asks Mashima whether consequences would follow if Katsuragi had been expelled, then warns Katsuragi not to oppose Class A. Meets Ayanokōji at the special building and explains she used Class A praise votes to protect him while manipulating Yamauchi. Says she targeted Yamauchi in part as revenge for him bumping into her at the Mixed Training Camp. Acting director Tsukishiro appears; Sakayanagi falls when her cane is kicked away and is helped by Ayanokōji. Questions Tsukishiro’s actions and agrees to face Ayanokōji in the next exam.<\/p><p class=\"with\">with <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/totsuka-yahiko.html\">Totsuka Yahiko<\/a> · <a href=\"../../../people/mashima-tomonari.html\">Mashima Tomonari<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Spares him and expels Totsuka instead, warning him to remain obedient.<span class=\"pg\">p.292–298<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Totsuka Yahiko<\/b> Has him expelled from Class A.<span class=\"pg\">p.292–296<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mashima Tomonari<\/b> Receives the results and questions him.<span class=\"pg\">p.292–297<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Explains her actions and accepts his proposal for a match in the next exam.<span class=\"pg\">p.354–361<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y1v10-p269-1\">← Before: Ch.6/Epilogue: Added voice lines<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y1v10-p373-1\">→ After: Short Stories<\/button><\/div><\/article>"},{"i":"sc-totsuka-yahiko-y1v10-p293-1","v":"y1v10","y":1,"o":12,"k":"","w":"katsuragi-kouhei sakayanagi-arisu mashima-tomonari totsuka-yahiko","q":"totsuka yahiko epilogue  expulsion from class a is announced as the student with 36 censure votes and expelled from class a  reacts in disbelief when katsuragi  not him  was expected to be expelled  is unable to overturn the result and leaves the classroom with mashima  expelled from class a in the class poll  expected him to be expelled instead  expelled by her decision  announces his expulsion and escorts him out","h":"<article class=\"card\" id=\"sc-totsuka-yahiko-y1v10-p293-1\"><h3><span class=\"ttl\"><a href=\"../../../people/totsuka-yahiko.html#sc-totsuka-yahiko-y1v10-p293-1\">Epilogue: Expulsion from Class A<\/a><\/span><span class=\"meta\">Y1V10 · p.293–296<\/span><span class=\"by\">notes on <a href=\"../../../people/totsuka-yahiko.html\">Totsuka Yahiko<\/a><\/span><\/h3><p class=\"setup\">Is announced as the student with 36 censure votes and expelled from Class A. Reacts in disbelief when Katsuragi, not him, was expected to be expelled. Is unable to overturn the result and leaves the classroom with Mashima.<\/p><p class=\"with\">with <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/mashima-tomonari.html\">Mashima Tomonari<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Position<\/span> Expelled from Class A in the Class Poll.<span class=\"pg\">p.293–296, 315<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Expected him to be expelled instead.<span class=\"pg\">p.293–296<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Expelled by her decision.<span class=\"pg\">p.294–296<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mashima Tomonari<\/b> Announces his expulsion and escorts him out.<span class=\"pg\">p.293, 296<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-totsuka-yahiko-y1v10-p263-1\">← Before: Ch.6: Defending Katsuragi<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-totsuka-yahiko-y1v10-p293-2\">→ After: Epilogue: Expulsion from Class A<\/button><\/div><\/article>"},{"i":"sc-totsuka-yahiko-y1v10-p293-2","v":"y1v10","y":1,"o":12,"k":"spoken","w":"katsuragi-kouhei totsuka-yahiko","q":"totsuka yahiko epilogue  expulsion from class a reacts in disbelief when announced as the one expelled instead of katsuragi   k katsuragi san  why  wha  expected him to be expelled instead","h":"<article class=\"card\" id=\"sc-totsuka-yahiko-y1v10-p293-2\"><h3><span class=\"ttl\"><a href=\"../../../people/totsuka-yahiko.html#sc-totsuka-yahiko-y1v10-p293-2\">Epilogue: Expulsion from Class A<\/a><\/span><span class=\"meta\">Y1V10 · p.293<\/span><span class=\"by\">notes on <a href=\"../../../people/totsuka-yahiko.html\">Totsuka Yahiko<\/a><\/span><\/h3><p class=\"setup\">Reacts in disbelief when announced as the one expelled instead of Katsuragi.<\/p><p class=\"with\">with <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Totsuka Yahiko<\/b> “K-Katsuragi-san… Why? Wha…?”<span class=\"pg\">p.293<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Expected him to be expelled instead.<span class=\"pg\">p.293<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-totsuka-yahiko-y1v10-p293-1\">← Before: Epilogue: Expulsion from Class A<\/button><\/div><\/article>"},{"i":"sc-katsuragi-kouhei-y1v10-p294-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"sakayanagi-arisu katsuragi-kouhei","q":"katsuragi kohei epilogue  spared from expulsion demands an explanation when sakayanagi says he was never the target   wait  sakayanagi  the one who should ve been expelled was me  accepts sakayanagi s warning not to oppose class a   i told you i understood  you don t have to drag anyone else into this  learns he was spared and submits to her control","h":"<article class=\"card\" id=\"sc-katsuragi-kouhei-y1v10-p294-1\"><h3><span class=\"ttl\"><a href=\"../../../people/katsuragi-kouhei.html#sc-katsuragi-kouhei-y1v10-p294-1\">Epilogue: Spared from expulsion<\/a><\/span><span class=\"meta\">Y1V10 · p.294, 298<\/span><span class=\"by\">notes on <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/span><\/h3><p class=\"setup\">Demands an explanation when Sakayanagi says he was never the target. Accepts Sakayanagi’s warning not to oppose Class A.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> “Wait, Sakayanagi! The one who should’ve been expelled was me!”<span class=\"pg\">p.294<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> “I told you I understood. You don’t have to drag anyone else into this.”<span class=\"pg\">p.298<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Learns he was spared and submits to her control.<span class=\"pg\">p.294, 298<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-katsuragi-kouhei-y1v10-p292-1\">← Before: Epilogue: Totsuka’s expulsion<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v10-p298-1","v":"y1v10","y":1,"o":12,"k":"","w":"sakayanagi-arisu kitou-hayato katsuragi-kouhei hashimoto-masayoshi","q":"hashimoto masayoshi epilogue  after totsuka s expulsion moves with kito to block katsuragi s path when he approaches sakayanagi after totsuka s expulsion  protects her during the confrontation with katsuragi  acts with him to block katsuragi  moves to obstruct him","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v10-p298-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y1v10-p298-1\">Epilogue: After Totsuka’s expulsion<\/a><\/span><span class=\"meta\">Y1V10 · p.298<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">Moves with Kitō to block Katsuragi’s path when he approaches Sakayanagi after Totsuka’s expulsion.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/kitou-hayato.html\">Kitō Hayato<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Protects her during the confrontation with Katsuragi.<span class=\"pg\">p.298<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> Acts with him to block Katsuragi.<span class=\"pg\">p.298<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Moves to obstruct him.<span class=\"pg\">p.298<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v10-p283-1\">← Before: Ch.6: Post-mortem with Sakayanagi<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y1v10-p299-1","v":"y1v10","y":1,"o":12,"k":"","w":"yamauchi-haruki hirata-yousuke ayanokouji-kiyotaka kouenji-rokusuke","q":"koenji rokusuke epilogue  provoking yamauchi tells yamauchi his defeat is close at hand before the results are announced  shows hirata a message indicating classmates were asked not to vote against him  questions yamauchi s claim that sakayanagi promised him 20 praise votes and points out a verbal promise is unreliable  casually stops yamauchi s chair attack and releases it when chabashira intervenes  tells ayanokoji he cooperated to avoid expulsion and denies provoking yamauchi out of concern for the class  provokes him before and after the results  shows him the message asking classmates not to vote against him  speaks with him after leaving the classroom","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y1v10-p299-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y1v10-p299-1\">Epilogue: Provoking Yamauchi<\/a><\/span><span class=\"meta\">Y1V10 · p.299–312<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><p class=\"setup\">Tells Yamauchi his defeat is close at hand before the results are announced. Shows Hirata a message indicating classmates were asked not to vote against him. Questions Yamauchi’s claim that Sakayanagi promised him 20 praise votes and points out a verbal promise is unreliable. Casually stops Yamauchi’s chair attack and releases it when Chabashira intervenes. Tells Ayanokōji he cooperated to avoid expulsion and denies provoking Yamauchi out of concern for the class.<\/p><p class=\"with\">with <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Provokes him before and after the results.<span class=\"pg\">p.299–308<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Shows him the message asking classmates not to vote against him.<span class=\"pg\">p.300<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Speaks with him after leaving the classroom.<span class=\"pg\">p.311–312<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y1v10-p200-1\">← Before: Ch.5: Supporting Horikita’s nomination<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v10-p299-1","v":"y1v10","y":1,"o":12,"k":"","w":"yamauchi-haruki ike-kanji sudou-ken","q":"sudo ken epilogue  yamauchi s expulsion sits quietly as koenji provokes yamauchi before the results  receives 21 censure votes  placing second from last  as yamauchi is expelled  leaves the classroom quietly with ike after the results  on monday he appears lacking energy  witnesses his friend s expulsion  shares the aftermath of the vote with him","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v10-p299-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y1v10-p299-1\">Epilogue: Yamauchi’s expulsion<\/a><\/span><span class=\"meta\">Y1V10 · p.299–311<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"setup\">Sits quietly as Kōenji provokes Yamauchi before the results. Receives 21 censure votes, placing second from last, as Yamauchi is expelled. Leaves the classroom quietly with Ike after the results; on Monday he appears lacking energy.<\/p><p class=\"with\">with <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Witnesses his friend’s expulsion.<span class=\"pg\">p.299–306<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Shares the aftermath of the vote with him.<span class=\"pg\">p.306, 311<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v10-p184-1\">← Before: Ch.5: Objection to expelling Yamauchi<\/button><\/div><\/article>"},{"i":"sc-kushida-kikyou-y1v10-p304-1","v":"y1v10","y":1,"o":12,"k":"","w":"ayanokouji-kiyotaka hirata-yousuke kushida-kikyou","q":"kushida kikyo epilogue  results and aftermath is announced as third in class c for praise votes and sighs with relief  on monday after yamauchi s expulsion  kushida s smile has faded in the classroom  places behind him in class c praise votes  places behind him in class c praise votes","h":"<article class=\"card\" id=\"sc-kushida-kikyou-y1v10-p304-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kushida-kikyou.html#sc-kushida-kikyou-y1v10-p304-1\">Epilogue: Results and aftermath<\/a><\/span><span class=\"meta\">Y1V10 · p.304–362<\/span><span class=\"by\">notes on <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/span><\/h3><p class=\"setup\">Is announced as third in Class C for praise votes and sighs with relief. On Monday after Yamauchi’s expulsion, Kushida’s smile has faded in the classroom.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Places behind him in Class C praise votes.<span class=\"pg\">p.304<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Places behind him in Class C praise votes.<span class=\"pg\">p.304<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kushida-kikyou-y1v10-p206-1\">← Before: Ch.5: Retraction under pressure<\/button><\/div><\/article>"},{"i":"sc-manabe-shiho-y1v10-p315-1","v":"y1v10","y":1,"o":12,"k":"","w":"ryuuen-kakeru ibuki-mio manabe-shiho","q":"manabe shiho epilogue  expelled from class d the bulletin board lists manabe shiho as expelled from class d in the class poll  in the flashback  ibuki chooses manabe as the replacement target to be expelled instead of ryuen  expelled from class d in the class poll  expelled in his place as he avoids expulsion  chosen by her as the replacement target","h":"<article class=\"card\" id=\"sc-manabe-shiho-y1v10-p315-1\"><h3><span class=\"ttl\"><a href=\"../../../people/manabe-shiho.html#sc-manabe-shiho-y1v10-p315-1\">Epilogue: Expelled from Class D<\/a><\/span><span class=\"meta\">Y1V10 · p.315–348<\/span><span class=\"by\">notes on <a href=\"../../../people/manabe-shiho.html\">Manabe Shiho<\/a><\/span><\/h3><p class=\"setup\">The bulletin board lists Manabe Shiho as expelled from Class D in the Class Poll. In the flashback, Ibuki chooses Manabe as the replacement target to be expelled instead of Ryūen.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Position<\/span> Expelled from Class D in the Class Poll.<span class=\"pg\">p.315, 348<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Expelled in his place as he avoids expulsion.<span class=\"pg\">p.315, 348<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Chosen by her as the replacement target.<span class=\"pg\">p.338<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-manabe-shiho-y1v10-p240-1\">← Before: Ch.6: Provoking Ibuki<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y1v10-p315-1","v":"y1v10","y":1,"o":12,"k":"","w":"ayanokouji-kiyotaka katsuragi-kouhei manabe-shiho ibuki-mio ishizaki-daichi ryuuen-kakeru","q":"ryuen kakeru epilogue  survival and aftermath remains in school after the class poll  the bulletin board shows manabe shiho expelled from class d instead of him  at the bulletin board  speaks with katsuragi and comments on sakayanagi expelling totsuka  takes ayanokoji behind the school building and asks since when he became a good person  says he had known ichinose was saving points but did not expect ayanokoji s involvement  learns ibuki chose manabe and calls his survival an annoying gift from ishizaki and ibuki  avoids expulsion from class d in the class poll  talks with him about how he was saved  speaks with him at the bulletin board  survives as she is expelled in his place  acknowledges her role in his survival  acknowledges his role in his survival","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y1v10-p315-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y1v10-p315-1\">Epilogue: Survival and aftermath<\/a><\/span><span class=\"meta\">Y1V10 · p.315–348<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Remains in school after the Class Poll; the bulletin board shows Manabe Shiho expelled from Class D instead of him. At the bulletin board, speaks with Katsuragi and comments on Sakayanagi expelling Totsuka. Takes Ayanokōji behind the school building and asks since when he became a good person. Says he had known Ichinose was saving points but did not expect Ayanokōji’s involvement. Learns Ibuki chose Manabe and calls his survival an annoying gift from Ishizaki and Ibuki.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/manabe-shiho.html\">Manabe Shiho<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a><\/p><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Position<\/span> Avoids expulsion from Class D in the Class Poll.<span class=\"pg\">p.315–348<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Talks with him about how he was saved.<span class=\"pg\">p.316–318, 347–348<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Speaks with him at the bulletin board.<span class=\"pg\">p.316–317<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Manabe Shiho<\/b> Survives as she is expelled in his place.<span class=\"pg\">p.315, 348<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Acknowledges her role in his survival.<span class=\"pg\">p.348<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Acknowledges his role in his survival.<span class=\"pg\">p.348<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y1v10-p249-1\">← Before: Ch.6/Epilogue: Added voice lines<\/button><\/div><\/article>"},{"i":"sc-kaneda-satoru-y1v10-p316-1","v":"y1v10","y":1,"o":12,"k":"","w":"kaneda-satoru","q":"kaneda satoru epilogue  class poll result the bulletin board lists kaneda as the class d student with the most praise votes  27  received the most praise votes in class d in the class poll","h":"<article class=\"card\" id=\"sc-kaneda-satoru-y1v10-p316-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kaneda-satoru.html#sc-kaneda-satoru-y1v10-p316-1\">Epilogue: Class Poll result<\/a><\/span><span class=\"meta\">Y1V10 · p.316<\/span><span class=\"by\">notes on <a href=\"../../../people/kaneda-satoru.html\">Kaneda Satoru<\/a><\/span><\/h3><p class=\"setup\">The bulletin board lists Kaneda as the Class D student with the most praise votes (27).<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Position<\/span> Received the most praise votes in Class D in the Class Poll.<span class=\"pg\">p.316<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ibuki-mio-y1v10-p319-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ryuuen-kakeru ishizaki-daichi ichinose-honami ayanokouji-kiyotaka manabe-shiho ibuki-mio","q":"ibuki mio epilogue  saving ryuen  flashback  visits ayanokoji s room with ishizaki at night to ask how to prevent ryuen s expulsion  says she was forced to come along and that ayanokoji would not cooperate  admits she does not want to beg ryuen for his points but later recovers them  calls ayanokoji to report she has obtained all of ryuen s private points and comes to his room with ishizaki  chooses manabe shiho as the replacement target to be expelled instead of ryuen  agrees with ichinose to exchange ryuen s points for class b s 40 praise votes to save him   it  it just pisses me off that he s running away before i can pay him back for this stupid loan i took from him  that s all there is to it  helps save him from expulsion by using his points  works with him to seek help and carry out the plan  negotiates with her to secure praise votes for ryuen  asks for his help and follows his plan  chooses her as the replacement target","h":"<article class=\"card\" id=\"sc-ibuki-mio-y1v10-p319-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y1v10-p319-1\">Epilogue: Saving Ryūen (flashback)<\/a><\/span><span class=\"meta\">Y1V10 · p.319–346<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"setup\">Visits Ayanokōji’s room with Ishizaki at night to ask how to prevent Ryūen’s expulsion. Says she was forced to come along and that Ayanokōji would not cooperate. Admits she does not want to beg Ryūen for his points but later recovers them. Calls Ayanokōji to report she has obtained all of Ryūen’s private points and comes to his room with Ishizaki. Chooses Manabe Shiho as the replacement target to be expelled instead of Ryūen. Agrees with Ichinose to exchange Ryūen’s points for Class B’s 40 praise votes to save him.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/manabe-shiho.html\">Manabe Shiho<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “It… It just pisses me off that he’s running away before I can pay him back for this stupid loan I took from him, that’s all there is to it.”<span class=\"pg\">p.345<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Helps save him from expulsion by using his points.<span class=\"pg\">p.319–346<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Works with him to seek help and carry out the plan.<span class=\"pg\">p.319–346<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Negotiates with her to secure praise votes for Ryūen.<span class=\"pg\">p.342–346<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Asks for his help and follows his plan.<span class=\"pg\">p.319–346<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Manabe Shiho<\/b> Chooses her as the replacement target.<span class=\"pg\">p.338–339<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y1v10-p245-2\">← Before: Ch.6: Recalling Ayanokōji’s words<\/button><\/div><\/article>"},{"i":"sc-ishizaki-daichi-y1v10-p319-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ryuuen-kakeru ibuki-mio ayanokouji-kiyotaka ichinose-honami ishizaki-daichi","q":"ishizaki daichi epilogue  saving ryuen  flashback  comes to ayanokoji s room with ibuki and begs for a way to prevent ryuen s expulsion   please  ayanokoji  tell us how to prevent ryuen san from getting expelled  insists he wants to save ryuen even after ayanokoji explains it is unreasonable  agrees to take responsibility for saving ryuen  knowing someone else must be expelled  agrees to ibuki s choice of manabe as the replacement target and plans to redirect votes  meets ichinose in ayanokoji s room and takes part in the agreement to save ryuen  seeks to save him from expulsion  acts together with her throughout the plan  asks for his help and follows his guidance  participates in the deal with her","h":"<article class=\"card\" id=\"sc-ishizaki-daichi-y1v10-p319-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ishizaki-daichi.html#sc-ishizaki-daichi-y1v10-p319-1\">Epilogue: Saving Ryūen (flashback)<\/a><\/span><span class=\"meta\">Y1V10 · p.319–346<\/span><span class=\"by\">notes on <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a><\/span><\/h3><p class=\"setup\">Comes to Ayanokōji’s room with Ibuki and begs for a way to prevent Ryūen’s expulsion. Insists he wants to save Ryūen even after Ayanokōji explains it is unreasonable. Agrees to take responsibility for saving Ryūen, knowing someone else must be expelled. Agrees to Ibuki’s choice of Manabe as the replacement target and plans to redirect votes. Meets Ichinose in Ayanokōji’s room and takes part in the agreement to save Ryūen.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ishizaki Daichi<\/b> “Please, Ayanokōji! Tell us how to prevent Ryūen-san from getting expelled!”<span class=\"pg\">p.323<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Seeks to save him from expulsion.<span class=\"pg\">p.319–346<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Acts together with her throughout the plan.<span class=\"pg\">p.319–346<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Asks for his help and follows his guidance.<span class=\"pg\">p.319–346<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Participates in the deal with her.<span class=\"pg\">p.342–346<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ishizaki-daichi-y1v10-p239-1\">← Before: Ch.6: Trying to save Ryūen<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ishizaki-daichi-y1v10-p331-1\">→ After: Epilogue: Saving Ryūen<\/button><\/div><\/article>"},{"i":"sc-ishizaki-daichi-y1v10-p331-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ibuki-mio ishizaki-daichi","q":"ishizaki daichi epilogue  saving ryuen says he will not take ryuen s private points either   i won t either  threatens to get at least one hit on ayanokoji   even if i m no match for him  i ll at least get one hit in  agrees with her to recover nothing and threatens ayanokoji","h":"<article class=\"card\" id=\"sc-ishizaki-daichi-y1v10-p331-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ishizaki-daichi.html#sc-ishizaki-daichi-y1v10-p331-1\">Epilogue: Saving Ryūen<\/a><\/span><span class=\"meta\">Y1V10 · p.331, 332<\/span><span class=\"by\">notes on <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a><\/span><\/h3><p class=\"setup\">Says he will not take Ryūen’s private points either. Threatens to get at least one hit on Ayanokōji.<\/p><p class=\"with\">with <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ishizaki Daichi<\/b> “I won’t either!”<span class=\"pg\">p.331<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ishizaki Daichi<\/b> “Even if I’m no match for him, I’ll at least get one hit in!”<span class=\"pg\">p.332<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Agrees with her to recover nothing and threatens Ayanokōji.<span class=\"pg\">p.331–332<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ishizaki-daichi-y1v10-p319-1\">← Before: Epilogue: Saving Ryūen (flashback)<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v10-p342-1","v":"y1v10","y":1,"o":12,"k":"","w":"ayanokouji-kiyotaka ibuki-mio ishizaki-daichi ryuuen-kakeru kanzaki-ryuuji ichinose-honami","q":"ichinose honami epilogue  saving ryuen and class b  flashback and call  comes to ayanokoji s room and meets ibuki and ishizaki to discuss saving ryuen  agrees to ask class b to cast 40 praise votes for ryuen in exchange for ryuen s private points  says she decided to accept the deal because their sincerity was real  receives the transferred points and confirms she has twenty million in her account  calls ayanokoji to report class b avoided any expulsion by paying 20 million points to negate kanzaki s expulsion  reflects that she was relieved not to have to accept nagumo s condition and discusses what she would have done otherwise  makes the deal through him and later reports the outcome  accepts her points and agrees to save ryuen  participates in the agreement with him  uses class b s praise votes to save him from expulsion  reports that class b saved him by paying the override","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v10-p342-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y1v10-p342-1\">Epilogue: Saving Ryūen and Class B (flashback and call)<\/a><\/span><span class=\"meta\">Y1V10 · p.342–353<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><p class=\"setup\">Comes to Ayanokōji’s room and meets Ibuki and Ishizaki to discuss saving Ryūen. Agrees to ask Class B to cast 40 praise votes for Ryūen in exchange for Ryūen’s private points. Says she decided to accept the deal because their sincerity was real. Receives the transferred points and confirms she has twenty million in her account. Calls Ayanokōji to report Class B avoided any expulsion by paying 20 million points to negate Kanzaki’s expulsion. Reflects that she was relieved not to have to accept Nagumo’s condition and discusses what she would have done otherwise.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/p><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Makes the deal through him and later reports the outcome.<span class=\"pg\">p.342–353<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Accepts her points and agrees to save Ryūen.<span class=\"pg\">p.342–346<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Participates in the agreement with him.<span class=\"pg\">p.342–346<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Uses Class B’s praise votes to save him from expulsion.<span class=\"pg\">p.343–350<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Reports that Class B saved him by paying the override.<span class=\"pg\">p.349<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v10-p253-1\">← Before: Ch.6/Epilogue: Added voice lines<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v10-p366-1\">→ After: Short Stories<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v10-p366-1","v":"y1v10","y":1,"o":12,"k":"","w":"ichinose-honami horikita-suzune sakayanagi-arisu ayanokouji-kiyotaka","q":"ayanokoji kiyotaka short stories meets ichinose in the morning and agrees to walk to school with her  in horikita s perspective after the exam  ayanokoji speaks briefly with koenji and walks away as horikita stops him  meets sakayanagi  who asks to postpone their duel past the class poll  receives ichinose in his room at night and responds to her questions  walks to school with her and talks with her in his room  is stopped by her in the corridor after the exam  agrees to her request to postpone their match","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v10-p366-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v10-p366-1\">Short Stories<\/a><\/span><span class=\"meta\">Y1V10 · p.366–376<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Meets Ichinose in the morning and agrees to walk to school with her. In Horikita’s perspective after the exam, Ayanokōji speaks briefly with Kōenji and walks away as Horikita stops him. Meets Sakayanagi, who asks to postpone their duel past the Class Poll. Receives Ichinose in his room at night and responds to her questions.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Walks to school with her and talks with her in his room.<span class=\"pg\">p.366–369, 375–376<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Is stopped by her in the corridor after the exam.<span class=\"pg\">p.370–371<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Agrees to her request to postpone their match.<span class=\"pg\">p.373–374<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v10-p287-1\">← Before: Epilogue: Added voice lines<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v10-p366-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ayanokouji-kiyotaka ichinose-honami","q":"ichinose honami short stories waits near the dorms in the cold morning to ambush ayanokoji so she can talk to him  greets ayanokoji and  flustered  asks to walk to school together   good morning  ayanokouji kun  walks beside him to school  noticing her feelings have changed since speaking with nagumo  visits ayanokoji s room late at night after their discussion and asks if he is someone amazing   ayanokouji kun  are you perhaps someone really amazing  reflects on his intelligence and her heartbeat  aware they will remain rivals as classmates in different classes  walks to school with him and later visits his room","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v10-p366-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y1v10-p366-1\">Short Stories<\/a><\/span><span class=\"meta\">Y1V10 · p.366–369, 375–376<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><p class=\"setup\">Waits near the dorms in the cold morning to ambush Ayanokōji so she can talk to him. Greets Ayanokōji and, flustered, asks to walk to school together. Walks beside him to school, noticing her feelings have changed since speaking with Nagumo. Visits Ayanokōji’s room late at night after their discussion and asks if he is someone amazing. Reflects on his intelligence and her heartbeat, aware they will remain rivals as classmates in different classes.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “Good morning— Ayanokouji-kun!”<span class=\"pg\">p.367<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “Ayanokouji-kun, are you perhaps someone really amazing?”<span class=\"pg\">p.375<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Walks to school with him and later visits his room.<span class=\"pg\">p.366–369, 375–376<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v10-p342-1\">← Before: Epilogue: Saving Ryūen and Class B (flashback and call)<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y1v10-p370-1","v":"y1v10","y":1,"o":12,"k":"","w":"ayanokouji-kiyotaka karuizawa-kei horikita-suzune","q":"horikita suzune short stories  neighbour after the exam  follows ayanokoji in the corridor and grabs his hand to stop him  asks him how much he knew  he repeats that he did not participate in the special exam in the literal sense  speaks with karuizawa about ayanokoji and trust  stops him and questions him after the exam  talks with her about ayanokoji","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v10-p370-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v10-p370-1\">Short Stories: Neighbour<\/a><\/span><span class=\"meta\">Y1V10 · p.370–372<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">After the exam, follows Ayanokōji in the corridor and grabs his hand to stop him. Asks him how much he knew; he repeats that he did not participate in the special exam in the literal sense. Speaks with Karuizawa about Ayanokōji and trust.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Stops him and questions him after the exam.<span class=\"pg\">p.370–371<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Talks with her about Ayanokōji.<span class=\"pg\">p.371–372<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v10-p286-1\">← Before: Epilogue: Morning vote and aftermath<\/button><\/div><\/article>"},{"i":"sc-karuizawa-kei-y1v10-p371-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"horikita-suzune ayanokouji-kiyotaka karuizawa-kei","q":"karuizawa kei short stories  neighbour approaches horikita in the corridor and asks what she was talking about with ayanokoji  tells horikita that if she is too scared  her relationship with ayanokoji will never begin  then returns to her friends   if you are that scared  your relationship with him will never begin  speaks with her about ayanokoji  discusses him with horikita","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y1v10-p371-1\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y1v10-p371-1\">Short Stories: Neighbour<\/a><\/span><span class=\"meta\">Y1V10 · p.371–372<\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><p class=\"setup\">Approaches Horikita in the corridor and asks what she was talking about with Ayanokōji. Tells Horikita that if she is too scared, her relationship with Ayanokōji will never begin, then returns to her friends.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “If you are that scared, your relationship with him will never begin”.<span class=\"pg\">p.372<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Speaks with her about Ayanokōji.<span class=\"pg\">p.371–372<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Discusses him with Horikita.<span class=\"pg\">p.371–372<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y1v10-p168-2\">← Before: Ch.4: Warning by phone<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-arisu-y1v10-p373-1","v":"y1v10","y":1,"o":12,"k":"spoken","w":"ayanokouji-kiyotaka sakayanagi-arisu","q":"sakayanagi arisu short stories meets ayanokoji privately after sending kamuro away and asks to postpone their duel past the class poll   won t you accept  this deal  promises not to give ayanokoji any censure votes during the exam to earn his trust  proposes postponing their match and offers reassurance","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y1v10-p373-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y1v10-p373-1\">Short Stories<\/a><\/span><span class=\"meta\">Y1V10 · p.373–374<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><p class=\"setup\">Meets Ayanokōji privately after sending Kamuro away and asks to postpone their duel past the Class Poll. Promises not to give Ayanokōji any censure votes during the exam to earn his trust.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “Won’t you accept, this deal?”<span class=\"pg\">p.373<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Proposes postponing their match and offers reassurance.<span class=\"pg\">p.373–374<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y1v10-p292-1\">← Before: Epilogue: Results and the acting director<\/button><\/div><\/article>"}];
